import time
import signal
import logging
from typing import Optional, Tuple

import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class Oscilloscope:
    """Oscilloscope sampler for two ADS1115 ADC channels on a Raspberry Pi."""

    def __init__(self, i2c_bus: int = 1, gain: int = 1, sample_rate: float = 10.0) -> None:
        self.sample_rate = sample_rate
        self._running = False
        self._adc: Optional[ADS.ADS1115] = None
        self._channels: Tuple[Optional[AnalogIn], Optional[AnalogIn]] = (None, None)
        self._i2c: Optional[busio.I2C] = None
        self._logger = logging.getLogger(self.__class__.__name__)

        try:
            self._i2c = busio.I2C(board.SCL, board.SDA, frequency=100_000)
            self._adc = ADS.ADS1115(self._i2c, address=0x48)
            self._adc.gain = gain
            self._adc.mode = ADS.MODE_CONTINUOUS
            self._channels = (AnalogIn(self._adc, ADS.P0), AnalogIn(self._adc, ADS.P1))
            self._logger.info(
                "ADS1115 initialized on I2C bus %d, gain=%d, channels P0/P1", i2c_bus, gain
            )
        except Exception as exc:
            self._logger.error("Failed to initialize ADS1115: %s", exc)
            self.close()
            raise

    def close(self) -> None:
        """Release ADC, I2C bus and channel objects."""
        if self._adc is not None:
            try:
                self._adc = None
            except Exception as exc:
                self._logger.error("Error releasing ADC: %s", exc)
        if self._i2c is not None:
            try:
                self._i2c.deinit()
                self._i2c = None
            except Exception as exc:
                self._logger.error("Error deinitializing I2C: %s", exc)
        self._channels = (None, None)

    def _read_channels(self) -> Tuple[Optional[float], Optional[float]]:
        """Return (ch0_v, ch1_v) or (None, None) on error."""
        if self._adc is None or self._channels[0] is None or self._channels[1] is None:
            return None, None
        try:
            v0 = self._channels[0].voltage
            v1 = self._channels[1].voltage
            return v0, v1
        except Exception as exc:
            self._logger.error("Error reading ADC channels: %s", exc)
            return None, None

    def run(self) -> None:
        """Continuously sample and print timestamped voltage values."""
        self._running = True
        self._logger.info("Starting oscilloscope sampling at %.1f Hz", self.sample_rate)

        try:
            while self._running:
                loop_start = time.monotonic()
                v0, v1 = self._read_channels()
                if v0 is not None and v1 is not None:
                    timestamp = time.monotonic()
                    print(f"{timestamp:.6f},{v0:.6f},{v1:.6f}")
                else:
                    self._logger.warning("Skipping sample due to read error")
                elapsed = time.monotonic() - loop_start
                sleep_time = max(0.0, (1.0 / self.sample_rate) - elapsed)
                time.sleep(sleep_time)
        except KeyboardInterrupt:
            self._logger.info("Oscilloscope stopped by user (KeyboardInterrupt)")
        except Exception as exc:
            self._logger.error("Unexpected error in sampling loop: %s", exc)
        finally:
            self._running = False
            self.close()
            self._logger.info("Oscilloscope stopped and resources released")

    def stop(self) -> None:
        """Signal the sampling loop to stop."""
        self._running = False


def _signal_handler(signum, frame, osc: Optional[Oscilloscope]) -> None:
    if osc is not None:
        osc.stop()


def main() -> None:
    osc = Oscilloscope(i2c_bus=1, gain=1, sample_rate=10.0)
    signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, osc))
    signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, osc))
    osc.run()


if __name__ == "__main__":
    main()

