import argparse
import logging
import queue
import signal
import sys
import threading
import time

try:
    import spidev
except ImportError:
    spidev = None

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None


class SoundSensor:
    """Reads a digital or analog sound sensor and logs events with debounce."""

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.running = True
        self.lock = threading.Lock()
        self.spi_lock = threading.Lock()
        self.spi_initialized = False

        if self.sensor_type == "digital":
            if len(self.gpio_pins) != 1:
                raise ValueError("digital sensor must have exactly one GPIO pin")
            self.digital_pin = self.gpio_pins[0]
            if GPIO is None:
                raise RuntimeError("RPi.GPIO not available; run on a Raspberry Pi")
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.digital_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        elif self.sensor_type == "analog":
            if len(self.channels) != 1:
                raise ValueError("analog sensor must have exactly one MCP3008 channel")
            if spidev is None:
                raise RuntimeError("spidev not available; install python3-spidev")
            self.spi = spidev.SpiDev()
            try:
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
                self.spi_initialized = True
            except Exception as e:
                raise RuntimeError(f"Failed to initialize SPI: {e}")
        else:
            raise ValueError(f"Invalid sensor_type: {self.sensor_type}")

    def read_sensor(self):
        """Read the sensor and return the value or None on error."""
        if self.sensor_type == "digital":
            try:
                return GPIO.input(self.digital_pin)
            except Exception as e:
                logging.error(f"Error reading digital sensor {self.sensor_id}: {e}")
                return None
        elif self.sensor_type == "analog":
            with self.spi_lock:
                if not self.spi_initialized:
                    logging.error(f"SPI not initialized for sensor {self.sensor_id}")
                    return None
                try:
                    adc = self._read_mcp3008(self.channels[0])
                    return adc
                except Exception as e:
                    logging.error(f"Error reading analog sensor {self.sensor_id}: {e}")
                    return None
        return None

    def _read_mcp3008(self, channel):
        """Read a single-ended channel from the MCP3008."""
        if not 0 <= channel <= 7:
            raise ValueError(f"Invalid MCP3008 channel: {channel}")
        r = self.spi.xfer2([1, (8 + channel) << 4, 0])
        return ((r[1] & 3) << 8) + r[2]

    def detect_event(self):
        """Debounce and log an event if the sensor exceeds the threshold."""
        with self.lock:
            if not self.running:
                return
            value = self.read_sensor()
            if value is None:
                return
            if value >= self.threshold:
                logging.info(f"Event detected by sensor {self.sensor_id}: value={value}")
                if self.log_queue:
                    self.log_queue.put(f"Event detected by sensor {self.sensor_id}: value={value}")
                time.sleep(0.1)

    def run(self):
        """Continuously sample the sensor at the configured rate."""
        if self.sensor_type == "digital":
            logging.info(f"Starting digital sensor {self.sensor_id} on GPIO {self.digital_pin}")
        elif self.sensor_type == "analog":
            logging.info(f"Starting analog sensor {self.sensor_id} on MCP3008 channel {self.channels[0]}")
        while self.running:
            time.sleep(1 / self.sample_rate)
            self.detect_event()

    def stop(self):
        """Signal the sensor to stop and release resources."""
        self.running = False
        if self.sensor_type == "analog":
            with self.spi_lock:
                if self.spi:
                    try:
                        self.spi.close()
                    except Exception:
                        pass
                    self.spi_initialized = False


def parse_arguments():
    parser = argparse.ArgumentParser(description="Sound sensor monitoring system")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"])
    parser.add_argument("--threshold", type=int, required=True)
    parser.add_argument("--sample_rate", type=int, required=True)
    parser.add_argument("--log_file", required=True)
    parser.add_argument("--gpio_pins", type=int, nargs="+", required=True)
    parser.add_argument("--channels", type=int, nargs="+", required=True)
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", type=int, nargs="+", required=True)
    return parser.parse_args()


def main():
    args = parse_arguments()
    logging.basicConfig(filename=args.log_file, level=logging.INFO,
                        format="%(asctime)s - %(levelname)s - %(message)s")
    logging.info("Starting sound sensor monitoring system")
    logging.info(f"Arguments: {args}")

    sensor_instances = []
    for i, sensor_id in enumerate(args.sensor_ids):
        try:
            sensor = SoundSensor(
                sensor_id=sensor_id,
                sensor_type=args.sensor_type,
                threshold=args.threshold,
                sample_rate=args.sample_rate,
                gpio_pins=[args.gpio_pins[i]] if args.sensor_type == "digital" else args.gpio_pins,
                channels=[args.channels[i]] if args.sensor_type == "analog" else args.channels,
                spi_speed=args.spi_speed,
            )
            sensor_instances.append(sensor)
        except Exception as e:
            logging.error(f"Failed to create sensor {sensor_id}: {e}")
            sys.exit(1)

    threads = []
    for sensor in sensor_instances:
        t = threading.Thread(target=sensor.run, daemon=True)
        t.start()
        threads.append(t)

    def signal_handler(signum, frame):
        logging.info("Received signal, shutting down...")
        for sensor in sensor_instances:
            sensor.stop()
        for t in threads:
            t.join(timeout=2)
        logging.info("Shutdown complete")
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        signal_handler(signal.SIGINT, None)


if __name__ == "__main__":
    main()

