        try:
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = SPI_SPEED_HZ
            self.spi.mode = 0
        except OSError as e:
            raise RuntimeError(f"Failed to open SPI bus {spi_bus} device {spi_device}: {e}") from e

    def read_raw(self):
        """Reads a raw 10-bit value from the configured ADC channel."""
        # MCP3008 single-ended read command: start bit, single/diff=1, channel bits
        command = [1, (8 + self.channel) << 4, 0]
        try:
            response = self.spi.xfer2(command)
        except OSError as e:
            raise RuntimeError(f"SPI transfer failed on channel {self.channel}: {e}") from e
        # Extract 10-bit value from response bytes 1 and 2
        raw_value = ((response[1] & 0x03) << 8) | response[2]
        return raw_value

    def estimate_ppm(self, raw_value):
        """Converts a raw ADC reading to an estimated gas concentration in ppm."""
        # Placeholder calibration curve for MQ-2 (adjust as needed)
        # This is a simplified linear mapping; a real implementation would use
        # a lookup table or calibration data.
        ppm = (raw_value / 1023.0) * 1000.0
        return round(ppm, 1)

    def close(self):
        """Closes the SPI connection."""
        try:
            self.spi.close()
        except Exception:
            pass


def determine_alert_level(ppm_value):
    """Determines the alert level based on the gas concentration."""
    if ppm_value < SAFE_THRESHOLD_PPM:
        return "safe"
    elif ppm_value < WARNING_THRESHOLD_PPM:
        return "warning"
    else:
        return "danger"


def main():
    monitor = None
    try:
        monitor = GasSensorMonitor(SPI_BUS, SPI_DEVICE, GAS_SENSOR_CHANNEL)
        for sample_index in range(NUM_SAMPLES):
            try:
                raw = monitor.read_raw()
                ppm = monitor.estimate_ppm(raw)
                alert = determine_alert_level(ppm)
                print(f"Sample {sample_index + 1}/{NUM_SAMPLES}: Raw={raw}, PPM={ppm}, Alert={alert}")
            except RuntimeError as e:
                print(f"Error during sample {sample_index + 1}: {e}", file=sys.stderr)
            if sample_index < NUM_SAMPLES - 1:
                time.sleep(SAMPLE_INTERVAL_S)
    except RuntimeError as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if monitor is not None:
            monitor.close()


if __name__ == "__main__":
    # Handle SIGINT and SIGTERM for clean shutdown
    def signal_handler(sig, frame):
        print("\nInterrupt received, exiting...")
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

