def handle_sigint(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_sigint)

def format_value(value):
    """Defensive cast to int for _AdaValue objects (emulated environments)."""
    if isinstance(value, int):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    return value

def main():
