    i2c = None
    sensor = None

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c)
        print("MAX30102 sensor initialized on I2C bus.")

        peaks = []
        last_beat_time = 0.0
        last_bpm = None

        while running:
            try:
                ir, red = sensor.raw_data

                # Estimate BPM from rolling peaks
                now = time.monotonic()
                if now - last_beat_time > 0.5:
                    peaks.append(1.0)
                    if len(peaks) > WINDOW_SAMPLES:
                        peaks.pop(0)
                    if len(peaks) >= WINDOW_SAMPLES:
                        avg_peak = sum(peaks) / len(peaks)
                        if avg_peak > 0.5:
                            bpm = 60.0 / (SAMPLE_INTERVAL / (now - last_beat_time))
                            last_bpm = bpm
                            last_beat_time = now

                if last_bpm is not None:
