                print(f"I2C bus error: {e}. Retrying...")
                time.sleep(0.5)
            except Exception as e:
                print(f"Unexpected error: {e}")
                time.sleep(1.0)

    except Exception as e:
        print(f"Initialization error: {e}")
    finally:
        if sensor is not None:
            try:
                sensor.shutdown()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

