import signal
import sys
import cv2
from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

picam2 = None
try:
    picam2 = Picamera2()
    config = picam2.create_preview_configuration(
        main={"size": (640, 480), "format": "BGR888"}
    )
    picam2.configure(config)
    picam2.start()
except Exception as e:
    print(f"Error initializing camera: {e}", file=sys.stderr)
    if picam2 is not None:
        try:
            picam2.close()
        except Exception:
            pass
    sys.exit(1)

face_cascade = cv2.CascadeClassifier(
    cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
)
if face_cascade.empty():
    print("Error: Could not load frontal face cascade.", file=sys.stderr)
    picam2.stop()
    picam2.close()
    sys.exit(1)

eye_cascade = cv2.CascadeClassifier(
    cv2.data.haarcascades + "haarcascade_eye.xml"
)
if eye_cascade.empty():
    print("Error: Could not load eye cascade.", file=sys.stderr)
    picam2.stop()
    picam2.close()
    sys.exit(1)

try:
    while running:
        try:
            frame = picam2.capture_array()
        except Exception as e:
            print(f"Error capturing frame: {e}", file=sys.stderr)
            break

        if frame is None:
            continue

        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        faces = face_cascade.detectMultiScale(
            gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30)
        )

        for (x, y, w, h) in faces:
            cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
            roi_gray = gray[y : y + h, x : x + w]
            eyes = eye_cascade.detectMultiScale(
                roi_gray, scaleFactor=1.1, minNeighbors=3, minSize=(20, 20)
            )
            for (ex, ey, ew, eh) in eyes:
                cv2.rectangle(
                    frame, (x + ex, y + ey), (x + ex + ew, y + ey + eh), (0, 0, 255), 2
                )

        cv2.imshow("Face and Eye Detection", frame)

        if cv2.waitKey(1) & 0xFF == ord("q"):
            break

except Exception as e:
    print(f"Runtime error: {e}", file=sys.stderr)

finally:
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception:
            pass
        try:
            picam2.close()
        except Exception:
            pass
    cv2.destroyAllWindows()

