import io
import time
import json
import signal
import logging
from PIL import Image
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import JpegEncoder
from picamera2.outputs import FileOutput
from libcamera import controls

# ---------------------------------------------------------------------------
# Configuration (config.json)
# ---------------------------------------------------------------------------
CONFIG_FILE = "config.json"

DEFAULT_CONFIG = {
    "model_path": "model.tflite",
    "threshold": 0.5,
    "gpio_led": 17,
    "gpio_door_control": None,
    "camera_resolution": [224, 224],
}

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Global resources for cleanup
# ---------------------------------------------------------------------------
picam2 = None
led = None
door = None
running = True


def load_config(path: str) -> dict:
    """Load and validate the configuration file."""
    try:
        with open(path, "r", encoding="utf-8") as f:
            cfg = json.load(f)
        # Merge with defaults so missing keys are filled in
        cfg = {**DEFAULT_CONFIG, **cfg}
        # Validate required keys
        if not isinstance(cfg["model_path"], str) or not cfg["model_path"]:
            raise ValueError("model_path must be a non-empty string")
        if not isinstance(cfg["threshold"], (int, float)) or cfg["threshold"] < 0:
            raise ValueError("threshold must be a non-negative number")
        if not isinstance(cfg["camera_resolution"], list) or len(cfg["camera_resolution"]) != 2:
            raise ValueError("camera_resolution must be a list of two integers")
        if not isinstance(cfg["gpio_led"], int) or cfg["gpio_led"] < 0:
            raise ValueError("gpio_led must be a non-negative integer")
        if cfg["gpio_door_control"] is not None and not isinstance(cfg["gpio_door_control"], int):
            raise ValueError("gpio_door_control must be an integer or None")
        return cfg
    except FileNotFoundError:
        logger.warning("config.json not found; using defaults.")
        return DEFAULT_CONFIG.copy()
    except (json.JSONDecodeError, ValueError) as e:
        logger.error(f"Invalid config.json: {e}; using defaults.")
        return DEFAULT_CONFIG.copy()


def initialize_camera(resolution: list) -> Picamera2:
    """Initialize the Raspberry Pi camera with the requested resolution."""
    global picam2
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": tuple(resolution), "format": "RGB888"},
            controls={"FrameRate": 30.0},
        )
        picam2.configure(config)
        picam2.set_controls({"AfMode": controls.AfModeEnum.Continuous})
        picam2.start()
        logger.info(f"Camera initialized at {resolution[0]}x{resolution[1]}")
        return picam2
    except Exception as e:
        logger.error(f"Camera initialization failed: {e}")
        raise


def capture_image(camera: Picamera2) -> Image.Image:
    """Capture a single frame from the camera and return it as a PIL Image."""
    try:
        buffer = io.BytesIO()
        camera.capture_file(buffer, format="jpeg")
        buffer.seek(0)
        return Image.open(buffer)
    except Exception as e:
        logger.error(f"Image capture failed: {e}")
        raise


def preprocess_image(image: Image.Image) -> np.ndarray:
    """Resize and convert the image to a normalized float32 tensor."""
    try:
        img = image.resize((224, 224), Image.Resampling.BILINEAR)
        img = np.array(img, dtype=np.float32)
        img = np.expand_dims(img, axis=0)
        img = img / 255.0
        return img
    except Exception as e:
        logger.error(f"Image preprocessing failed: {e}")
        raise


def run_inference(model_path: str, threshold: float, image: np.ndarray) -> bool:
    """Run TFLite inference and return True if a bird is detected above threshold."""
    try:
        import tflite_runtime.interpreter as tflite
        interpreter = tflite.Interpreter(model_path=model_path)
        interpreter.allocate_tensors()
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        interpreter.set_tensor(input_details[0]["index"], image)
        interpreter.invoke()
        output = interpreter.get_tensor(output_details[0]["index"])
        return bool(np.any(output > threshold))
    except Exception as e:
        logger.error(f"Inference failed: {e}")
        return False


def indicate_bird(led_pin: int) -> None:
    """Drive the indicator LED HIGH for 1 second, then LOW."""
    global led
    try:
        if led is None:
            from gpiozero import LED
            led = LED(led_pin)
        led.on()
        time.sleep(1.0)
        led.off()
    except Exception as e:
        logger.error(f"LED control failed: {e}")


def control_door(door_pin: int, open_door: bool) -> None:
    """Control the feeder door actuator via gpiozero OutputDevice."""
    global door
    try:
        if door is None:
            from gpiozero import OutputDevice
            door = OutputDevice(door_pin, active_high=True, initial_value=False)
        if open_door:
            door.on()
        else:
            door.off()
    except Exception as e:
        logger.error(f"Door control failed: {e}")


def cleanup() -> None:
    """Release all hardware resources cleanly."""
    global picam2, led, door, running
    running = False
    logger.info("Cleaning up resources...")
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception:
            pass
        picam2 = None
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if door is not None:
        try:
            door.close()
        except Exception:
            pass
        door = None
    logger.info("Cleanup complete.")


def signal_handler(signum, frame) -> None:
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    logger.info(f"Received signal {signum}, shutting down...")
    cleanup()
    raise SystemExit(0)


def main() -> None:
    """Main entry point: load config, init camera, run detection loop."""
    global running
    config = load_config(CONFIG_FILE)
    camera_resolution = config["camera_resolution"]
    model_path = config["model_path"]
    threshold = config["threshold"]
    led_pin = config["gpio_led"]
    door_pin = config["gpio_door_control"]

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        camera = initialize_camera(camera_resolution)
    except Exception:
        logger.error("Camera initialization failed; aborting.")
        return

    try:
        while running:
            try:
                image = capture_image(camera)
                preprocessed = preprocess_image(image)
                detected = run_inference(model_path, threshold, preprocessed)
                if detected:
                    logger.info("Bird detected!")
                    indicate_bird(led_pin)
                    if door_pin is not None:
                        control_door(door_pin, open_door=True)
                time.sleep(0.1)
            except Exception as e:
                logger.error(f"Loop iteration failed: {e}")
                time.sleep(0.1)
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

