import time
import signal
import threading
import queue
import logging
from PIL import Image
import numpy as np
import cv2
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class Camera:
    def __init__(self, config):
        self.config = config
        self.camera = None
        self.running = False
        self.frame = None
        self.grabbed = False
        self.vs = None
        self._lock = threading.Lock()

    def initialize(self):
        try:
            if self.config.get('camera_type') == 'picamera':
                from picamera2 import Picamera2
                self.camera = Picamera2()
                self.camera.configure(self.camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
                self.camera.start()
                time.sleep(2.0)
                logging.info("PiCamera initialized successfully.")
            elif self.config.get('camera_type') == 'opencv':
                self.vs = cv2.VideoCapture(0)
                if not self.vs.isOpened():
                    raise IOError("Cannot open webcam")
                logging.info("OpenCV camera initialized successfully.")
            else:
                logging.error("Invalid camera type specified in configuration.")
                return False
            return True
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            return False

    def read(self):
        with self._lock:
            if not self.grabbed or not self.frame:
                return None, False
            frame = self.frame.copy()
            self.grabbed, self.frame = self.capture_frame()
            return frame, self.grabbed

    def capture_frame(self):
        if self.config.get('camera_type') == 'picamera':
            try:
                frame = self.camera.capture_array()
                if frame is None:
                    logging.warning("Picamera returned None frame.")
                    return False, None
                return True, frame
            except Exception as e:
                logging.error(f"Error capturing frame from PiCamera: {e}")
                return False, None
        elif self.config.get('camera_type') == 'opencv':
            try:
                ret, frame = self.vs.read()
                if not ret or frame is None:
                    logging.warning("OpenCV frame capture failed.")
                    return False, None
                return True, frame
            except Exception as e:
                logging.error(f"Error capturing frame from OpenCV: {e}")
                return False, None
        return False, None

    def start(self):
        if self.running:
            return
        self.running = True
        if self.config.get('camera_type') == 'picamera':
            self.thread = threading.Thread(target=self.update, daemon=True)
        elif self.config.get('camera_type') == 'opencv':
            self.thread = threading.Thread(target=self.update, daemon=True)
        self.thread.start()

    def update(self):
        while self.running:
            try:
                if self.config.get('camera_type') == 'picamera':
                    frame = self.capture_frame()
                    if frame[0]:
                        self.frame = frame[1]
                        self.grabbed = frame[0]
                elif self.config.get('camera_type') == 'opencv':
                    ret, frame = self.vs.read()
                    if ret and frame is not None:
                        self.frame = frame
                        self.grabbed = ret
            except Exception as e:
                logging.error(f"Error updating camera: {e}")
                time.sleep(0.1)

    def stop(self):
        self.running = False
        if self.config.get('camera_type') == 'picamera':
            if self.camera:
                self.camera.stop()
        elif self.config.get('camera_type') == 'opencv':
            if self.vs:
                self.vs.release()
        self.thread.join()

class LED:
    def __init__(self, gpio_pin):
        self.gpio_pin = gpio_pin
        self.timer = None
        self._lock = threading.Lock()

    def trigger_alert(self, duration):
        with self._lock:
            if self.timer:
                self.timer.cancel()
            self.timer = threading.Timer(duration, self._turn_off)
            self.timer.start()
            GPIO.output(self.gpio_pin, GPIO.HIGH)
            logging.info(f"LED triggered on GPIO {self.gpio_pin} for {duration} seconds.")

    def _turn_off(self):
        GPIO.output(self.gpio_pin, GPIO.LOW)
        logging.info(f"LED turned off on GPIO {self.gpio_pin}.")

    def cleanup(self):
        with self._lock:
            if self.timer:
                self.timer.cancel()
            GPIO.cleanup(self.gpio_pin)

def main():
    config = None
    try:
        with open('config.json', 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        logging.error("Configuration file not found.")
        return
    except json.JSONDecodeError:
        logging.error("Invalid JSON format in configuration file.")
        return

    camera = Camera(config)
    if not camera.initialize():
        return

    gpio_pin = config.get('gpio_pin')
    if gpio_pin is None:
        logging.error("GPIO pin not specified in configuration.")
        camera.stop()
        return

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(gpio_pin, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        logging.error(f"Error setting up GPIO pin {gpio_pin}: {e}")
        camera.stop()
        return

    led = LED(gpio_pin)
    frame_queue = queue.Queue(maxsize=config.get('frame_queue_size', 50))

    def signal_handler(sig, frame):
        logging.info("SIGINT received, shutting down...")
        camera.stop()
        led.cleanup()
        GPIO.cleanup()
        exit(0)

    signal.signal(signal.SIGINT, signal_handler)

    camera.start()

    try:
        while True:
            frame, grabbed = camera.read()
            if not grabbed:
                logging.warning("Failed to grab frame from camera.")
                time.sleep(0.1)
                continue

            try:
                frame_queue.put(frame, block=False)
            except queue.Full:
                try:
                    frame_queue.get_nowait()
                    frame_queue.put(frame, block=False)
                    logging.warning("Frame queue is full, dropping oldest frame.")
                except queue.Empty:
                    logging.error("Frame queue is unexpectedly empty after attempting to remove a frame.")
                    continue

            if frame_queue.qsize() > config.get('frame_queue_size', 50):
                try:
                    frame_queue.get_nowait()
                except queue.Empty:
                    pass

            if frame_queue.qsize() > 0:
                try:
                    frame = frame_queue.get_nowait()
                except queue.Empty:
                    continue

                if frame is None:
                    continue

                try:
                    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                    gray = cv2.GaussianBlur(gray, (21, 21), 0)
                    if not led.timer:
                        if frame_queue.qsize() > config.get('motion_detection_threshold', 10):
                            led.trigger_alert(config.get('led_duration', 2))
                except Exception as e:
                    logging.error(f"Error processing frame: {e}")
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        camera.stop()
        led.cleanup()
        GPIO.cleanup()

if __name__ == '__main__':
    main()

