import signal
import sys
import time
import smbus

I2C_BUS = 1
PCF8574_ADDR = 0x3F
INT_PIN = 17
DEBOUNCE_S = 0.05
POLL_INTERVAL_S = 1.0

running = True
bus = None


def cleanup():
    global bus
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
        bus = None


def handle_sigterm(signum, frame):
    global running
    running = False


def read_proximity():
    try:
        return bus.read_byte(PCF8574_ADDR)
    except OSError as exc:
        print(f"I2C read error: {exc}", file=sys.stderr)
        return None


def on_interrupt():
    time.sleep(DEBOUNCE_S)
    val = read_proximity()
    if val is None:
        return
    for bit in range(8):
        if (val >> bit) & 1:
            continue
        print(f"Obstacle detected by sensor {bit}")


def main():
    global bus
    signal.signal(signal.SIGTERM, handle_sigterm)
    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Failed to open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)
    try:
        bus.write_byte(PCF8574_ADDR, 0xFF)
        bus.write_byte(PCF8574_ADDR, 0x00)
        bus.write_byte(PCF8574_ADDR, 0xFF)
        bus.write_byte(PCF8574_ADDR, 0x00)
    except OSError as exc:
        print(f"Failed to initialize PCF8574 at 0x{PCF8574_ADDR:02X}: {exc}", file=sys.stderr)
        sys.exit(1)
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(INT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.add_event_detect(INT_PIN, GPIO.FALLING, callback=on_interrupt, bouncetime=200)
        print("Monitoring proximity sensors on PCF8574 INT (GPIO17). Press Ctrl+C to exit.")
        while running:
            time.sleep(POLL_INTERVAL_S)
    except ImportError:
        print("RPi.GPIO is required. Install with: sudo apt install python3-rpi.gpio", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

