    _PYZBAR_AVAILABLE = True
except ImportError:
    _PYZBAR_AVAILABLE = False

# Optional QR code decoding library (e.g., zxing)
try:
    from zxing import decode as zxing_decode
    _ZXING_AVAILABLE = True
except ImportError:
    _ZXING_AVAILABLE = False


def decode_qr_code(image):
    """Decode QR codes from a BGR image using pyzbar and zxing.

    Returns the decoded text string if found, otherwise None.
    """
    if not _PYZBAR_AVAILABLE and not _ZXING_AVAILABLE:
        return None

    # pyzbar
    if _PYZBAR_AVAILABLE:
        try:
            decoded_objects = pyzbar_decode(image)
            for obj in decoded_objects:
                if obj.type == 'QR_CODE':
                    return obj.data.decode('utf-8')
        except Exception as e:
            print(f"pyzbar decode error: {e}", file=sys.stderr)

    # zxing
    if _ZXING_AVAILABLE:
        try:
            decoded_objects = zxing_decode(image)
            for obj in decoded_objects:
                if obj.type == 'QR_CODE':
                    return obj.text
        except Exception as e:
            print(f"zxing decode error: {e}", file=sys.stderr)

    return None


def main():
    # Initialize the Raspberry Pi camera via the camera driver library.
    # The camera is enabled via raspi-config; no sudo is required.
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise RuntimeError("Failed to open camera (index 0).")
    except Exception as e:
        print(f"Camera initialization error: {e}", file=sys.stderr)
        sys.exit(1)

    # Capture a single frame at the documented 64x64 resolution.
    try:
        ret, frame = camera.read()
        if not ret or frame is None:
            raise RuntimeError("Failed to capture frame from camera.")
    except Exception as e:
        print(f"Frame capture error: {e}", file=sys.stderr)
        camera.release()
        sys.exit(1)

    # Convert the frame to grayscale for QR code detection.
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    except Exception as e:
        print(f"Color conversion error: {e}", file=sys.stderr)
        camera.release()
        sys.exit(1)

    # Attempt to decode the QR code from the grayscale image.
    try:
        decoded_text = decode_qr_code(gray)
    except Exception as e:
        print(f"QR code decoding error: {e}", file=sys.stderr)
        decoded_text = None

    # Print the result.
    if decoded_text:
        print(f"QR code detected: {decoded_text}")
    else:
        print("No QR code detected.")

    # Release the camera resources.
    try:
        camera.release()
    except Exception as e:
        print(f"Error releasing camera: {e}", file=sys.stderr)


if __name__ == "__main__":
    main()

