import os
import time
import datetime
import logging
import configparser
import signal
import sys
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder, JpegEncoder
from picamera2.outputs import FileOutput

CONFIG_FILE = 'config.ini'
LOG_FILE = 'logs/camera.log'
DEFAULT_CONFIG = {
    'storage_directory': './storage',
    'disk_space_threshold_mb': '1024',
    'log_file': LOG_FILE,
}

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_logging(log_file):
    log_dir = os.path.dirname(log_file)
    if not os.path.exists(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except OSError as e:
            print(f"Cannot create log directory {log_dir}: {e}", file=sys.stderr)
            log_dir = 'logs'
            try:
                os.makedirs(log_dir, exist_ok=True)
            except OSError as e2:
                print(f"Cannot create fallback log directory {log_dir}: {e2}", file=sys.stderr)
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )
    logging.info("Logging initialized.")

def load_config(config_file):
    config = configparser.ConfigParser()
    if not os.path.exists(config_file):
        with open(config_file, 'w') as f:
            for section, value in DEFAULT_CONFIG.items():
                f.write(f"[{section}]\n{section} = {value}\n")
        logging.warning(f"Created default config file {config_file}")
    config.read(config_file)
    return config

def get_config_value(config, section, key, default):
    try:
        return config.get(section, key)
    except (configparser.NoSectionError, configparser.NoOptionError):
        return default

def get_storage_path(storage_directory, timestamp):
    return os.path.join(storage_directory, timestamp.strftime('%Y'), timestamp.strftime('%m'), timestamp.strftime('%d'))

def get_available_space(path):
    try:
        statvfs = os.statvfs(path)
        return statvfs.f_bavail * statvfs.f_frsize
    except OSError as e:
        logging.error(f"Error getting disk space: {e}")
        return 0

def manage_disk_space(storage_directory, threshold_mb):
    threshold_bytes = threshold_mb * 1024 * 1024
    while True:
        available = get_available_space(storage_directory)
        if available >= threshold_bytes:
            break
        oldest_file = None
        oldest_size = 0
        for root, dirs, files in os.walk(storage_directory):
            for f in files:
                file_path = os.path.join(root, f)
                try:
                    size = os.path.getsize(file_path)
                    if oldest_file is None or size < oldest_size:
                        oldest_file = file_path
                        oldest_size = size
                except OSError:
                    continue
            if oldest_file:
                try:
                    os.remove(oldest_file)
                    logging.info(f"Deleted oldest file: {oldest_file}")
                    break
                except OSError as e:
                    logging.error(f"Error deleting file {oldest_file}: {e}")
                    break
        if oldest_file is None:
            logging.warning("No files to delete.")
            break

def capture_images(picam2, storage_directory, timestamp):
    for i in range(3):
        if not _running:
            return
        try:
            image_path = os.path.join(get_storage_path(storage_directory, timestamp), f"image_{i+1}.jpg")
            picam2.capture_file(image_path, format='jpeg', quality=85, bitrate=64)
            logging.info(f"Captured image: {image_path}")
        except Exception as e:
            logging.error(f"Error capturing image: {e}")
        time.sleep(0.5)

def record_video(picam2, storage_directory, timestamp):
    if not _running:
        return
    video_path = os.path.join(get_storage_path(storage_directory, timestamp), "video.h264")
    try:
        encoder = H264Encoder(bitrate=1700000)
        output = FileOutput(video_path)
        picam2.start_recording(encoder, output)
        time.sleep(5)
        picam2.stop_recording()
        logging.info(f"Recorded video: {video_path}")
    except Exception as e:
        logging.error(f"Error recording video: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config(CONFIG_FILE)
    storage_directory = get_config_value(config, 'DEFAULT', 'storage_directory', DEFAULT_CONFIG['storage_directory'])
    disk_space_threshold_mb = int(get_config_value(config, 'DEFAULT', 'disk_space_threshold_mb', DEFAULT_CONFIG['disk_space_threshold_mb']))
    log_file = get_config_value(config, 'DEFAULT', 'log_file', DEFAULT_CONFIG['log_file'])

    setup_logging(log_file)
    logging.info("Starting camera monitoring system.")

    picam2 = None
    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_still_configuration())
        picam2.start()
        logging.info("Camera initialized.")
    except Exception as e:
        logging.warning(f"Camera initialization failed: {e}. Continuing without camera.")
        picam2 = None

    try:
        while _running:
            try:
                motion_detected = False
                if picam2:
                    try:
                        motion_detected = picam2.capture_array() is not None
                    except Exception as e:
                        logging.warning(f"Error reading motion sensor: {e}")
                if motion_detected:
                    timestamp = datetime.datetime.now()
                    logging.info(f"Motion detected at {timestamp}.")
                    manage_disk_space(storage_directory, disk_space_threshold_mb)
                    storage_path = get_storage_path(storage_directory, timestamp)
                    try:
                        os.makedirs(storage_path, exist_ok=True)
                    except OSError as e:
                        logging.error(f"Error creating storage directory: {e}")
                        continue
                    if picam2:
                        capture_images(picam2, storage_path, timestamp)
                        record_video(picam2, storage_path, timestamp)
                    else:
                        logging.warning("Camera not available. Skipping image and video capture.")
                time.sleep(2)
            except Exception as e:
                logging.error(f"Error in main loop: {e}")
                time.sleep(1)
    finally:
        if picam2:
            try:
                picam2.stop()
                picam2.close()
                logging.info("Camera released.")
            except Exception as e:
                logging.error(f"Error releasing camera: {e}")
        logging.info("Exiting camera monitoring system.")

if __name__ == "__main__":
    main()

