import os
import time
import csv
import socket
import signal
import logging
from datetime import datetime
from picamera2 import Picamera2

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

LEFT_CAMERA_ID = 0
RIGHT_CAMERA_ID = 1
EXPOSURE_MIN = 100
EXPOSURE_MAX = 10000
BRIGHTNESS_MIN = 0
BRIGHTNESS_MAX = 100
CONTRAST_MIN = 0
CONTRAST_MAX = 100
TCP_SERVER_ADDRESS = ('127.0.0.1', 65432)
IMAGE_DIR = 'images'
CSV_FILE = 'images/metadata.csv'

running = True


def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False


def validate_exposure(exposure):
    if not (EXPOSURE_MIN <= exposure <= EXPOSURE_MAX):
        raise ValueError(
            f"Exposure must be between {EXPOSURE_MIN} and {EXPOSURE_MAX} us"
        )


def validate_brightness(brightness):
    if not (BRIGHTNESS_MIN <= brightness <= BRIGHTNESS_MAX):
        raise ValueError(
            f"Brightness must be between {BRIGHTNESS_MIN} and {BRIGHTNESS_MAX}"
        )


def validate_contrast(contrast):
    if not (CONTRAST_MIN <= contrast <= CONTRAST_MAX):
        raise ValueError(
            f"Contrast must be between {CONTRAST_MIN} and {CONTRAST_MAX}"
        )


def initialize_camera(camera_id, exposure, brightness, contrast):
    try:
        cam = Picamera2(camera_id)
        config = cam.create_still_configuration(
            main={"size": (640, 480)}
        )
        cam.configure(config)
        cam.set_controls({
            "ExposureTime": exposure,
            "Brightness": brightness,
            "Contrast": contrast,
        })
        cam.start()
        time.sleep(2)
        return cam
    except Exception as e:
        logging.error(f"Error initializing camera {camera_id}: {e}")
        return None


def capture_image(cam, filename):
    try:
        cam.capture_file(filename)
        return True
    except Exception as e:
        logging.error(f"Error capturing image {filename}: {e}")
        return False


def transmit_data(data, address):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
            sock.settimeout(5)
            sock.connect(address)
            sock.sendall(data.encode('utf-8'))
    except Exception as e:
        logging.error(f"Error transmitting data: {e}")


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    os.makedirs(IMAGE_DIR, exist_ok=True)

    left_cam = initialize_camera(LEFT_CAMERA_ID, 5000, 50, 50)
    right_cam = initialize_camera(RIGHT_CAMERA_ID, 5000, 50, 50)

    if left_cam is None or right_cam is None:
        logging.error("Failed to initialize one or both cameras. Exiting.")
        if left_cam is not None:
            left_cam.close()
        if right_cam is not None:
            right_cam.close()
        return

    try:
        while running:
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            left_filename = os.path.join(IMAGE_DIR, f"{timestamp}_left.jpg")
            right_filename = os.path.join(IMAGE_DIR, f"{timestamp}_right.jpg")

            if not capture_image(left_cam, left_filename):
                logging.error("Failed to capture left image.")
                continue
            if not capture_image(right_cam, right_filename):
                logging.error("Failed to capture right image.")
                continue

            left_res = left_cam.camera_configuration['main']['size']
            right_res = right_cam.camera_configuration['main']['size']

            metadata = (
                f"{timestamp},{left_filename},{right_filename},"
                f"{left_res[0]}x{left_res[1]},{right_res[0]}x{right_res[1]},"
                f"{left_cam.controls['ExposureTime']},{left_cam.controls['Brightness']},"
                f"{left_cam.controls['Contrast']}"
            )

            try:
                with open(CSV_FILE, 'a', newline='') as csvfile:
                    csv.writer(csvfile).writerow([metadata])
            except IOError as e:
                logging.error(f"Error writing to CSV file: {e}")

            transmit_data(metadata, TCP_SERVER_ADDRESS)

            logging.info(f"Captured images: {left_filename}, {right_filename}")

            time.sleep(1.0)

    finally:
        logging.info("Releasing camera resources...")
        if left_cam is not None:
            try:
                left_cam.stop()
                left_cam.close()
            except Exception as e:
                logging.error(f"Error releasing left camera: {e}")
        if right_cam is not None:
            try:
                right_cam.stop()
                right_cam.close()
            except Exception as e:
                logging.error(f"Error releasing right camera: {e}")
        logging.info("Cleanup complete.")


if __name__ == "__main__":
    main()

