import time
import logging
import signal
import sys
import atexit
from collections import deque

try:
    import board
    import busio
    from adafruit_vl53l0x import VL53L0X
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-vl53l0x", file=sys.stderr)
    sys.exit(1)

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO not available; running in mock mode.", file=sys.stderr)
    GPIO = None

ZONE_PINS = [17, 27, 22]
ZONE_NAMES = ["zone1", "zone2", "zone3"]
VALIDATION_DISTANCE = 1.0  # meters
MAX_RETRIES = 3
RETRY_DELAY = 0.1
MOVING_AVG_SIZE = 5
LOG_FILE = "occupancy_log.txt"

_running = True
_i2c = None
_sensor = None
_log = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _sensor, _log
    if _sensor is not None:
        try:
            _sensor.stop_ranging()
        except Exception:
            pass
    if _log is not None:
        try:
            _log.flush()
            _log.close()
        except Exception:
            pass
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass


def _init_gpio():
    if GPIO is None:
        return
    GPIO.setmode(GPIO.BCM)
    for pin in ZONE_PINS:
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)


def _init_sensor():
    global _i2c, _sensor
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
        _sensor = VL53L0X(_i2c)
        _sensor.start_ranging()
        logging.info("VL53L0X sensor initialized on I2C1.")
    except Exception as exc:
        logging.error(f"Failed to initialize VL53L0X: {exc}")
        _sensor = None
        _i2c = None


def _read_distance():
    if _sensor is None:
        return None
    for attempt in range(MAX_RETRIES):
        try:
            distance = _sensor.range
            if distance is not None and distance > 0:
                return distance
        except Exception as exc:
            logging.warning(f"VL53L0X read error (attempt {attempt + 1}/{MAX_RETRIES}): {exc}")
        time.sleep(RETRY_DELAY)
    logging.error("VL53L0X read failed after retries.")
    return None


def _validate_occupancy(distance):
    if distance is None:
        return False
    if distance < VALIDATION_DISTANCE * 1000:
        return True
    return False


def _debounce_callback(channel, zone_name):
    logging.info(f"Motion detected in {zone_name} (GPIO {channel}).")
    distances = deque(maxlen=MOVING_AVG_SIZE)
    for attempt in range(MAX_RETRIES):
        distance = _read_distance()
        if distance is None:
            logging.warning(f"Validation failed for {zone_name} (attempt {attempt + 1}/{MAX_RETRIES}).")
            time.sleep(RETRY_DELAY)
            continue
        distances.append(distance)
        if len(distances) == MOVING_AVG_SIZE:
            avg_distance = sum(distances) / MOVING_AVG_SIZE
            if avg_distance < VALIDATION_DISTANCE * 1000:
                logging.info(f"Occupancy validated in {zone_name} (avg distance: {avg_distance:.2f} mm).")
                return
            else:
                logging.warning(f"Occupancy NOT validated in {zone_name} (avg distance: {avg_distance:.2f} mm).")
    logging.error(f"Occupancy validation failed for {zone_name} after retries.")


def _register_callbacks():
    for i, pin in enumerate(ZONE_PINS):
        if GPIO is not None:
            GPIO.add_event_detect(pin, GPIO.RISING, callback=lambda ch, z=ZONE_NAMES[i]: _debounce_callback(ch, z), bouncetime=2000)


def main():
    global _log
    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Starting occupancy monitoring system.")
    _init_gpio()
