#!/usr/bin/env python3
"""
QR Code Inventory Scanner for Raspberry Pi 4B

Reads from two USB cameras (/dev/video0 and /dev/video2), detects motion
using a configurable threshold, decodes QR codes, logs successful scans,
maintains a redundancy time window, buffers frames, and simulates cloud
upload at configurable intervals.  Includes robust error handling,
recovery from USB bus errors, and a watchdog that restarts the program
if no QR code is decoded for 30 consecutive seconds.

Hardware:
    - Raspberry Pi 4 Model B
    - USB 3.0 cameras at /dev/video0 and /dev/video2

Dependencies:
    - opencv-python
    - pyzbar
    - Pillow
    - configobj
"""

import argparse
import datetime
import logging
import os
import queue
import re
import signal
import sys
import threading
import time
from typing import Optional, Tuple

import cv2
import configobj
import numpy as np
from pyzbar import pyzbar

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
DEFAULT_CONFIG_FILE = "config.ini"
DEFAULT_LOG_FILE = "inventory.log"
DEFAULT_LOG_LEVEL = "INFO"
DEFAULT_FRAME_BUFFER_SIZE = 10
DEFAULT_MOTION_THRESHOLD = 25
DEFAULT_REDUNDANCY_TIME_WINDOW = 60
DEFAULT_CLOUD_UPLOAD_INTERVAL = 60
DEFAULT_REINIT_DELAY = 5
DEFAULT_WATCHDOG_TIMEOUT = 30
CAMERA_DEVICES = ["/dev/video0", "/dev/video2"]
CAMERA_NAMES = ["Camera 1", "Camera 2"]
DEFAULT_INVENTORY_FILE = "inventory.log"
DEFAULT_BACKUP_INVENTORY_FILE = "backup_inventory.log"
DEFAULT_QR_CODE_PATTERN = r"^(QRCODE_)[A-Z0-9]{12}$"
DEFAULT_QR_CODE_PATTERN_RE = re.compile(DEFAULT_QR_CODE_PATTERN)

# ---------------------------------------------------------------------------
# Global state
# ---------------------------------------------------------------------------
inventory_data: dict = {}
inventory_lock = threading.Lock()
frame_buffer: dict = {name: [] for name in CAMERA_NAMES}
