import io
import os
import time
import signal
import logging
import threading
from typing import Tuple, Optional

import numpy as np
import cv2
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEFAULT_CONFIG = {
    'snapshot_dir': 'snapshots',
    'roi_x1': 100, 'roi_y1': 100, 'roi_x2': 400, 'roi_y2': 400,
    'motion_threshold': 1.0, 'confirmation_delay': 2.0,
    'temperature_threshold': 70.0, 'simulated_temperature': False
}

running = True
lock = threading.Lock()


def signal_handler(sig, frame):
    global running
    with lock:
        running = False
    logger.info('Shutdown signal received.')


def load_config(config_file: str = 'config.txt') -> dict:
    config = DEFAULT_CONFIG.copy()
    try:
        with open(config_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' not in line:
                    logger.warning(f'Invalid config line: {line}')
                    continue
                key, value = line.split('=', 1)
                key = key.strip()
                value = value.strip()
                if key not in config:
                    logger.warning(f'Unknown config key: {key}')
                    continue
                try:
                    if isinstance(config[key], bool):
                        config[key] = value.lower() in ('true', '1', 'yes')
                    elif isinstance(config[key], int):
                        config[key] = int(value)
                    elif isinstance(config[key], float):
                        config[key] = float(value)
                    else:
                        config[key] = value
