import cv2
import os
import time
import signal
import sys

IMAGE_DIR = "images"
MAX_IMAGES = 5
CAMERA_INDEX = 0
CASCADE_PATH = cv2.data.haarcascades + "haarcascade_frontalface_default.xml"

running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def create_image_directory(directory_name):
    try:
        os.makedirs(directory_name, exist_ok=True)
        return True
    except OSError as e:
        print(f"Error creating directory '{directory_name}': {e}")
        return False

def initialize_camera(camera_index=CAMERA_INDEX):
    for attempt in range(3):
        try:
            camera = cv2.VideoCapture(camera_index)
            if not camera.isOpened():
                raise IOError("Could not open camera")
            return camera
        except Exception as e:
            print(f"Error initializing camera (attempt {attempt + 1}/3): {e}")
            time.sleep(1)
    return None

def detect_faces(image, face_cascade):
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))

def draw_bounding_boxes(image, faces):
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (255, 0, 0), 2)

def save_image(image, directory, name):
    filename = os.path.join(directory, f"{name}.jpg")
    try:
        success = cv2.imwrite(filename, image)
        if success:
            print(f"Image saved: {filename}")
            return True
        else:
            print(f"Error: cv2.imwrite returned False for {filename}")
            return False
    except Exception as e:
        print(f"Error saving image '{filename}': {e}")
        return False

def main():
    global running

    if not create_image_directory(IMAGE_DIR):
        sys.exit(1)

    face_cascade = cv2.CascadeClassifier(CASCADE_PATH)
    if face_cascade.empty():
        print("Error: Could not load Haar cascade classifier.")
        sys.exit(1)

    camera = initialize_camera()
    if camera is None:
        print("Error: Could not initialize camera after 3 attempts.")
        sys.exit(1)

    image_count = 0
    try:
        while running and image_count < MAX_IMAGES:
            ret, frame = camera.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break

            faces = detect_faces(frame, face_cascade)
            draw_bounding_boxes(frame, faces)

            cv2.imshow("Face Detection", frame)

            key = cv2.waitKey(1) & 0xFF
            if key == ord('q'):
                break
            elif key == ord('y'):
                if not faces:
                    print("No face detected. Please try again.")
                    continue

                x, y, w, h = faces[0]
                face_image = frame[y:y + h, x:x + w]
                name = input("Name: ").strip()

                if not name:
                    print("Name cannot be empty. Skipping.")
                    continue

                if save_image(face_image, IMAGE_DIR, name):
                    image_count += 1
                    print(f"Total images saved: {image_count}/{MAX_IMAGES}")

                    if image_count < MAX_IMAGES:
                        print(f"Need {MAX_IMAGES - image_count} more images.")
                else:
                    print("Failed to save image. Continuing.")

            elif key != ord('y'):
                print("Press 'y' to capture, 'q' to quit.")

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        camera.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    main()

