import cv2
import signal
import sys
import atexit

# Constants
CAMERA_INDEX = 0
WINDOW_TITLE = "Real-time Face Detection"
FACE_CASCADE_PATH = cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
RECTANGLE_COLOR = (255, 0, 0)  # Blue in BGR
RECTANGLE_THICKNESS = 2
WAIT_KEY_DELAY = 1  # ms

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_camera(camera_index=CAMERA_INDEX):
    """Initializes the camera with error handling."""
    try:
        camera = cv2.VideoCapture(camera_index)
        if not camera.isOpened():
            raise IOError(f"Could not open camera at index {camera_index}")
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None


def load_face_cascade(cascade_path=FACE_CASCADE_PATH):
    """Loads the face cascade classifier with error handling."""
    try:
        face_cascade = cv2.CascadeClassifier(cascade_path)
        if face_cascade.empty():
            raise IOError(f"Could not load face cascade from {cascade_path}")
        return face_cascade
    except Exception as e:
        print(f"Error loading face cascade: {e}", file=sys.stderr)
        return None


def detect_faces(image, face_cascade):
    """Detects faces in an image using the provided cascade classifier."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(
        gray, scaleFactor=1.1, minNeighbors=5
    )


def draw_rectangles(image, faces):
    """Draws rectangles around detected faces in the image."""
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), RECTANGLE_COLOR, RECTANGLE_THICKNESS)


def process_frame(frame, face_cascade):
    """Processes a single frame: detect faces, draw rectangles, and return the image."""
    faces = detect_faces(frame, face_cascade)
    draw_rectangles(frame, faces)
    if len(faces) > 0:
        print("Face detected!")
    return frame


def display_frame(frame, window_title=WINDOW_TITLE):
    """Displays the frame in a window with proper error handling."""
    try:
        cv2.imshow(window_title, frame)
    except Exception as e:
        print(f"Error displaying frame: {e}", file=sys.stderr)


def release_resources(camera):
    """Releases camera and window resources."""
    try:
        if camera is not None:
            camera.release()
    except Exception as e:
        print(f"Error releasing camera: {e}", file=sys.stderr)
    try:
        cv2.destroyAllWindows()
    except Exception as e:
        print(f"Error destroying windows: {e}", file=sys.stderr)


def main():
    """Main function to run the face detection."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Ensure cleanup on normal exit
    atexit.register(release_resources)

    camera = initialize_camera()
    if camera is None:
        sys.exit(1)

    face_cascade = load_face_cascade()
    if face_cascade is None:
        release_resources(camera)
        sys.exit(1)

    try:
        while _running:
            ret, frame = camera.read()
            if not ret:
                print("Failed to grab frame", file=sys.stderr)
                break

            processed_frame = process_frame(frame, face_cascade)
            display_frame(processed_frame)

            key = cv2.waitKey(WAIT_KEY_DELAY) & 0xFF
            if key == ord("q"):
                break
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        release_resources(camera)


if __name__ == "__main__":
    main()

