                 min_object_area=10, servo1_pin=7, servo2_pin=13, servo_center_duty_cycle=7.0,
                 uart_port='/dev/serial0', uart_baudrate=115200, max_reconnect_attempts=3,
                 reconnect_delay=5):
        self.camera_resolution = camera_resolution
        self.frame_rate = frame_rate
        self.tracking_threshold = tracking_threshold
        self.min_object_area = min_object_area
        self.servo1_pin = servo1_pin
        self.servo2_pin = servo2_pin
        self.servo_center_duty_cycle = servo_center_duty_cycle
        self.uart_port = uart_port
        self.uart_baudrate = uart_baudrate
        self.max_reconnect_attempts = max_reconnect_attempts
        self.reconnect_delay = reconnect_delay
        self.camera = None
        self.uart = None
        self.servo1 = None
        self.servo2 = None
        self.running = True
        self.lock = threading.Lock()
        self._init_gpio()
        self._init_uart()
        self._init_camera()

    def _init_gpio(self):
        if GPIO is None:
            logging.warning("RPi.GPIO not available; servo control disabled.")
            return
        try:
            GPIO.setmode(GPIO.BOARD)
            GPIO.setup(self.servo1_pin, GPIO.OUT)
            GPIO.setup(self.servo2_pin, GPIO.OUT)
            self.servo1 = GPIO.PWM(self.servo1_pin, 50)
            self.servo2 = GPIO.PWM(self.servo2_pin, 50)
            self.servo1.start(self.servo_center_duty_cycle)
            self.servo2.start(self.servo_center_duty_cycle)
            logging.info("GPIO initialized: servo1=BOARD%d, servo2=BOARD%d @ 50 Hz, duty %.1f%%",
                         self.servo1_pin, self.servo2_pin, self.servo_center_duty_cycle)
        except Exception as e:
            logging.error("GPIO initialization failed: %s", e)
            self.cleanup()
            raise

    def _init_uart(self):
        try:
            self.uart = serial.Serial(self.uart_port, self.uart_baudrate, timeout=1)
            logging.info("UART initialized on %s @ %d baud", self.uart_port, self.uart_baudrate)
        except SerialException as e:
            logging.error("UART initialization failed: %s", e)
            self.uart = None

    def _init_camera(self):
        for attempt in range(1, self.max_reconnect_attempts + 1):
            try:
                self.camera = cv2.VideoCapture(0)
                if not self.camera.isOpened():
                    raise IOError("Cannot open camera")
                self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, self.camera_resolution[0])
                self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, self.camera_resolution[1])
                self.camera.set(cv2.CAP_PROP_FPS, self.frame_rate)
                actual_fps = self.camera.get(cv2.CAP_PROP_FPS)
                logging.info("Camera initialized: resolution %s, fps %.2f",
                             self.camera_resolution, actual_fps)
                return
            except Exception as e:
                logging.error("Camera init attempt %d/%d failed: %s", attempt, self.max_reconnect_attempts, e)
                if self.camera:
                    self.camera.release()
                    self.camera = None
                if attempt < self.max_reconnect_attempts:
                    time.sleep(self.reconnect_delay)
        raise IOError("Camera initialization failed after %d attempts" % self.max_reconnect_attempts)

    def _segment_red(self, frame):
        hsv_roi = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
        mask1 = cv2.inRange(hsv_roi, np.array([160, 160, 10]), np.array([190, 255, 255]))
        ycr_roi = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
        mask2 = cv2.inRange(ycr_roi, np.array([0, 165, 0]), np.array([255, 255, 255]))
        mask = mask1 | mask2
        mask = cv2.erode(mask, np.ones((3, 3), np.uint8))
        mask = cv2.dilate(mask, np.ones((8, 8), np.uint8))
        return mask

    def _calculate_center(self, mask):
        try:
            contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            if not contours:
                return None, None
            largest_contour = max(contours, key=cv2.contourArea)
            area = cv2.contourArea(largest_contour)
            if area < self.min_object_area:
                return None, None
            x, y, w, h = cv2.boundingRect(largest_contour)
            center_x = x + w / 2
            center_y = y + h / 2
            return center_x, center_y
        except Exception as e:
            logging.error("Error calculating center: %s", e)
            return None, None

    def _move_servos(self, center_x):
        try:
            if center_x is None:
                return
            error = center_x - self.camera_resolution[0] / 2
            if abs(error) > self.tracking_threshold:
                duty_cycle = self.servo_center_duty_cycle + (error / self.camera_resolution[0]) * 5.0
                duty_cycle = max(2.5, min(10.0, duty_cycle))
                if self.servo1:
                    self.servo1.ChangeDutyCycle(duty_cycle)
                if self.servo2:
                    self.servo2.ChangeDutyCycle(duty_cycle)
                logging.info("Servo error: %.2f, duty: %.1f%%", error, duty_cycle)
            else:
                if self.servo1:
                    self.servo1.ChangeDutyCycle(self.servo_center_duty_cycle)
                if self.servo2:
                    self.servo2.ChangeDutyCycle(self.servo_center_duty_cycle)
        except Exception as e:
            logging.error("Error moving servos: %s", e)

    def _send_uart_command(self, command):
        if self.uart:
            try:
                self.uart.write(command.encode('utf-8'))
                self.uart.flush()
            except SerialException as e:
                logging.error("UART write failed: %s", e)
                self.uart = None

    def _process_frame(self, frame):
        mask = self._segment_red(frame)
        center_x, center_y = self._calculate_center(mask)
        self._move_servos(center_x)
        return center_x, center_y

    def run(self):
        try:
            while self.running:
                ret, frame = self.camera.read()
                if not ret:
                    logging.error("Failed to grab frame")
                    break
                with self.lock:
                    self._process_frame(frame)
                    self._send_uart_command("Tracking: X=%.2f, Y=%.2f" % (self._calculate_center(frame)[0] if self._calculate_center(frame) else 0, 0))
        except Exception as e:
            logging.error("Error in main loop: %s", e)
        finally:
            self.cleanup()

    def cleanup(self):
        self.running = False
        if self.camera:
            self.camera.release()
            self.camera = None
        if self.uart:
            try:
                self.uart.close()
            except Exception:
                pass
            self.uart = None
        if GPIO is not None:
            try:
                if self.servo1:
                    self.servo1.stop()
                if self.servo2:
                    self.servo2.stop()
                GPIO.cleanup()
            except Exception:
                pass
        logging.info("Cleanup complete")

def main():
    tracker = BallTracker()
    def signal_handler(sig, frame):
        logging.info("Signal received, shutting down...")
        tracker.running = False
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    tracker.run()

if __name__ == "__main__":
    main()

