import io
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np
from PIL import Image
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

try:
    import uvicorn
    from fastapi import FastAPI, WebSocket
    from fastapi.responses import StreamingResponse
except ImportError:
    uvicorn = None
    FastAPI = None
    WebSocket = None
    StreamingResponse = None

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
app: Optional[FastAPI] = None
ws_connections: list[WebSocket] = []
lock = threading.Lock()
prev_frame: Optional[np.ndarray] = None
picam2: Optional[Picamera2] = None
stop_event = threading.Event()


def detect_motion_function(prev_frame: np.ndarray, curr_frame: np.ndarray) -> bool:
    """Motion-detection callback.

    Expects NumPy frames from the camera driver.  Converts JPEG bytes
    (extracted between 0xFF 0xD8 markers) to PIL images and compares
    them with frame differencing.
    """
    if curr_frame is None or prev_frame is None:
        return False

    # curr_frame may be a JPEG-encoded bytes buffer; extract the
    # JPEG-encoded data between 0xFF 0xD8 markers.
    if isinstance(curr_frame, (bytes, bytearray)):
        try:
            curr_frame = np.frombuffer(curr_frame, dtype=np.uint8)
        except Exception as exc:
            print(f"[motion] JPEG decode failed: {exc}")
            return False

    if curr_frame is None or len(curr_frame) < 2:
        return False

    start = np.where(curr_frame == 0xFF)[0]
    if len(start) < 2:
        return False

    # Locate the first 0xFF after the first 0xFF (0xFF 0xD8).
    idx = np.searchsorted(start, 0xD8, side="right")
    if idx < 2:
        return False

    start_idx = start[idx - 1]
    end_idx = start[idx] if idx < len(start) else len(curr_frame)

    if end_idx <= start_idx + 2:
        return False

    try:
        img = Image.fromarray(curr_frame[start_idx:end_idx])
        curr_gray = cv2.cvtColor(np.array(img), cv2.COLOR_RGB2GRAY)
        diff = cv2.absdiff(prev_frame, curr_gray)
        thresh = cv2.threshold(diff, 25, 255, cv2.THRESH_BINARY)[1]
        thresh = cv2.dilate(thresh, None, iterations=2)
        motion = cv2.countNonZero(thresh)
        return motion > 0
    except Exception as exc:
        print(f"[motion] Error during motion detection: {exc}")
        return False


def send_frame_to_clients(frame: np.ndarray) -> None:
    """Broadcast a frame to all connected WebSocket clients."""
    if not ws_connections:
        return

    try:
        data = frame.tobytes()
        for ws in ws_connections:
            try:
                ws.send_bytes(data)
            except Exception as exc:
                print(f"[broadcast] Error sending frame to client: {exc}")
    except Exception as exc:
        print(f"[broadcast] Error sending frame: {exc}")


def frame_callback(requested_format: str, frame: np.ndarray) -> None:
    """Picamera2 callback: decode JPEG bytes and broadcast if motion."""
    global prev_frame

    if requested_format != "main":
        return

    if frame is None:
        return

    # Convert to JPEG bytes (picamera2 MJPEG output is raw JPEG data).
    if isinstance(frame, (bytes, bytearray)):
        try:
            curr_frame = np.frombuffer(frame, dtype=np.uint8)
        except Exception as exc:
            print(f"[frame] JPEG decode failed: {exc}")
            return
    else:
        try:
            curr_frame = np.array(frame)
        except Exception as exc:
            print(f"[frame] Frame conversion failed: {exc}")
            return

    if curr_frame is None or len(curr_frame) == 0:
        return

    # Extract JPEG-encoded data between 0xFF 0xD8 markers.
    if isinstance(curr_frame, (bytes, bytearray)):
        try:
            curr_frame = np.frombuffer(curr_frame, dtype=np.uint8)
        except Exception as exc:
            print(f"[frame] JPEG decode failed: {exc}")
            return

    if curr_frame is None or len(curr_frame) < 2:
        return

    start = np.where(curr_frame == 0xFF)[0]
    if len(start) < 2:
        return

    idx = np.searchsorted(start, 0xD8, side="right")
    if idx < 2:
        return

    start_idx = start[idx - 1]
    end_idx = start[idx] if idx < len(start) else len(curr_frame)

    if end_idx <= start_idx + 2:
        return

    try:
        img = Image.fromarray(curr_frame[start_idx:end_idx])
        curr_gray = cv2.cvtColor(np.array(img), cv2.COLOR_RGB2GRAY)

        if prev_frame is None:
            prev_frame = curr_gray
            return

        if detect_motion_function(prev_frame, curr_gray):
            send_frame_to_clients(curr_gray)

        prev_frame = curr_gray
    except Exception as exc:
        print(f"[frame] Error processing frame: {exc}")


def start_camera() -> None:
    """Initialize and start the Picamera2 MJPEG encoder in a background thread."""
    global picam2
    try:
        picam2 = Picamera2()
        config = picam2.create_video_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            lores={"size": (320, 240), "format": "YUV420"},
            encode="lores",
        )
        picam2.configure(config)

        # picamera2 MJPEG encoder produces raw JPEG bytes on the main
        # stream.  We use a custom Output that buffers the JPEG data
        # and calls frame_callback when a complete frame is available.
        class MJPEGOutput(Output):
            def __init__(self, callback: Callable[[str, np.ndarray], None]):
                super().__init__()
                self.callback = callback
                self._buffer = io.BytesIO()
                self._lock = threading.Lock()

            def outputframe(self, frame: bytes, keyframe: bool = True, timestamp: int = 0) -> None:
                with self._lock:
                    self._buffer.write(frame)
                    # 0xFF 0xD9 marks the end of a complete JPEG frame.
                    if b"\xff\xd9" in self._buffer.getvalue():
                        jpeg_data = self._buffer.getvalue()
                        self._buffer.seek(0)
                        self._buffer.truncate()
                        self.callback("main", jpeg_data)

        output = MJPEGOutput(frame_callback)
        picam2.start_recording(MJPEGEncoder(), output)
        print("[camera] MJPEG recording started.")
    except Exception as exc:
        print(f"[camera] Error initializing camera: {exc}")
        raise


def stop_camera() -> None:
    """Stop the camera and release resources."""
    global picam2
    if picam2 is not None:
        try:
            picam2.stop_recording()
        except Exception as exc:
            print(f"[camera] Error stopping recording: {exc}")
        try:
            picam2.close()
        except Exception as exc:
            print(f"[camera] Error closing camera: {exc}")
        picam2 = None
    print("[camera] Camera stopped.")


def has_connections() -> bool:
    """Return True if there are currently connected WebSocket clients."""
    return len(ws_connections) > 0


def broadcast(data: bytes) -> None:
    """Broadcast data to all connected WebSocket clients."""
    with lock:
        send_frame_to_clients(data)


def websocket_endpoint(websocket: WebSocket) -> None:
    """FastAPI WebSocket endpoint."""
    try:
        await websocket.accept()
        with lock:
            ws_connections.append(websocket)
        try:
            while not stop_event.is_set():
                await asyncio.sleep(0.1)
        finally:
            with lock:
                ws_connections.remove(websocket)
    except Exception as exc:
        print(f"[ws] Error handling WebSocket: {exc}")


def signal_handler(signum, frame) -> None:
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\n[signal] Received signal {signum}, shutting down...")
    stop_event.set()


def main() -> None:
    """Entry point: start camera, run FastAPI server, and handle shutdown."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if uvicorn is None or FastAPI is None or WebSocket is None:
        print("[main] Missing dependencies. Install with: pip install fastapi uvicorn")
        return

    try:
        start_camera()
    except Exception as exc:
        print(f"[main] Camera initialization failed: {exc}")
        stop_camera()
        return

    app = FastAPI()

    @app.websocket("/ws")
    async def websocket_endpoint(websocket: WebSocket):
        await websocket_endpoint(websocket)

    try:
        import asyncio

        asyncio.run(app.run(host="0.0.0.0", port=8000))
    except KeyboardInterrupt:
        print("[main] KeyboardInterrupt received.")
    finally:
        stop_event.set()
        stop_camera()


if __name__ == "__main__":
    main()

