import os
import sys
import signal
import numpy as np
import torch
import torchvision.transforms as T
import torchvision.models as M
from PIL import Image
from picamera2 import Picamera2

# ---------------------------------------------------------------------------
# Globals for signal-safe cleanup
# ---------------------------------------------------------------------------
_camera = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    print(f"\n[INFO] Signal {signum} received – shutting down cleanly.", file=sys.stderr)
    cleanup()
    sys.exit(0)


def cleanup():
    global _camera
    if _camera is not None:
        try:
            _camera.stop()
        except Exception:
            pass
        _camera = None


def download_model(url, fname):
    """Download a Torch model file from *url* and save as *fname*."""
    try:
        import requests
    except ImportError:
        raise RuntimeError("requests library is required for download")
    try:
        r = requests.get(url, stream=True, timeout=30)
        r.raise_for_status()
        with open(fname, "wb") as f:
            for chunk in r.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.exceptions.RequestException as e:
        raise RuntimeError(f"Failed to download model from {url}: {e}")
    except OSError as e:
        raise RuntimeError(f"Failed to write model file {fname}: {e}")


def load_labels(path):
    """Load labels from a text file, one per line."""
    try:
        with open(path, "r", encoding="utf-8") as f:
            return [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        raise RuntimeError(f"Label file not found: {path}")
    except OSError as e:
        raise RuntimeError(f"Failed to read label file {path}: {e}")


def transform_image(img):
    """Resize short side to 256, center-crop to 224x224, convert to CHW float32."""
    try:
        transform = T.Compose([
            T.Resize(256),
            T.CenterCrop(224),
            T.ToTensor(),
            T.Normalize(mean=[0.485, 0.456, 0.406],
                        std=[0.229, 0.224, 0.225]),
        ])
        return transform(img).unsqueeze(0)
    except Exception as e:
        raise RuntimeError(f"Image transformation failed: {e}")


def predict(image_path, model, labels, top_k=3):
    """Run inference and return top_k (prob, label) tuples."""
    try:
        img = Image.open(image_path)
        if img is None:
            raise RuntimeError("Failed to open image for prediction")
        input_tensor = transform_image(img)
    except Exception as e:
        raise RuntimeError(f"Image preprocessing failed: {e}")

    try:
        with torch.no_grad():
            output = model(input_tensor)
        probs = torch.nn.functional.softmax(output, dim=1)
        top_idx = torch.topk(probs, k=top_k)[1].squeeze()
        results = []
        for idx in top_idx:
            results.append((float(probs[0, idx].item()), str(labels[idx])))
        return results
    except Exception as e:
        raise RuntimeError(f"Inference failed: {e}")


def main():
    global _camera

    # Install signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- Camera setup -------------------------------------------------------
    try:
        _camera = Picamera2()
        _camera.configure(_camera.create_still_configuration())
        _camera.start()
    except Exception as e:
        raise RuntimeError(f"Failed to initialise camera at index 0: {e}")

    # --- Image directory ----------------------------------------------------
    try:
        os.makedirs("images", exist_ok=True)
    except OSError as e:
        raise RuntimeError(f"Cannot create images directory: {e}")

    # --- Image capture ------------------------------------------------------
    try:
        timestamp = int(os.times().tick) if hasattr(os, "times") else int(time.time() * 1000)
        image_path = f"images/{timestamp}.jpg"
        _camera.capture_file(image_path)
    except Exception as e:
        cleanup()
        raise RuntimeError(f"Failed to capture image: {e}")

    # --- Model & label loading ---------------------------------------------
    try:
        model_url = "https://download.pytorch.org/models/resnet50-19c8e933.pth"
        label_url = "https://raw.githubusercontent.com/pytorch/hub/master/imagenet_classes.txt"
        model_fname = "resnet50.pth"
        label_fname = "imagenet_classes.txt"

        if not os.path.exists(model_fname):
            download_model(model_url, model_fname)
        if not os.path.exists(label_fname):
            download_model(label_url, label_fname)

        model = M.resnet50(pretrained=False)
        model.load_state_dict(torch.load(model_fname))
        model.eval()

        labels = load_labels(label_fname)
    except Exception as e:
        cleanup()
        raise RuntimeError(f"Model/label loading failed: {e}")

    # --- Prediction ---------------------------------------------------------
    try:
        results = predict(image_path, model, labels)
        print("Top 3 predictions:")
        for prob, label in results:
            print(f"  {prob:.4f}  {label}")
    except Exception as e:
        cleanup()
        raise RuntimeError(f"Prediction failed: {e}")

    cleanup()


if __name__ == "__main__":
    import time
    try:
        main()
    except RuntimeError as e:
        print(f"[ERROR] {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"[ERROR] Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)

