import signal
import sys
import time
import logging
import threading

import cv2
import numpy as np
from PIL import Image

import config
import face
import ui
import helpers.audio as audio_helper
import helpers.general as general_helper
from helpers.database import Database

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DOOR_LOCK_PIN = 18
BUTTON_PIN = 17
SAMPLE_RATE = 48000
SAMPLE_WIDTH = 2
NUM_CHANNELS = 1
FRAME_DURATION = 1.0 / 30.0
LOOP_DELAY = 0.1

_running = True
_lock = threading.Lock()


def _signal_handler(signum, frame):
    global _running
    logger.info('Signal %s received, shutting down...', signum)
    with _lock:
        _running = False


def _cleanup():
    try:
        audio_helper.stop()
    except Exception as e:
        logger.warning('Error stopping audio: %s', e)


def _load_sound_resources():
    try:
        welcome = audio_helper.Sound('welcome.wav')
        wait = audio_helper.Sound('wait.wav')
        later = audio_helper.Sound('later.wav')
        return welcome, wait, later
    except Exception as e:
        logger.error('Failed to load sound resources: %s', e)
        return None, None, None


def _init_camera():
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise RuntimeError('Cannot open camera')
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
        return camera
    except Exception as e:
        logger.error('Failed to initialize camera: %s', e)
        return None


def _init_mixer():
    try:
        return audio_helper.Mixer()
    except Exception as e:
        logger.error('Failed to initialize mixer: %s', e)
        return None


def _init_recognizer():
    try:
        recognizer = cv2.face.EigenFaceRecognizer_create()
        recognizer.read(config.TRAINING_FILE)
        return recognizer
    except Exception as e:
        logger.error('Failed to load training data: %s', e)
        return None


def _init_database():
    try:
        db = Database()
        db.connect()
        return db
    except Exception as e:
        logger.error('Failed to connect to database: %s', e)
        return None


def _process_face(recognizer, db, sound_welcome, sound_wait, sound_later):
    try:
        gray = face.detect_single(face.camera_frame)
        if gray is None:
            sound_later.play()
            return

        label, confidence = recognizer.predict(gray)
        logger.info('Predicted label: %s, confidence: %s', label, confidence)

        if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
            if db is not None:
                db.set_last_knocked(config.POSITIVE_LABEL)
            sound_welcome.play()
            face.unlock_door()
        else:
            sound_wait.play()
    except Exception as e:
        logger.error('Error processing face: %s', e)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    welcome, wait, later = _load_sound_resources()
    if welcome is None or wait is None or later is None:
        _cleanup()
        return

    camera = _init_camera()
    if camera is None:
        _cleanup()
        return

    mixer = _init_mixer()
    if mixer is None:
        _cleanup()
        return

    recognizer = _init_recognizer()
    if recognizer is None:
        _cleanup()
        return

    db = _init_database()
    if db is None:
        _cleanup()
        return

    try:
        with _lock:
            _running = True

        while _running:
            if face.is_button_up():
                _process_face(recognizer, db, welcome, wait, later)

            if camera is not None:
                ret, frame = camera.read()
                if ret:
                    try:
                        face.detect_and_annotate(frame)
                    except Exception as e:
                        logger.warning('Face detection error: %s', e)

            time.sleep(LOOP_DELAY)

    except Exception as e:
        logger.exception('Unexpected error in main loop: %s', e)
    finally:
        _cleanup()
        if camera is not None:
            camera.release()
        logger.info('Program finished.')


if __name__ == '__main__':
    main()

