        return None


def _process_face(recognizer, db, sound_welcome, sound_wait, sound_later):
    try:
        gray = face.detect_single(face.camera_frame)
        if gray is None:
            sound_later.play()
            return

        label, confidence = recognizer.predict(gray)
        logger.info('Predicted label: %s, confidence: %s', label, confidence)

        if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
            if db is not None:
                db.set_last_knocked(config.POSITIVE_LABEL)
            sound_welcome.play()
            face.unlock_door()
        else:
            sound_wait.play()
    except Exception as e:
        logger.error('Error processing face: %s', e)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    welcome, wait, later = _load_sound_resources()
    if welcome is None or wait is None or later is None:
        _cleanup()
        return

    camera = _init_camera()
    if camera is None:
        _cleanup()
        return

    mixer = _init_mixer()
    if mixer is None:
        _cleanup()
        return

    recognizer = _init_recognizer()
    if recognizer is None:
        _cleanup()
        return

    db = _init_database()
    if db is None:
        _cleanup()
        return

    try:
        with _lock:
            _running = True

        while _running:
            if face.is_button_up():
                _process_face(recognizer, db, welcome, wait, later)

            if camera is not None:
                ret, frame = camera.read()
                if ret:
                    try:
                        face.detect_and_annotate(frame)
                    except Exception as e:
                        logger.warning('Face detection error: %s', e)

            time.sleep(LOOP_DELAY)

    except Exception as e:
        logger.exception('Unexpected error in main loop: %s', e)
    finally:
        _cleanup()
        if camera is not None:
            camera.release()
        logger.info('Program finished.')


