import adafruit_bme280
import adafruit_tsl2561
from adafruit_ssd1306 import SSD1306_I2C

# Global resources for cleanup
i2c = None
oled = None
bme280 = None
tsl2561 = None
running = True


def cleanup():
    """Release all hardware resources and clear the display."""
    global oled, i2c
    if oled is not None:
        try:
            oled.fill(0)
            oled.show()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass


def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global running
    running = False


def init_hardware():
    """Initialize I2C bus, BME280, TSL2561, and SSD1306 OLED."""
    global i2c, oled, bme280, tsl2561

    # I2C bus (SCL=GPIO3, SDA=GPIO2)
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Fatal: failed to initialize I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    # BME280 (0x76 / 0x77)
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(i2c, address=0x76)
    except Exception as e:
        print(f"Warning: BME280 not found at 0x76: {e}", file=sys.stderr)
        bme280 = None

    # TSL2561 (0x59)
    try:
        tsl2561 = adafruit_tsl2561.TSL2561(i2c, address=0x59)
    except Exception as e:
        print(f"Warning: TSL2561 not found at 0x59: {e}", file=sys.stderr)
        tsl2561 = None

    # SSD1306 OLED (default 0x3C)
    try:
        oled = SSD1306_I2C(128, 64, i2c)
        oled.fill(0)
        oled.show()
    except Exception as e:
        print(f"Fatal: failed to initialize SSD1306 OLED: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)


def read_sensors():
    """Read temperature, humidity, pressure, and light level."""
    temp = humidity = pressure = light = None

    if bme280 is not None:
        try:
            temp = bme280.temperature
            humidity = bme280.humidity
            pressure = bme280.pressure
        except Exception as e:
            print(f"Warning: BME280 read error: {e}", file=sys.stderr)

    if tsl2561 is not None:
        try:
            light = tsl2561.lux
        except Exception as e:
            print(f"Warning: TSL2561 read error: {e}", file=sys.stderr)

    return temp, humidity, pressure, light


def update_display(temp, humidity, pressure, light):
    """Render sensor data on the OLED display."""
    try:
        oled.fill(0)
        if temp is not None:
            oled.text(f"Temp: {temp:.1f} C", 0, 0, 1)
        else:
            oled.text("Temp: --.0 C", 0, 0, 1)
        if humidity is not None:
            oled.text(f"Humidity: {humidity:.1f} %", 0, 16, 1)
        else:
            oled.text("Humidity: --- %", 0, 16, 1)
        if pressure is not None:
            oled.text(f"Pressure: {pressure:.1f} hPa", 0, 32, 1)
        else:
            oled.text("Pressure: ---- hPa", 0, 32, 1)
        if light is not None:
            oled.text(f"Light: {light:.1f} lux", 0, 48, 1)
        else:
            oled.text("Light: ---- lux", 0, 48, 1)
        oled.show()
    except Exception as e:
        print(f"Warning: OLED update error: {e}", file=sys.stderr)


def main():
    """Main loop: read sensors and update display once per second."""
    global running

    init_hardware()
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        while running:
            temp, humidity, pressure, light = read_sensors()
            update_display(temp, humidity, pressure, light)
            time.sleep(1.0)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

