import os
import time
import signal
import logging
from PIL import Image, UnidentifiedImageError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class AnimatedGif:
    def __init__(self, display, width=None, height=None, folder=None):
        self.display = display
        self.width = width if width is not None else display.width
        self.height = height if height is not None else display.height
        self.folder = folder
        self.gif_files = []
        self.gif_data = []
        self.loop = 0
        self._is_running = False
        self._shutdown_requested = False

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, requesting shutdown.")
        self._shutdown_requested = True

    def load_files(self):
        if not self.folder:
            raise FileNotFoundError("Folder path not provided.")
        if not os.path.isdir(self.folder):
            raise FileNotFoundError(f"Folder not found: {self.folder}")
        try:
            for filename in os.listdir(self.folder):
                if filename.lower().endswith('.gif'):
                    filepath = os.path.join(self.folder, filename)
                    try:
                        with Image.open(filepath) as img:
                            if getattr(img, 'is_animated', False):
                                self.gif_files.append(filepath)
                                logging.info(f"Found animated GIF: {filename}")
                            else:
                                logging.warning(f"Skipping non-animated GIF: {filename}")
                    except (UnidentifiedImageError, OSError) as e:
                        logging.error(f"Error processing {filename}: {e}")
                    except Exception as e:
                        logging.error(f"Unexpected error processing {filename}: {e}")
        except Exception as e:
            logging.error(f"Error listing folder {self.folder}: {e}")
        if not self.gif_files:
            raise FileNotFoundError("No valid GIF files found in the specified folder.")

    def preload(self):
        for filepath in self.gif_files:
            try:
                with Image.open(filepath) as img:
                    duration = img.info.get('duration', 100)
                    loop_count = img.info.get('loop', 0)
                    self.loop = loop_count
                    frames = []
                    for frame_index in range(img.n_frames):
                        img.seek(frame_index)
                        frame = img.convert('RGB')
                        frame = frame.resize((self.width, self.height), Image.NEAREST)
                        frames.append(frame)
                    self.gif_data.append((frames, duration))
            except (UnidentifiedImageError, OSError) as e:
                logging.error(f"Error loading GIF {filepath}: {e}")
            except Exception as e:
                logging.error(f"Unexpected error loading GIF {filepath}: {e}")

    def play(self):
        if not self.gif_data:
            logging.error("No GIF data preloaded. Call preload() first.")
            return False
        if self._shutdown_requested:
            logging.info("Shutdown requested, stopping play.")
            return False
        if self.loop == 0:
            logging.info("Playing GIFs infinitely.")
        elif self.loop > 0:
            logging.info(f"Playing GIFs {self.loop} times.")
        else:
            logging.info("Playing GIFs once.")
        total_loops = self.loop
        current_loop = 0
        while not self._shutdown_requested:
            if total_loops > 0 and current_loop >= total_loops:
                logging.info("All loops completed.")
                return True
            for frames, duration in self.gif_data:
                for frame in frames:
                    if self._shutdown_requested:
                        return False
                    start_time = time.monotonic()
                    try:
                        self.display.display(frame)
                    except Exception as e:
                        logging.error(f"Error displaying frame: {e}")
                        return False
                    elapsed = time.monotonic() - start_time
                    sleep_time = (duration / 1000.0) - elapsed
                    if sleep_time > 0:
                        time.sleep(sleep_time)
        return True

    def run(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)
        self._is_running = True
        try:
            self.load_files()
            self.preload()
            while self._is_running:
                self.play()
        except FileNotFoundError as e:
            logging.error(f"FileNotFoundError: {e}")
        except Exception as e:
            logging.error(f"An error occurred: {e}")
        finally:
            self._is_running = False
            logging.info("Animation stopped.")

    def stop(self):
        self._is_running = False

