import time
import board
import busio
import adafruit_dht
from adafruit_character_lcd.character_lcd_i2c import Character_LCD_I2C

LCD_COLUMNS = 16
LCD_ROWS = 2
DHT_PIN = board.D4
I2C_SDA = board.SDA
I2C_SCL = board.SCL
UPDATE_INTERVAL = 2.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    try:
        return busio.I2C(scl=I2C_SCL, sda=I2C_SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None

def initialize_lcd(i2c_bus):
    try:
        return Character_LCD_I2C(i2c_bus, LCD_COLUMNS, LCD_ROWS)
    except Exception as e:
        print(f"Error initializing LCD: {e}", file=sys.stderr)
        return None

def initialize_dht22(pin):
    try:
        return adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as e:
        print(f"Error initializing DHT22 sensor: {e}", file=sys.stderr)
        return None

def read_sensor_data(dht_sensor):
    try:
        temperature = dht_sensor.temperature
        humidity = dht_sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None for temperature or humidity")
        return temperature, humidity
    except RuntimeError as e:
        print(f"Error reading DHT22 sensor (checksum/bus error): {e}", file=sys.stderr)
        return None, None
    except Exception as e:
        print(f"Unexpected error reading DHT22 sensor: {e}", file=sys.stderr)
        return None, None

def display_data_on_lcd(lcd_display, temperature, humidity):
    try:
        lcd_display.clear()
        lcd_display.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
    except Exception as e:
        print(f"Error displaying data on LCD: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    lcd_display = initialize_lcd(i2c_bus)
    if lcd_display is None:
        sys.exit(1)

    dht_sensor = initialize_dht22(DHT_PIN)
    if dht_sensor is None:
        sys.exit(1)

    try:
        while _running:
            temperature, humidity = read_sensor_data(dht_sensor)
            if temperature is not None and humidity is not None:
                display_data_on_lcd(lcd_display, temperature, humidity)
            time.sleep(UPDATE_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        try:
            lcd_display.clear()
        except Exception:
            pass
        try:
            dht_sensor.exit()
        except Exception:
            pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

