import signal
import sys
import time
import smbus2
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

TSL2561_ADDR = 0x29
TSL2561_COMMAND_BIT = 0xA0
TSL2561_REGISTER_ENABLE = 0x00
TSL2561_REGISTER_CONTROL = 0x01
TSL2561_REGISTER_DATA0LOW = 0x14
TSL2561_REGISTER_ID = 0x12
TSL2561_ID = 0x50
TSL2561_POWER_ON = 0x03
TSL2561_INTEGRATIONTIME_101MS = 0x00
TSL2561_GAIN_1X = 0x00

running = True


def signal_handler(sig, frame):
    global running
    running = False


def read_word_2c(bus, addr, reg):
    high = bus.read_byte_data(addr, reg)
    low = bus.read_byte_data(addr, reg + 1)
    val = (high << 8) | low
    if val >= 0x8000:
        val -= 0x10000
    return val


def init_tsl2561(bus):
    try:
        chip_id = read_word_2c(bus, TSL2561_ADDR, TSL2561_REGISTER_ID)
        if chip_id != TSL2561_ID:
            print(f"Error: TSL2561 not found (ID=0x{chip_id:02X}), expected 0x{TSL2561_ID:02X}")
            return None
        bus.write_byte_data(TSL2561_ADDR, TSL2561_COMMAND_BIT | TSL2561_REGISTER_ENABLE, TSL2561_POWER_ON)
        bus.write_byte_data(TSL2561_ADDR, TSL2561_COMMAND_BIT | TSL2561_REGISTER_CONTROL, TSL2561_INTEGRATIONTIME_101MS | TSL2561_GAIN_1X)
        return bus
    except OSError as e:
        print(f"Error initializing TSL2561: {e}")
        return None


def read_lux(bus):
    try:
        channel0 = read_word_2c(bus, TSL2561_ADDR, TSL2561_REGISTER_DATA0LOW)
        channel1 = read_word_2c(bus, TSL2561_ADDR, TSL2561_REGISTER_DATA0LOW + 2)
        if channel0 == 0:
            return 0.0
        ratio = channel1 / channel0
        if ratio <= 0.5:
            lux = 0.0
        elif ratio <= 0.61:
            lux = 0.033 * channel0
        elif ratio <= 0.67:
            lux = 0.052 * channel0
        elif ratio <= 0.80:
            lux = 0.082 * channel0
        elif ratio <= 1.20:
            lux = 0.128 * channel0
        elif ratio <= 1.50:
            lux = 0.194 * channel0
        elif ratio <= 1.61:
            lux = 0.226 * channel0
        else:
            lux = 0.325 * channel0
        return lux
    except OSError as e:
        print(f"Error reading TSL2561: {e}")
        return None


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    bus = None
    oled = None
    try:
        bus = smbus2.SMBus(1)
        bus = init_tsl2561(bus)
        if bus is None:
            print("Failed to initialize TSL2561. Check wiring and I2C address.")
            return
        oled = ssd1306(i2c(port=1, address=0x3C))
        while running:
            lux = read_lux(bus)
            if lux is not None:
                contrast = int(lux / 100.0 * 255)
                contrast = max(0, min(255, contrast))
                print(f"Lux: {lux:.2f}, Contrast: {contrast}")
                with canvas(oled) as draw:
                    draw.text((0, 0), f"Lux: {lux:.2f}", fill="white")
                    draw.text((0, 12), f"Contrast: {contrast}", fill="white")
            else:
                print("Failed to read lux.")
            time.sleep(1)
    except OSError as e:
        print(f"I2C bus error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.write_byte_data(TSL2561_ADDR, TSL2561_COMMAND_BIT | TSL2561_REGISTER_ENABLE, 0x00)
            except OSError:
                pass
        if oled is not None:
            try:
                oled.clear()
            except Exception:
                pass
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print("Program finished.")


if __name__ == "__main__":
    main()

