import os
import time
import signal
import logging
import spidev
from PIL import Image, ImageOps

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DEFAULT_FRAME_DURATION = 100  # milliseconds

class GifPlayer:
    def __init__(self, display, folder=".", frame_duration=DEFAULT_FRAME_DURATION):
        self.display = display
        self.folder = folder
        self.frame_duration = frame_duration
        self.gif_files = self._get_gif_files()
        self.current_gif_index = 0
        self._running = True

    def _get_gif_files(self):
        try:
            gif_files = [f for f in os.listdir(self.folder) if f.lower().endswith('.gif')]
            if not gif_files:
                logging.warning(f"No GIF files found in folder: {self.folder}")
            return gif_files
        except FileNotFoundError:
            logging.error(f"Folder not found: {self.folder}")
            return []
        except OSError as e:
            logging.error(f"Error accessing folder {self.folder}: {e}")
            return []

    def _convert_to_rgb(self, image):
        if image.mode != 'RGB':
            image = image.convert('RGB')
        return image

    def _pad_to_24bit(self, image):
        width, height = image.size
        padded_width = (width + 3) & ~3
        padded_height = (height + 3) & ~3
        padded_image = Image.new('RGB', (padded_width, padded_height), (0, 0, 0))
        padded_image.paste(image, (0, 0))
        return padded_image

    def _play_gif(self, gif_file):
        try:
            image = Image.open(os.path.join(self.folder, gif_file))
            duration = image.info.get('duration', DEFAULT_FRAME_DURATION)
            image = self._convert_to_rgb(image)
            image = self._pad_to_24bit(image)

            for frame in range(image.n_frames):
                image.seek(frame)
                self.display.display(image)
                time.sleep(duration / 1000.0)
        except Exception as e:
            logging.error(f"Error playing GIF '{gif_file}': {e}")

    def play(self):
        if not self.gif_files:
            logging.warning("No GIF files to play.")
            return
        self._play_gif(self.gif_files[self.current_gif_index])

    def run(self):
        while self._running:
            if self.gif_files:
                self.play()
                self.current_gif_index = (self.current_gif_index + 1) % len(self.gif_files)
            else:
                logging.warning("No GIF files found. Waiting...")
                time.sleep(1)

    def stop(self):
        self._running = False

def signal_handler(signum, frame):
    logging.info(f"Signal {signum} received. Cleaning up...")
    if 'gif_player' in globals():
        gif_player.stop()
    exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        from lib_oled91fd import oled91fd
        display = oled91fd.OLED91fd()
        display.begin()
    except Exception as e:
        logging.error(f"Failed to initialize display: {e}")
        exit(1)

    gif_player = GifPlayer(display, folder=".", frame_duration=DEFAULT_FRAME_DURATION)
    gif_player.run()

