import time
import signal
import board
import busio
import adafruit_ssd1306
import adafruit_dht

# Constants
OLED_WIDTH = 128
OLED_HEIGHT = 64
OLED_I2C_ADDR = 0x3C
DHT_PIN = board.D4
READ_INTERVAL = 2.0

# Global resources for cleanup
i2c = None
oled = None
dht_device = None
running = True

def cleanup():
    """Release resources on exit."""
    global oled, dht_device, i2c
    if oled is not None:
        try:
            oled.fill(0)
            oled.show()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass

def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    global running
    running = False

def init_oled():
    """Initialize the SSD1306 OLED display over I2C."""
    global i2c, oled
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        oled = adafruit_ssd1306.SSD1306_I2C(
            OLED_WIDTH, OLED_HEIGHT, i2c, addr=OLED_I2C_ADDR
        )
        oled.fill(0)
        oled.show()
        return True
    except Exception as e:
        print(f"OLED initialization failed: {e}")
        return False

def init_sensor():
    """Initialize the DHT22 sensor."""
    global dht_device
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        return True
    except Exception as e:
        print(f"DHT22 initialization failed: {e}")
        return False

def read_sensor():
    """Read temperature and humidity from the DHT22 sensor with retry."""
    global dht_device
    if dht_device is None:
        return None, None
    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            print(f"DHT22 read error (attempt {attempt + 1}/3): {e}")
            time.sleep(0.5)
        except Exception as e:
            print(f"Unexpected DHT22 error: {e}")
            break
    return None, None

def display_data(temperature, humidity):
    """Display temperature and humidity on the OLED screen."""
    if oled is None:
        return
    try:
        oled.fill(0)
        oled.text(f"Temp: {temperature:.1f} C", 0, 0, 1)
        oled.text(f"Hum: {humidity:.1f} %", 0, 16, 1)
        oled.show()
    except Exception as e:
        print(f"OLED display error: {e}")

def main():
    """Main loop: read sensor and update OLED every 2 seconds."""
    global running
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    if not init_oled():
        print("Exiting: OLED not available.")
        return

    if not init_sensor():
        print("Exiting: DHT22 not available.")
        cleanup()
        return

    try:
        while running:
            temperature, humidity = read_sensor()
            if temperature is not None and humidity is not None:
                display_data(temperature, humidity)
            else:
                print("Failed to read sensor data after retries.")
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

