import time
import logging
import signal
import sys
from typing import Tuple, Optional

try:
    import smbus2 as smbus
except ImportError:
    import smbus

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

DHT20_I2C_ADDRESS = 0x70
DHT20_STATUS_REGISTER = 0x00
DHT20_DATA_REGISTER = 0x71
DHT20_STATUS_READY_MASK = 0x80
DHT20_CRC_POLYNOMIAL = 0x31
DHT20_CRC_INITIAL_VALUE = 0xFF


class DHT20:
    def __init__(self, i2c_bus_number: int = 1, address: int = DHT20_I2C_ADDRESS):
        self.address = address
        self._bus: Optional[smbus.SMBus] = None
        self._closed = False
        try:
            self._bus = smbus.SMBus(i2c_bus_number)
            time.sleep(0.5)
            if not self._check_status():
                raise RuntimeError("DHT20 not responding or not ready.")
            logging.info("DHT20 initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing DHT20: {e}")
            self._bus = None
            raise

    def _check_status(self) -> bool:
        try:
            status = self._read_register(DHT20_STATUS_REGISTER, 1)[0]
            return (status & DHT20_STATUS_READY_MASK) == DHT20_STATUS_READY_MASK
        except Exception as e:
            logging.error(f"Error checking DHT20 status: {e}")
            return False

    def _read_register(self, register: int, length: int) -> bytes:
        if self._bus is None:
            raise RuntimeError("I2C bus is not initialized.")
        try:
            return self._bus.read_i2c_block_data(self.address, register, length)
        except Exception as e:
            logging.error(f"Error reading from I2C register {register}: {e}")
            raise

    def _calculate_crc(self, data: bytes) -> int:
        crc = DHT20_CRC_INITIAL_VALUE
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20_CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_data(self) -> Tuple[Optional[float], Optional[float], bool]:
        if self._bus is None:
            logging.error("I2C bus is not initialized.")
            return None, None, True

        for attempt in range(5):
            try:
