import asyncio
import time
import random
import json
import logging
import signal
import urllib.request
import urllib.error
import os
import sys

# Configuration
VENTILATION_PIN = 17
IRRIGATION_PIN = 27
TEMP_THRESHOLD_HIGH = 28
TEMP_THRESHOLD_LOW = 23
SOIL_MOISTURE_THRESHOLD = 35
DATA_LOG_FILE = "retail_env_data.json"
ERROR_LOG_FILE = "retail_env_errors.log"
SYNC_ENDPOINT = "http://your_server/api/retail_env_data"
SYNC_INTERVAL = 300
SENSOR_INTERVAL = 60
PUMP_DURATION = 10

# Global state
fan_state = False
pump_state = False
last_sync_index = 0
shutdown_event = asyncio.Event()

# Logging setup
logging.basicConfig(
    filename=ERROR_LOG_FILE,
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def log_error(message):
    logging.error(message)
    print(f"Error: {message}", file=sys.stderr)

def read_config():
    try:
        with open("config.json", "r") as f:
            config = json.load(f)
            return config
    except FileNotFoundError:
        log_error("config.json not found. Using defaults.")
        return {}
    except json.JSONDecodeError as e:
        log_error(f"Invalid JSON in config.json: {e}")
        return {}

def get_last_sync_index():
    try:
        with open("last_sync.txt", "r") as f:
            return int(f.read().strip())
    except FileNotFoundError:
        return 0
    except (ValueError, IOError) as e:
        log_error(f"Error reading last_sync.txt: {e}")
        return 0

def write_last_sync_index(index):
    try:
        with open("last_sync.txt", "w") as f:
            f.write(str(index))
    except IOError as e:
        log_error(f"Error writing last_sync.txt: {e}")

def simulate_sensor_data():
    temperature = random.uniform(15, 35)
    humidity = random.uniform(40, 80)
    soil_moisture = random.uniform(20, 80)
    if random.random() < 0.05:
        return None, None, None
    return temperature, humidity, soil_moisture

def control_ventilation(temperature):
    global fan_state
    if temperature > TEMP_THRESHOLD_HIGH and not fan_state:
        print("Ventilation ON")
        fan_state = True
    elif temperature < TEMP_THRESHOLD_LOW and fan_state:
        print("Ventilation OFF")
        fan_state = False

def control_irrigation(soil_moisture):
    global pump_state
    if soil_moisture < SOIL_MOISTURE_THRESHOLD and not pump_state:
        print("Irrigation ON")
        pump_state = True
        asyncio.run_coroutine_threadsafe(
            asyncio.sleep(PUMP_DURATION), asyncio.get_event_loop()
        )
        print("Irrigation OFF")
        pump_state = False

async def read_sensors():
    while not shutdown_event.is_set():
        temperature, humidity, soil_moisture = simulate_sensor_data()
        if temperature is None:
            log_error("Sensor read failed.")
        else:
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            data = {
                "timestamp": timestamp,
                "temperature": round(temperature, 2),
                "humidity": round(humidity, 2),
                "soil_moisture": round(soil_moisture, 2),
                "fan_state": fan_state,
                "pump_state": pump_state
            }
            try:
                with open(DATA_LOG_FILE, "a") as f:
                    f.write(json.dumps(data) + "\n")
            except IOError as e:
                log_error(f"Error writing to {DATA_LOG_FILE}: {e}")
        await asyncio.sleep(SENSOR_INTERVAL)

async def sync_data():
    global last_sync_index
    while not shutdown_event.is_set():
        try:
            with open(DATA_LOG_FILE, "r") as f:
                lines = f.readlines()
            new_index = max(get_last_sync_index(), last_sync_index)
            if new_index < len(lines):
                data_to_sync = lines[new_index:]
                for line in data_to_sync:
                    try:
                        data = json.loads(line.strip())
                        req_data = json.dumps(data).encode('utf-8')
                        req = urllib.request.Request(
                            SYNC_ENDPOINT,
                            data=req_data,
                            headers={'Content-Type': 'application/json'}
                        )
                        with urllib.request.urlopen(req, timeout=10) as resp:
                            if resp.status == 200:
                                last_sync_index = new_index + data_to_sync.index(line)
                                write_last_sync_index(last_sync_index)
                                print(f"Synced {len(data_to_sync)} records.")
                            else:
                                log_error(f"Sync failed with status {resp.status}")
                    except (json.JSONDecodeError, urllib.error.URLError, OSError) as e:
                        log_error(f"Sync error: {e}")
        except FileNotFoundError:
            log_error(f"{DATA_LOG_FILE} not found.")
        except IOError as e:
            log_error(f"Error reading {DATA_LOG_FILE}: {e}")
        await asyncio.sleep(SYNC_INTERVAL)

def signal_handler(sig, frame):
    print("\nShutting down...")
    shutdown_event.set()

async def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    config = read_config()
    try:
        await asyncio.gather(
            read_sensors(),
            sync_data()
        )
    except asyncio.CancelledError:
        pass

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass
    finally:
        print("Cleanup complete.")

