# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
PARITY = serial.PARITY_NONE
STOPBITS = serial.STOPBITS_ONE
BYTESIZE = serial.EIGHTBITS
TIMEOUT = 1

MQTT_BROKER = "your_mqtt_broker_address"
MQTT_PORT = 1883
MQTT_TOPIC = "manufacturing/monitoring/data"
MQTT_PUBLISH_INTERVAL = 60

DATABASE_FILE = "manufacturing_data.db"
CLOUD_DATA_FILE = "cloud_data.json"

DHT22_PIN = 4
SOUND_SENSOR_PIN = 17

PZEM_SLAVE_ADDR = 1
PEAK_DEMAND_DURATION = 5
GRID_EVENT_MIN = 30
GRID_EVENT_MAX = 60

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    filename="manufacturing_monitor.log",
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# ---------------------------------------------------------------------------
# Global shutdown flag
# ---------------------------------------------------------------------------
_shutdown = False


def _signal_handler(signum, frame):
    global _shutdown
    _shutdown = True
    logging.info(f"Received signal {signum}; initiating graceful shutdown.")


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


# ---------------------------------------------------------------------------
# Database helpers
# ---------------------------------------------------------------------------
def create_database():
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute(
            """
            CREATE TABLE IF NOT EXISTS readings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp TEXT NOT NULL,
                power REAL,
                voltage REAL,
                current REAL,
                temperature REAL,
                humidity REAL,
                sound_level REAL,
                synced INTEGER DEFAULT 0
            )
            """
        )
        conn.commit()
        conn.close()
        logging.info("Database initialized successfully.")
    except sqlite3.Error as e:
        logging.error(f"Database initialization error: {e}")
        sys.exit(1)


def store_data(timestamp, power, voltage, current, temperature, humidity, sound_level):
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute(
            """
            INSERT INTO readings (timestamp, power, voltage, current, temperature, humidity, sound_level)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (timestamp, power, voltage, current, temperature, humidity, sound_level),
        )
        conn.commit()
        conn.close()
        logging.info("Data stored in database.")
    except sqlite3.Error as e:
        logging.error(f"Database storage error: {e}")


def mark_as_synced(row_id):
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute("UPDATE readings SET synced = 1 WHERE id = ?", (row_id,))
        conn.commit()
        conn.close()
        logging.info(f"Row {row_id} marked as synced.")
    except sqlite3.Error as e:
        logging.error(f"Database update error: {e}")


def get_unsynced_data():
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute("SELECT id, timestamp, power, voltage, current, temperature, humidity, sound_level FROM readings WHERE synced = 0")
        rows = cursor.fetchall()
        conn.close()
        return rows
    except sqlite3.Error as e:
        logging.error(f"Database query error: {e}")
        return []


def write_to_cloud_data(rows):
    try:
        with open(CLOUD_DATA_FILE, "w") as f:
            json.dump(rows, f, indent=4)
        logging.info("Cloud data written to file.")
    except IOError as e:
        logging.error(f"Cloud data write error: {e}")


# ---------------------------------------------------------------------------
# Modbus RTU PZEM-004T v3.0
# ---------------------------------------------------------------------------
class PZEM004T:
    def __init__(self, port, baudrate, slave_addr):
        self.port = port
        self.baudrate = baudrate
        self.slave_addr = slave_addr
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                parity=PARITY,
                stopbits=STOPBITS,
                bytesize=BYTESIZE,
                timeout=TIMEOUT,
            )
            logging.info(f"Connected to PZEM-004T on {self.port}.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to connect to PZEM-004T: {e}")
            self.ser = None
            return False

    def read_all(self):
        if not self.ser:
            logging.error("Serial port not open.")
            return None, None, None, None, None, None

        try:
            # Read 24 bytes (3 registers * 8 bytes each) in one RTU frame
            data = self.ser.read(24)
            if len(data) < 24:
                logging.warning("Incomplete Modbus response from PZEM-004T.")
                return None, None, None, None, None, None

            # PZEM-004T v3.0: 3 registers, each 16-bit
            power = self._to_float(data[0:2], data[2:4])
            voltage = self._to_float(data[4:6], data[6:8])
            current = self._to_float(data[8:10], data[10:12])
            energy = self._to_float(data[12:14], data[14:16])
            timestamp = self._to_float(data[16:18], data[18:20])
            return power, voltage, current, energy, timestamp, self._to_float(data[20:22], data[22:24])
        except Exception as e:
            logging.error(f"Error reading PZEM-004T data: {e}")
            return None, None, None, None, None, None

    @staticmethod
    def _to_float(hi, lo):
        val = (hi[0] << 8) | lo[0]
        if val & 0x8000:
            val -= 0x10000
        return val * 0.1

    def close(self):
        if self.ser:
            try:
                self.ser.close()
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")
            finally:
                self.ser = None


