class DHT22:
    def __init__(self, pin):
        self.pin = pin
        self._initialized = False

    def read(self):
        if not self._initialized:
            logging.error("DHT22 not initialized.")
            return None, None

        try:
            # Real DHT22 read logic would go here (e.g., adafruit_dht)
            # For this stub we return simulated values.
            temperature = random.uniform(15, 35)
            humidity = random.uniform(40, 80)
            return temperature, humidity
        except Exception as e:
            logging.error(f"DHT22 read error: {e}")
            return None, None

    def init(self):
        try:
            # Stub: pretend we initialized the GPIO pin.
            self._initialized = True
            logging.info("DHT22 initialized.")
        except Exception as e:
            logging.error(f"DHT22 initialization error: {e}")


