# ---------------------------------------------------------------------------
# MQTT
# ---------------------------------------------------------------------------
def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logging.info("Connected to MQTT broker.")
    else:
        logging.error(f"Failed to connect to MQTT broker. Reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    logging.warning(f"Disconnected from MQTT broker. Reason code: {reason_code}")


def publish_data(client, data):
    try:
        result = client.publish(MQTT_TOPIC, json.dumps(data), qos=1)
        if result.rc == mqtt.MQTT_ERR_SUCCESS:
            logging.info("Data published to MQTT broker.")
        else:
            logging.error(f"Failed to publish data to MQTT broker. Error code: {result.rc}")
    except Exception as e:
        logging.error(f"MQTT publish error: {e}")


