#!/usr/bin/env python3
"""
Hydroponics Controller for Raspberry Pi

Drives a relay-controlled water pump on BCM pin 17 and simulates a DHT11
temperature sensor on BCM pin 4.  Listens on port 12345, accepting only
connections from a whitelisted IP address, and processes JSON commands
to control the pump and query its status.

Usage:
    python3 hydroponics_controller.py [-r RELAY_PIN] [-d DHT_PIN] [-p PORT]
                                      [-i IP_ADDRESS] [-l LOG_FILE]
"""

import argparse
import json
import logging
import socket
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None


class HydroponicsController:
    """Encapsulates pump control and DHT11 simulation."""

    def __init__(self, relay_pin: int, dht_pin: int, temperature: float = 25.0):
        self.relay_pin = relay_pin
        self.dht_pin = dht_pin
        self.temperature = temperature
        self.pump_on = False
        self._initialized = False

        if GPIO is not None:
            try:
                GPIO.setmode(GPIO.BCM)
                GPIO.setup(self.relay_pin, GPIO.OUT, initial=GPIO.LOW)
                self._initialized = True
            except Exception as exc:
                logging.error("GPIO setup failed: %s", exc)
                self._initialized = False
        else:
            logging.warning("RPi.GPIO not available; running in simulation mode.")

    def set_pump(self, state: bool) -> None:
        """Drive the relay and update the internal state."""
        if not self._initialized:
            logging.warning("GPIO not initialized; pump state not changed.")
            return
        try:
            GPIO.output(self.relay_pin, GPIO.HIGH if state else GPIO.LOW)
            self.pump_on = state
            logging.info("Pump turned %s.", "ON" if state else "OFF")
        except Exception as exc:
            logging.error("Failed to set pump state: %s", exc)

    def get_temperature(self) -> float:
        """Return the fixed simulated temperature."""
        return self.temperature

    def cleanup(self) -> None:
        """Release GPIO resources."""
        if self._initialized and GPIO is not None:
            try:
                GPIO.cleanup(self.relay_pin)
            except Exception as exc:
                logging.error("GPIO cleanup error: %s", exc)
        self._initialized = False


def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Hydroponics Controller for Raspberry Pi"
    )
    parser.add_argument(
        "-r", "--relay_pin", type=int, default=17,
        help="BCM GPIO pin for the relay (default: 17)"
    )
    parser.add_argument(
        "-d", "--dht_pin", type=int, default=4,
        help="BCM GPIO pin for the DHT11 (default: 4)"
    )
    parser.add_argument(
        "-p", "--port", type=int, default=12345,
        help="TCP port for the controller (default: 12345)"
    )
    parser.add_argument(
        "-i", "--ip_address", type=str, default="192.168.1.100",
        help="Whitelisted IP address for connections (default: 192.168.1.100)"
    )
    parser.add_argument(
        "-l", "--log_file", type=str, default="hydroponics.log",
        help="Path to the log file (default: hydroponics.log)"
    )
    return parser.parse_args()


def main() -> None:
    args = parse_arguments()

    logging.basicConfig(
        filename=args.log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s"
    )
    logging.info("Starting Hydroponics Controller")
    logging.info("Configuration: relay_pin=%d, dht_pin=%d, port=%d, ip_address=%s",
                 args.relay_pin, args.dht_pin, args.port, args.ip_address)

    controller = HydroponicsController(args.relay_pin, args.dht_pin)

    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as server_socket:
            server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            server_socket.bind(("", args.port))
            server_socket.listen(1)
            logging.info("Listening on port %d", args.port)

            while True:
                try:
                    connection, client_address = server_socket.accept()
                except OSError as exc:
                    logging.error("Accept error: %s", exc)
                    time.sleep(1)
                    continue

                if client_address[0] != args.ip_address:
                    logging.warning("Connection from unauthorized IP: %s", client_address[0])
                    try:
                        connection.sendall(b"Unauthorized IP\n")
                    except OSError:
                        pass
                    connection.close()
                    continue

                logging.info("Connection from %s", client_address[0])

                try:
                    data = connection.recv(1024)
                    if not data:
                        logging.warning("Empty request from %s", client_address[0])
                        continue

                    try:
                        command = json.loads(data.decode("utf-8"))
                    except json.JSONDecodeError as exc:
                        logging.error("Invalid JSON from %s: %s", client_address[0], exc)
                        try:
                            connection.sendall(b"Invalid JSON\n")
                        except OSError:
                            pass
                        continue

                    if not isinstance(command, dict):
                        logging.error("Non-object command from %s", client_address[0])
                        try:
                            connection.sendall(b"Invalid command\n")
                        except OSError:
                            pass
                        continue

                    action = command.get("command")

                    if action == "pump_on":
                        controller.set_pump(True)
                        try:
                            connection.sendall(b"Pump ON\n")
                        except OSError:
                            pass
                    elif action == "pump_off":
                        controller.set_pump(False)
                        try:
                            connection.sendall(b"Pump OFF\n")
                        except OSError:
                            pass
                    elif action == "get_status":
                        status = {
                            "pump": "on" if controller.pump_on else "off",
                            "temperature": controller.get_temperature()
                        }
                        try:
                            connection.sendall(json.dumps(status).encode("utf-8"))
                        except OSError:
                            pass
                    else:
                        logging.warning("Unknown command from %s: %s", client_address[0], action)
                        try:
                            connection.sendall(b"Unknown command\n")
                        except OSError:
                            pass

                except OSError as exc:
                    logging.error("Socket error with %s: %s", client_address[0], exc)
                finally:
                    try:
                        connection.close()
                    except OSError:
                        pass

    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received, shutting down.")
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        controller.cleanup()
        logging.info("Hydroponics Controller stopped.")


if __name__ == "__main__":
    main()

