import serial
import signal
import sys
import time
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

TEMP_MIN, TEMP_MAX = -40.0, 85.0
HUM_MIN, HUM_MAX = 0.0, 100.0
PRES_MIN, PRES_MAX = 800.0, 1200.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _validate(temperature, humidity, pressure):
    if not (TEMP_MIN <= temperature <= TEMP_MAX):
        return False
    if not (HUM_MIN <= humidity <= HUM_MAX):
        return False
    if not (PRES_MIN <= pressure <= PRES_MAX):
        return False
    return True


def _process_line(line):
    line = line.strip()
    if not line:
        return
    parts = line.split(',')
    if len(parts) != 3:
        print(f"Warning: malformed data (expected 3 fields, got {len(parts)}): {line!r}")
        return
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
        pressure = float(parts[2])
    except ValueError:
        print(f"Warning: non-numeric data: {line!r}")
        return
    if _validate(temperature, humidity, pressure):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        print(f"{timestamp} - Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %, Pressure: {pressure:.1f} hPa")
    else:
        print(f"Warning: out-of-range data: {line!r}")


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error: could not open {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Warning: serial read error: {e}", file=sys.stderr)
                time.sleep(0.5)
                continue
            if not raw:
                continue
            try:
                line = raw.decode('ascii', errors='replace')
            except Exception as e:
                print(f"Warning: decode error: {e}", file=sys.stderr)
                continue
            _process_line(line)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Program terminated cleanly.")


if __name__ == '__main__':
    main()

