import time
import signal
import sys

try:
    from gpiozero import CPUTemperature
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _handle_sigint)

def get_cpu_temperature():
    """Return the CPU temperature in degrees Celsius, or None on error."""
    try:
        cpu = CPUTemperature()
        return cpu.temperature
    except FileNotFoundError:
        print("Error: CPU temperature file not found. Check that thermal zone is enabled.")
        return None
    except Exception as exc:
        print(f"Error reading CPU temperature: {exc}")
        return None

def main():
    while _running:
        temp = get_cpu_temperature()
        if temp is not None:
            print(f"CPU Temperature: {temp:.2f} °C")
        else:
            print("Failed to read CPU temperature.")
        for _ in range(5):
            if not _running:
                break
            time.sleep(1)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nProgram terminated")
    finally:
        sys.exit(0)

