import time
import logging
import signal
import sys
from collections import deque

import board
import busio
import adafruit_bmp280

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

I2C_BUS = 1
DEFAULT_SEA_LEVEL_PRESSURE = 1013.25
SAMPLE_SIZE = 100
DISCARD_PERCENTAGE = 0.25
READ_INTERVAL_SECONDS = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def initialize_i2c():
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        logging.error(f"Error initializing I2C bus: {e}")
        return None


def initialize_sensor(i2c_bus):
    try:
        return adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=0x76)
    except ValueError as e:
        logging.error(f"Sensor not found on I2C bus: {e}")
        return None
    except Exception as e:
        logging.error(f"Error initializing BMP280 sensor: {e}")
        return None


def collect_pressure_samples(sensor, sample_size):
    pressure_samples = deque(maxlen=sample_size)
    for _ in range(sample_size):
        try:
            pressure_samples.append(sensor.pressure)
        except OSError as e:
            logging.error(f"I2C bus error reading pressure: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error reading pressure: {e}")
            raise
        time.sleep(0.1)
    return pressure_samples


def calculate_baseline(pressure_samples, discard_percentage):
    n_discard = int(len(pressure_samples) * discard_percentage)
    trimmed_samples = list(pressure_samples)[n_discard:-n_discard]
    if not trimmed_samples:
        raise CalibrationError("Insufficient data for baseline calculation.")
    return sum(trimmed_samples) / len(trimmed_samples)


class CalibrationError(Exception):
    pass


def read_and_print_altitude(sensor, baseline_pressure, sea_level_pressure):
    try:
        altitude = sensor.altitude
        print(f"Altitude: {altitude:.2f} meters")
    except OSError as e:
        logging.error(f"I2C bus error reading altitude: {e}")
    except Exception as e:
        logging.error(f"Unexpected error reading altitude: {e}")
    try:
        sea_level_pressure = sensor.sea_level_pressure
        print(f"Sea Level Pressure: {sea_level_pressure:.2f} hPa")
    except OSError as e:
        logging.error(f"I2C bus error reading sea level pressure: {e}")
    except Exception as e:
        logging.error(f"Unexpected error reading sea level pressure: {e}")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        sys.exit(1)

    try:
        pressure_samples = collect_pressure_samples(sensor, SAMPLE_SIZE)
        baseline_pressure = calculate_baseline(pressure_samples, DISCARD_PERCENTAGE)
        sensor.sea_level_pressure = baseline_pressure
        sea_level_pressure = baseline_pressure
    except CalibrationError as e:
        logging.error(e)
        sea_level_pressure = DEFAULT_SEA_LEVEL_PRESSURE
    except OSError as e:
        logging.error(f"I2C bus error during calibration: {e}")
        sea_level_pressure = DEFAULT_SEA_LEVEL_PRESSURE
    except Exception as e:
        logging.error(f"Unexpected error during calibration: {e}")
        sea_level_pressure = DEFAULT_SEA_LEVEL_PRESSURE

    logging.info(f"Calibration complete. Baseline pressure: {baseline_pressure:.2f} hPa")

    try:
        while _running:
            read_and_print_altitude(sensor, baseline_pressure, sea_level_pressure)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

