import csv
import signal
import sys
import time
from datetime import datetime

import serial

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1.0
CSV_FILE = 'temperature_log.csv'

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def _write_csv_row(writer, row):
    writer.writerow(row)
    writer.flush()


def _open_csv(path):
    try:
        with open(path, 'a', newline='') as fh:
            writer = csv.writer(fh)
            if fh.tell() == 0:
                writer.writerow(['Timestamp', 'Temperature_C', 'Temperature_F'])
                fh.flush()
    except OSError as exc:
        print(f'Error: could not initialise CSV file {path}: {exc}', file=sys.stderr)
        sys.exit(1)


def _convert_celsius_to_fahrenheit(celsius):
    return (celsius * 9.0 / 5.0) + 32.0


def _process_line(line, writer):
    line = line.strip()
    if not line:
        return
    try:
        celsius = float(line)
    except ValueError:
        print(f'Warning: non-numeric data received: {line!r}', file=sys.stderr)
        return
    fahrenheit = _convert_celsius_to_fahrenheit(celsius)
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    _write_csv_row(writer, [timestamp, f'{celsius:.2f}', f'{fahrenheit:.2f}'])


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    _open_csv(CSV_FILE)

    try:
        with serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        ) as ser:
            print(f'Opened {SERIAL_PORT} @ {BAUD_RATE} baud. Reading temperature data...')
            try:
                while running:
                    try:
                        raw = ser.readline()
                    except serial.SerialException as exc:
                        print(f'Warning: serial read error: {exc}', file=sys.stderr)
                        time.sleep(0.5)
                        continue
                    if not raw:
                        continue
                    try:
                        line = raw.decode('ascii', errors='replace')
                    except Exception as exc:
                        print(f'Warning: decode error: {exc}', file=sys.stderr)
                        continue
                    _process_line(line, csv.writer(sys.stdout))
            except KeyboardInterrupt:
                print('\nProgram terminated by user.')
    except serial.SerialException as exc:
        print(f'Error: could not open serial port {SERIAL_PORT}: {exc}', file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f'Unexpected error: {exc}', file=sys.stderr)
        sys.exit(1)


if __name__ == '__main__':
    main()

