import json
import logging
import random
import signal
import sys
import time
import urllib.error
import urllib.request

try:
    import board
    import adafruit_dht
except ImportError:
    print("Missing dependencies. Install with:")
    print("  pip install adafruit-circuitpython-dht")
    print("  sudo apt-get install libgpiod2")
    sys.exit(1)

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "webhook_url": "https://example.com/webhook",
    "dht22_pin": 4,
    "temperature_min": -40,
    "temperature_max": 80,
    "humidity_min": 0,
    "humidity_max": 100,
    "moving_average_window": 5,
    "webhook_retry_delays": [1, 3, 9],
    "webhook_failure_pause": 300,
    "sensor_read_interval": 60,
}

running = True
dht_device = None


def load_config():
    try:
        with open(CONFIG_FILE, "r") as f:
            config = json.load(f)
        merged = DEFAULT_CONFIG.copy()
        merged.update(config)
        return merged
    except FileNotFoundError:
        logging.warning("Config file not found. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError:
        logging.error("Config file is invalid JSON. Using defaults.")
        return DEFAULT_CONFIG.copy()


def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def read_dht22():
    global dht_device
    if dht_device is None:
        try:
            pin = getattr(board, f"D{config['dht22_pin']}")
            dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
        except Exception as e:
            logging.error(f"Failed to initialize DHT22 on pin {config['dht22_pin']}: {e}")
            return None, None
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("DHT22 returned None")
        return temperature, humidity
    except Exception as e:
        logging.error(f"DHT22 read error: {e}")
        return None, None


def validate_data(temperature, humidity):
    if not (config["temperature_min"] <= temperature <= config["temperature_max"]):
        logging.warning(f"Temperature {temperature}°C out of range.")
        return False
    if not (config["humidity_min"] <= humidity <= config["humidity_max"]):
        logging.warning(f"Humidity {humidity}% out of range.")
        return False
    return True


def moving_average(data, window_size):
    if len(data) < window_size:
        return sum(data) / len(data) if data else 0.0
    return sum(data[-window_size:]) / window_size


def generate_simulated_data():
    temperature = random.uniform(20, 30)
    humidity = random.uniform(60, 80)
    return temperature, humidity


def send_webhook(data):
    try:
        payload = json.dumps(data).encode("utf-8")
        req = urllib.request.Request(
            config["webhook_url"],
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            if 200 <= resp.status < 300:
                logging.info("Webhook sent successfully.")
                return True
            logging.error(f"Webhook returned status {resp.status}.")
            return False
    except urllib.error.URLError as e:
        logging.error(f"Webhook URL error: {e}")
        return False
    except Exception as e:
        logging.error(f"Webhook send error: {e}")
        return False


def main():
    global running
    config = load_config()
    logging.basicConfig(
        filename="greenhouse_monitor.log",
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    temperature_history = []
    webhook_failure_count = 0
    try:
        while running:
            temperature, humidity = read_dht22()
            if temperature is None or humidity is None:
                temperature, humidity = generate_simulated_data()
                logging.info("Simulation active: using plausible values.")
            else:
                logging.info(f"Sensor reading: {temperature:.2f}°C, {humidity:.2f}%")
            if not validate_data(temperature, humidity):
                logging.warning("Invalid sensor data. Skipping webhook.")
                time.sleep(config["sensor_read_interval"])
                continue
            temperature_history.append(temperature)
            avg_temperature = moving_average(temperature_history, config["moving_average_window"])
            data = {
                "temperature": round(avg_temperature, 2),
                "humidity": round(humidity, 2),
            }
            success = send_webhook(data)
            if success:
                webhook_failure_count = 0
            else:
                webhook_failure_count += 1
                if webhook_failure_count >= len(config["webhook_retry_delays"]):
                    logging.error(
                        f"Three consecutive webhook failures. Pausing for {config['webhook_failure_pause']} seconds."
                    )
                    time.sleep(config["webhook_failure_pause"])
                    webhook_failure_count = 0
            time.sleep(config["sensor_read_interval"])
    finally:
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

