import signal
import sys
import time
import logging
import threading
import paho.mqtt.client as mqtt
import adafruit_dht
import board

try:
    import config
except ImportError:
    raise ImportError("Error: config.py not found. Create it with the necessary configuration.")

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEGREE_CELSIUS = "\u00B0C"

running = True
client = None
dht_sensor = None


def signal_handler(sig, frame):
    global running
    logger.info("Signal received, shutting down...")
    running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker")
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    logger.warning(f"Disconnected from MQTT broker, reason code: {reason_code}")


def publish_mqtt_message(client, topic, payload):
    try:
        full_topic = f"homie/{config.homieclientid}/{topic}"
        client.publish(full_topic, str(payload), retain=True, qos=1)
    except Exception as e:
        logger.error(f"Error publishing to MQTT topic {topic}: {e}")


def publish_homie_discovery(client):
    publish_mqtt_message(client, "$homie", "4.0")
    publish_mqtt_message(client, "$name", config.homieclientname)
    publish_mqtt_message(client, "$nodes", config.homienodes)

    node = config.homienodes
    publish_mqtt_message(client, f"{node}/$name", "DHT22 Sensor")
    publish_mqtt_message(client, f"{node}/$properties", "temperature,humidity")

    publish_mqtt_message(client, f"{node}/temperature/$name", "Temperature")
    publish_mqtt_message(client, f"{node}/temperature/$unit", DEGREE_CELSIUS)
    publish_mqtt_message(client, f"{node}/temperature/$datatype", "float")
    publish_mqtt_message(client, f"{node}/temperature/$settable", "false")

    publish_mqtt_message(client, f"{node}/humidity/$name", "Humidity")
    publish_mqtt_message(client, f"{node}/humidity/$unit", "%")
    publish_mqtt_message(client, f"{node}/humidity/$datatype", "float")
    publish_mqtt_message(client, f"{node}/humidity/$settable", "false")


def connect_mqtt():
    global client
    client = mqtt.Client(
        mqtt.CallbackAPIVersion.VERSION2,
        client_id=config.mqttclientid,
        clean_session=True
    )
    if config.mqttusername and config.mqttpassword:
        client.username_pw_set(config.mqttusername, config.mqttpassword)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect

    try:
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        client.loop_start()
        time.sleep(2)
        return True
    except Exception as e:
        logger.error(f"Error connecting to MQTT broker: {e}")
        return False


def read_dht22():
    global dht_sensor
    if dht_sensor is None:
        try:
            dht_sensor = adafruit_dht.DHT22(board.D4)
        except Exception as e:
            logger.error(f"Failed to initialize DHT22 sensor: {e}")
            return None, None

    for attempt in range(3):
        try:
            temperature = dht_sensor.temperature
            humidity = dht_sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logger.warning(f"DHT22 returned None on attempt {attempt + 1}")
        except RuntimeError as e:
            logger.warning(f"DHT22 read error on attempt {attempt + 1}: {e}")
        except Exception as e:
            logger.error(f"Unexpected error reading DHT22 on attempt {attempt + 1}: {e}")
        if attempt < 2:
            time.sleep(2)
    return None, None


def publish_sensor_data(temperature, humidity):
    if temperature is not None and humidity is not None:
        publish_mqtt_message(client, f"{config.homienodes}/temperature", f"{temperature:.1f}")
        publish_mqtt_message(client, f"{config.homienodes}/humidity", f"{humidity:.1f}")
        logger.info(f"Published: Temperature = {temperature:.1f} {DEGREE_CELSIUS}, Humidity = {humidity:.1f} %")
    else:
        logger.error("Failed to read sensor data after retries.")


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not connect_mqtt():
        logger.error("Failed to connect to MQTT broker. Exiting.")
        return

    publish_homie_discovery(client)

    try:
        while running:
            temperature, humidity = read_dht22()
            publish_sensor_data(temperature, humidity)
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        if client:
            client.loop_stop()
            client.disconnect()
        if dht_sensor:
            try:
                dht_sensor.exit()
            except Exception:
                pass
        logger.info("Cleanup complete.")


if __name__ == "__main__":
    main()

