import time
import signal
import sys
import board
import busio
import adafruit_bmp280

# Constants
I2C_BUS = 1
SAMPLING_INTERVAL = 1.0
BASELINE_DURATION = 10.0
MIN_BASELINE_READINGS = 3

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def initialize_i2c():
    """Initializes the I2C bus using board.SCL and board.SDA."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_bmp280(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        return adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=0x76)
    except ValueError as e:
        print(f"BMP280 not found on I2C bus: {e}")
        return None
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None

def collect_baseline_pressure(bmp280, duration):
    """Collects baseline pressure readings, excluding the first two."""
    print("Collecting baseline pressure. Please wait...")
    readings = []
    start_time = time.monotonic()
    while time.monotonic() - start_time < duration:
        try:
            pressure = bmp280.pressure
            readings.append(pressure)
            time.sleep(SAMPLING_INTERVAL)
        except OSError as e:
            print(f"Error reading pressure during baseline: {e}")
            time.sleep(SAMPLING_INTERVAL)
        except Exception as e:
            print(f"Unexpected error reading pressure during baseline: {e}")
            time.sleep(SAMPLING_INTERVAL)

    if len(readings) < MIN_BASELINE_READINGS:
        print("Error: Insufficient baseline readings. Exiting.")
        return None

    baseline_pressure = sum(readings) / len(readings)
    print(f"Baseline pressure: {baseline_pressure:.2f} hPa")
    return baseline_pressure

def read_altitude(bmp280, baseline_pressure):
    """Reads and calculates altitude relative to the baseline pressure."""
    try:
        current_pressure = bmp280.pressure
        altitude = 44330.0 * (1.0 - (current_pressure / baseline_pressure) ** (1.0 / 5.255))
        return altitude
    except OSError as e:
        print(f"Error reading altitude: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading altitude: {e}")
        return None

def main():
    """Main function to run the altitude monitoring."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    bmp280 = initialize_bmp280(i2c_bus)
    if bmp280 is None:
        sys.exit(1)

    baseline_pressure = collect_baseline_pressure(bmp280, BASELINE_DURATION)
    if baseline_pressure is None:
        sys.exit(1)

    print("Starting altitude monitoring...")
    while _running:
        altitude = read_altitude(bmp280, baseline_pressure)
        if altitude is not None:
            print(f"Relative altitude: {altitude:.2f} meters")
        time.sleep(SAMPLING_INTERVAL)

    print("Exiting gracefully.")

if __name__ == "__main__":
    main()

