HUM_THRESHOLD = 70.0

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("urban_monitor")

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _cleanup():
    if GPIO is not None:
        try:
            GPIO.output(FAN_PIN, GPIO.LOW)
        except Exception:
            pass
        try:
            GPIO.cleanup()
        except Exception:
            pass


def read_dht11():
    if GPIO is None:
        raise RuntimeError("RPi.GPIO not available on this platform")
    import board
    import adafruit_dht
    pin = getattr(board, f"D{DHT_PIN}")
    sensor = adafruit_dht.DHT11(pin, use_pulseio=False)
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return temperature, humidity
    finally:
        try:
            sensor.exit()
        except Exception:
            pass


def control_fan(temperature, humidity):
    if temperature > TEMP_THRESHOLD or humidity > HUM_THRESHOLD:
        GPIO.output(FAN_PIN, GPIO.HIGH)
        return "ON"
    GPIO.output(FAN_PIN, GPIO.LOW)
    return "OFF"


def log_reading(temperature, humidity, fan_state):
    timestamp = datetime.now().isoformat(timespec="seconds")
    log_message = f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%, Fan: {fan_state}"
    try:
        with open(LOG_FILE, "a") as f:
            f.write(f"{timestamp} - {log_message}\n")
    except OSError as e:
        log.error("Failed to write log file: %s", e)


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    if GPIO is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            log.error("GPIO initialization failed: %s", e)
            _cleanup()
            sys.exit(1)
    else:
        log.warning("RPi.GPIO not available; running in simulation mode.")

    fan_state = "OFF"
    try:
        for i in range(NUM_READINGS):
            if not _running:
                break
            try:
                temperature, humidity = read_dht11()
            except Exception as e:
                log.error("DHT11 read failed: %s", e)
                time.sleep(READ_INTERVAL)
                continue

            log_reading(temperature, humidity, fan_state)
            fan_state = control_fan(temperature, humidity)
            print(f"Reading {i + 1}/{NUM_READINGS}: Temp={temperature:.1f}C, Hum={humidity:.1f}%, Fan={fan_state}")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL)
    finally:
        _cleanup()


