SUPPLY_INA219_ADDRESS = 0x41
BATTERY_INA219_ADDRESS = 0x42
SUPPLY_SHUNT_RESISTOR = 0.00725
BATTERY_SHUNT_RESISTOR = 0.005
LOOP_INTERVAL = 2

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_register(bus, address, register):
    try:
        return bus.read_byte_data(address, register)
    except OSError as e:
        logging.error(f"I2C read error at 0x{address:02X}, reg 0x{register:02X}: {e}")
        return None

def read_ina219(bus, address, shunt_resistor):
    try:
        config = read_register(bus, address, 0x00)
        if config is None:
            return None
        if config != 0x2100:
            logging.warning(f"INA219 config mismatch at 0x{address:02X}: 0x{config:04X}")
        power = read_register(bus, address, 0x03)
        if power is None:
            return None
        voltage = read_register(bus, address, 0x04)
        if voltage is None:
            return None
        current = read_register(bus, address, 0x05)
        if current is None:
            return None
        return {
            'voltage': voltage / 100.0,
            'current': current / 1000.0,
            'power': power / 1000.0
        }
    except OSError as e:
        logging.error(f"I2C read error at 0x{address:02X}: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS)
        supply_data = read_ina219(bus, SUPPLY_INA219_ADDRESS, SUPPLY_SHUNT_RESISTOR)
        battery_data = read_ina219(bus, BATTERY_INA219_ADDRESS, BATTERY_SHUNT_RESISTOR)
        if supply_data is None:
            logging.error("Supply INA219 not responding; continuing with battery-only monitoring.")
        if battery_data is None:
            logging.error("Battery INA219 not responding; continuing with supply-only monitoring.")
        while running:
            if supply_data is not None:
                print(f"Supply Voltage: {supply_data['voltage']:.2f} V")
                print(f"Supply Current: {supply_data['current']:.2f} mA")
                print(f"Supply Power: {supply_data['power']:.2f} mW")
