import time
import json
import logging
import threading
import signal
import sys
import board
import adafruit_dht
from gpiozero import PWMLED

# --- Configuration ---
DHT_PIN = board.D4
CLOUD_ENDPOINT = "http://example.com/api/data"
TEMPERATURE_MIN = 18.0
TEMPERATURE_MAX = 28.0
HUMIDITY_MIN = 30.0
HUMIDITY_MAX = 80.0
READ_INTERVAL = 5
UPLOAD_INTERVAL = 60
MAX_RETRIES = 3
RETRY_DELAY = 2
PWM_FREQUENCY = 1000

# --- Logging Setup ---
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
    handlers=[
        logging.FileHandler("greenhouse_monitor.log"),
        logging.StreamHandler(sys.stdout),
    ],
)

# --- Global State ---
last_temperature = None
last_humidity = None
last_color = None
last_brightness = None
last_alert = None
running = True

# --- GPIO Setup ---
leds = {}
try:
    for name, pins in [
        ("LED1", (17, 22, 27)),
        ("LED2", (5, 6, 13)),
        ("LED3", (19, 26, 16)),
    ]:
        r, g, b = pins
        leds[name] = {
            "red": PWMLED(r, frequency=PWM_FREQUENCY),
            "green": PWMLED(g, frequency=PWM_FREQUENCY),
            "blue": PWMLED(b, frequency=PWM_FREQUENCY),
        }
except Exception as e:
    logging.error(f"GPIO initialization failed: {e}")
    sys.exit(1)

# --- DHT22 Sensor Setup ---
dht_device = None
try:
    dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
except Exception as e:
    logging.error(f"DHT22 initialization failed: {e}")
    for led in leds.values():
        for led_type in led.values():
            led_type.close()
    sys.exit(1)

# --- Color Mapping ---
def map_color(temperature):
    if temperature is None:
        return (0, 0, 0)
    if temperature < 20:
        return (0, 0, 128)
    elif temperature < 25:
        return (0, 128, 0)
    elif temperature < 28:
        return (128, 255, 0)
    else:
        return (255, 0, 0)

# --- Brightness Mapping ---
def map_brightness(humidity):
    if humidity is None:
        return 0.0
    if humidity < 40:
        return 0.0
    elif humidity < 60:
        return (humidity - 40) / 20.0
    elif humidity < 80:
        return (humidity - 60) / 20.0
    else:
        return 1.0

# --- Sensor Reading ---
def read_sensor():
    global last_temperature, last_humidity, last_color, last_brightness, last_alert
    for attempt in range(MAX_RETRIES):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                last_temperature = temperature
                last_humidity = humidity
                color = map_color(temperature)
                brightness = map_brightness(humidity)
                last_color = color
                last_brightness = brightness
                alert = None
                if temperature < TEMPERATURE_MIN or temperature > TEMPERATURE_MAX:
                    alert = "Temperature Alert"
                if humidity < HUMIDITY_MIN or humidity > HUMIDITY_MAX:
                    alert = "Humidity Alert"
                last_alert = alert
                logging.info(
                    f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%, "
                    f"Color: R={color[0]}, G={color[1]}, B={color[2]}, "
                    f"Brightness: {brightness:.2f}, Alert: {alert}"
                )
                return
        except RuntimeError as e:
            logging.warning(f"DHT22 read error (attempt {attempt + 1}/{MAX_RETRIES}): {e}")
        except Exception as e:
            logging.error(f"Unexpected DHT22 error: {e}")
        if attempt < MAX_RETRIES - 1:
            time.sleep(RETRY_DELAY)
    logging.error("DHT22 read failed after all retries. Using last known values.")
    if last_temperature is not None and last_humidity is not None:
        color = map_color(last_temperature)
        brightness = map_brightness(last_humidity)
        alert = last_alert
        logging.info(
