            logging.warning(f"DHT22 read error (attempt {attempt + 1}/{MAX_RETRIES}): {e}")
        except Exception as e:
            logging.error(f"Unexpected DHT22 error: {e}")
        if attempt < MAX_RETRIES - 1:
            time.sleep(RETRY_DELAY)
    logging.error("DHT22 read failed after all retries. Using last known values.")
    if last_temperature is not None and last_humidity is not None:
        color = map_color(last_temperature)
        brightness = map_brightness(last_humidity)
        alert = last_alert
        logging.info(
            f"Using last known values: Temp={last_temperature:.1f}°C, "
            f"Hum={last_humidity:.1f}%, Color=R={color[0]}, G={color[1]}, B={color[2]}, "
            f"Brightness={brightness:.2f}, Alert={alert}"
        )
    else:
        logging.error("No last known values available.")

# --- Cloud Upload ---
def upload_data():
    payload = {
        "temperature": last_temperature,
        "humidity": last_humidity,
