# Program: Greenhouse Environment Monitor
# Description: Reads temperature and humidity from an AHT20 sensor on a Raspberry Pi 5.
# Hardware: Raspberry Pi 5, AHT20 sensor on I2C bus 1 (board.SCL / board.SDA).

import time
import board
import busio
import adafruit_ahtx2

# --- Configuration -----------------------------------------------------------
READ_INTERVAL_SECONDS = 5          # Delay between successful readings
REINITIALIZE_INTERVAL_SECONDS = 5  # Delay before retrying I2C / sensor init
TEMP_MIN_C, TEMP_MAX_C = -40.0, 85.0
HUM_MIN_PCT, HUM_MAX_PCT = 0.0, 100.0

# --- Globals -----------------------------------------------------------------
i2c = None
sensor = None
running = True


def init_sensor():
    """Re-initialize the I2C bus and AHT20 sensor; return the sensor object."""
    global i2c, sensor
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - I2C bus initialization failed: {exc}")
        time.sleep(REINITIALIZE_INTERVAL_SECONDS)
        return init_sensor()

    try:
        sensor = adafruit_ahtx2.AHTx2(i2c)
    except Exception as exc:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - AHT20 sensor initialization failed: {exc}")
        time.sleep(REINITIALIZE_INTERVAL_SECONDS)
        return init_sensor()

    # Probe the sensor to confirm it is present on the bus.
    try:
        _ = sensor.temperature
    except Exception as exc:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - AHT20 sensor not detected: {exc}")
        time.sleep(REINITIALIZE_INTERVAL_SECONDS)
        return init_sensor()

    return sensor


def read_environment():
    """Read temperature and humidity from the AHT20 sensor.

    Returns (temperature, humidity) or (None, None) on error.
    """
    try:
        temperature = sensor.temperature
        humidity = sensor.relative_humidity
    except Exception as exc:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Error reading sensor data: {exc}")
        return None, None

    if temperature is None or humidity is None:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Sensor returned None values.")
        return None, None

    if not (TEMP_MIN_C <= temperature <= TEMP_MAX_C):
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Temperature out of range: {temperature:.1f} C")
        return None, None

    if not (HUM_MIN_PCT <= humidity <= HUM_MAX_PCT):
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Humidity out of range: {humidity:.1f} %")
        return None, None

    return temperature, humidity


def display_environment(temperature, humidity):
    """Print the temperature and humidity to the console."""
    print(f"Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")


def cleanup():
    """Release I2C resources."""
    global i2c
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
        i2c = None


def main():
    """Main loop: initialize sensor, read every 5 s, handle errors."""
    global running
    sensor = init_sensor()

    while running:
        temperature, humidity = read_environment()
        if temperature is not None and humidity is not None:
            display_environment(temperature, humidity)
        time.sleep(READ_INTERVAL_SECONDS)

    print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Program stopped by user.")
    cleanup()


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Program stopped by user.")
    finally:
        cleanup()

