import subprocess
import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

# --- Configuration -----------------------------------------------------------
FAN_PIN = 14            # BCM GPIO14 (physical pin 8)
PWM_FREQ = 100          # Hz
POLL_INTERVAL = 5       # seconds
TEMP_CHECK_INTERVAL = 2 # seconds between vcgencmd calls

# --- Logging -----------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("fanctl")

# --- Globals -----------------------------------------------------------------
fan = None
last_duty = 100.0       # fail-safe default
running = True


def cleanup(signum=None, frame=None):
    """Stop PWM and release resources on exit."""
    global fan, running
    running = False
    if fan is not None:
        try:
            fan.value = 0.0
            fan.close()
        except Exception as exc:
            log.warning("Error during fan cleanup: %s", exc)
    if signum is not None:
        log.info("Received signal %s; exiting.", signum)
        sys.exit(0)


def get_cpu_temp():
    """Return CPU temperature in degrees Celsius, or None on failure."""
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        # Output looks like: temp=42.8'C
        temp_str = result.stdout.strip()
        if not temp_str.startswith("temp="):
            log.error("Unexpected vcgencmd output: %s", temp_str)
            return None
        return float(temp_str.split("=")[1].split("'")[0])
    except subprocess.TimeoutExpired:
        log.error("vcgencmd timed out.")
    except subprocess.CalledProcessError as exc:
        log.error("vcgencmd failed (rc=%s): %s", exc.returncode, exc.stderr.strip())
    except (IndexError, ValueError) as exc:
        log.error("Could not parse temperature output: %s", exc)
    except FileNotFoundError:
        log.error("vcgencmd not found on this system.")
    return None


def duty_for_temp(temp):
    """Map a CPU temperature to a fan duty cycle (0-100 %)."""
    if temp is None:
        return last_duty
    if temp > 70:
        return 100.0
    if temp > 65:
        return 80.0
    if temp > 60:
        return 60.0
    if temp > 55:
        return 40.0
    if temp > 50:
        return 20.0
    return 0.0


def main():
    global fan, last_duty

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize PWM output device
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
        log.info("PWM fan control started on GPIO%d @ %d Hz.", FAN_PIN, PWM_FREQ)
    except Exception as exc:
        log.error("Failed to initialize GPIO%d: %s", FAN_PIN, exc)
        sys.exit(1)

    last_check = 0.0

    while running:
        now = time.monotonic()
        if now - last_check >= TEMP_CHECK_INTERVAL:
            last_check = now
            temp = get_cpu_temp()
            if temp is not None:
                duty = duty_for_temp(temp)
                try:
                    fan.value = duty / 100.0
                    last_duty = duty
                    log.info("CPU %.1f°C -> fan duty %.0f%%", temp, duty)
                except Exception as exc:
                    log.error("Failed to set fan duty: %s", exc)
            else:
                log.error("Temperature read failed; retaining last duty (%.0f%%).", last_duty)

        time.sleep(POLL_INTERVAL)

    cleanup()


if __name__ == "__main__":
    main()

