import signal
import sys
import time
import paho.mqtt.client as mqtt
import adafruit_dht
import board

try:
    import config
except ImportError:
    raise ImportError("Error: config.py not found. Create it with the necessary configuration.")

DEGREE_CELSIUS = "\u00B0C"

running = True


def signal_handler(sig, frame):
    global running
    running = False


def publish_mqtt(client, topic, payload):
    try:
        full_topic = f"homie/{config.homieclientid}/{topic}"
        info = client.publish(full_topic, str(payload), qos=1)
        info.wait_for_publish(timeout=5)
    except Exception as e:
        print(f"Error publishing to MQTT: {e}")


def read_dht22(sensor):
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None for temperature or humidity.")
        return temperature, humidity
    except RuntimeError as e:
        print(f"DHT22 read error (retry): {e}")
        raise
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}")
        raise


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    client = None
    sensor = None

    try:
        sensor = adafruit_dht.DHT22(getattr(board, f"D{config.dhtgpiopin}"), use_pulseio=False)

        client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
        if hasattr(config, 'mqttusername') and hasattr(config, 'mqttpassword'):
            client.username_pw_set(config.mqttusername, config.mqttpassword)
        client.connect(config.mqttbroker, config.mqttport, 60)
        client.loop_start()

        while running:
            try:
                temperature, humidity = read_dht22(sensor)
                publish_mqtt(client, "status", "online")
