import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 2.0
POLL_INTERVAL = 1.0
TEMP_THRESHOLD = 30.0
HUM_THRESHOLD = 70.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        ser.reset_input_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening {port}: {e}", file=sys.stderr)
        return None

def read_sensor_data(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return line
    except serial.SerialException as e:
        print(f"Serial I/O error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}", file=sys.stderr)
        return None

def parse_sensor_data(data):
    if not data:
        return None, None
    try:
        parts = data.split(',')
        if len(parts) != 2:
            print(f"Malformed data (expected 2 fields, got {len(parts)}): {data}", file=sys.stderr)
            return None, None
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError as e:
        print(f"Error parsing data '{data}': {e}", file=sys.stderr)
        return None, None

def check_thresholds(temperature, humidity):
    if temperature is None or humidity is None:
        return False
    if temperature > TEMP_THRESHOLD or humidity > HUM_THRESHOLD:
        print(f"ALERT: Temperature {temperature:.1f}°C, Humidity {humidity:.1f}% exceeds thresholds.")
        return True
    return False

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            sensor_data = read_sensor_data(serial_connection)
            if sensor_data:
                temperature, humidity = parse_sensor_data(sensor_data)
                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                    check_thresholds(temperature, humidity)
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected runtime error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial connection closed.")

if __name__ == "__main__":
    main()

