import signal
import sys
import time
import smbus2

I2C_BUS = 1
I2C_ADDR = 0x38
MEAS_INTERVAL = 5.0

running = True

def _handle_sigint(signum, frame):
    global running
    running = False

def _crc8(data):
    crc = 0xFF
    for b in data:
        crc ^= b
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ 0x31) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def _read_reg(bus, reg, length):
    return bytes(bus.read_i2c_block_data(I2C_ADDR, reg, length))

def _write_reg(bus, reg, data):
    bus.write_i2c_block_data(I2C_ADDR, reg, data)

def main():
    global running
    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            _write_reg(bus, 0x01, [0x01])
            time.sleep(0.02)
        except OSError:
            print("Error: AHT20/DHT20 not detected at address 0x38.", file=sys.stderr)
            sys.exit(1)

        while running:
            try:
                data = _read_reg(bus, 0x00, 7)
            except OSError as e:
                print(f"Error: I2C read failed: {e}", file=sys.stderr)
                time.sleep(MEAS_INTERVAL)
                continue

            if len(data) != 7:
                print("Error: unexpected data length.", file=sys.stderr)
                time.sleep(MEAS_INTERVAL)
                continue

            if data[0] & 0x80:
                print("Error: sensor not ready (status bit 7 set).", file=sys.stderr)
                time.sleep(MEAS_INTERVAL)
                continue

            if _crc8(data[:6]) != data[6]:
                print("CRC error: data mismatch.", file=sys.stderr)
                time.sleep(MEAS_INTERVAL)
                continue

            temp_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4))
            hum_raw = ((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]

            temp_c = temp_raw * 200.0 / 1048576.0
            temp_f = temp_c * 9.0 / 5.0 + 32.0
            hum = hum_raw * 100.0 / 1048576.0

            ts = time.strftime("%Y-%m-%d %H:%M:%S")
            print(f"[{ts}] Temperature: {temp_c:.2f} C / {temp_f:.2f} F  Humidity: {hum:.2f} %")

            time.sleep(MEAS_INTERVAL)
    finally:
        bus.close()

if __name__ == "__main__":
    main()

