import signal
import sys
import time
import logging
from smbus2 import SMBus, i2c_msg

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

I2C_BUS = 1
SUPPLY_INA219_ADDRESS = 0x41
BATTERY_INA219_ADDRESS = 0x40
SHUNT_RESISTOR_SUPPLY = 0.00725
SHUNT_RESISTOR_BATTERY = 0.005

running = True


def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def read_register(bus, address, register):
    try:
        msg = i2c_msg.write(address, [register])
        bus.i2c_rdwr(msg)
        return None
    except OSError as e:
        logger.error(f"I2C read error at 0x{address:02X}, reg 0x{register:02X}: {e}")
        return None
    except Exception as e:
        logger.error(f"Unexpected error reading register 0x{register:02X} from 0x{address:02X}: {e}")
        return None


def write_register(bus, address, register, value):
    try:
        msg = i2c_msg.write(address, [register, value])
        bus.i2c_rdwr(msg)
        return None
    except OSError as e:
        logger.error(f"I2C write error at 0x{address:02X}, reg 0x{register:02X}: {e}")
        return None
    except Exception as e:
        logger.error(f"Unexpected error writing register 0x{register:02X} to 0x{address:02X}: {e}")
        return None


def read_ina219(bus, address, shunt_resistor):
    try:
        config = read_register(bus, address, 0x00)
        if config is None:
            return None
        if config != 0x2100:
            logger.warning(f"INA219 config mismatch at 0x{address:02X}: 0x{config:04X}")
        bus_voltage = read_register(bus, address, 0x01)
        if bus_voltage is None:
            return None
        current = read_register(bus, address, 0x03)
        if current is None:
            return None
        power = read_register(bus, address, 0x05)
        if power is None:
            return None
        voltage = (bus_voltage[0] << 8) | bus_voltage[1]
        current_mA = (current[0] << 8) | current[1]
        power_mW = (power[0] << 8) | power[1]
        voltage_V = voltage * 0.001
        current_mA /= 1000
        power_mW /= 1000
        return voltage_V, current_mA, power_mW
    except Exception as e:
        logger.error(f"Error reading INA219 at 0x{address:02X}: {e}")
        return None


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
        logger.info(f"I2C bus {I2C_BUS} opened successfully.")

        supply_data = read_ina219(bus, SUPPLY_INA219_ADDRESS, SHUNT_RESISTOR_SUPPLY)
        battery_data = read_ina219(bus, BATTERY_INA219_ADDRESS, SHUNT_RESISTOR_BATTERY)

        if supply_data is not None:
            v_supply, i_supply, p_supply = supply_data
            logger.info(f"Supply: V={v_supply:.3f}V, I={i_supply:.3f}mA, P={p_supply:.3f}mW")
        else:
            logger.warning("Supply INA219 not detected or read failed.")

        if battery_data is not None:
            v_battery, i_battery, p_battery = battery_data
            logger.info(f"Battery: V={v_battery:.3f}V, I={i_battery:.3f}mA, P={p_battery:.3f}mW")
        else:
            logger.warning("Battery INA219 not detected or read failed.")

        while running:
            time.sleep(1)

    except OSError as e:
        logger.error(f"I2C bus error: {e}")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
                logger.info("I2C bus closed.")
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")


if __name__ == "__main__":
    main()

