import subprocess
import time
import logging
import signal
import sys

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    logging.error("gpiozero is required. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PIN = 14
FREQ = 100
INTERVAL = 5
MIN_SPEED = 0.0
MAX_SPEED = 100.0
STEP = 10.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def get_fan_speed(temp):
    if temp < 40:
        return MIN_SPEED
    if temp < 50:
        return 25.0
    if temp < 60:
        return 50.0
    if temp < 70:
        return 75.0
    return MAX_SPEED


def get_temp():
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        return float(result.stdout.split("=")[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, IndexError, ValueError) as e:
        logging.warning("Failed to read temperature: %s", e)
        return None


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    fan = None
