import smbus
import time
import signal
import sys

I2C_BUS = 0
MCP23017_ADDR = 0x20
SWITCH_PIN = 7
LED_PIN = 0
POLL_INTERVAL = 0.1

running = True
bus = None

def signal_handler(signum, frame):
    global running
    running = False

def write_register(bus, addr, reg, value):
    try:
        bus.write_byte_data(addr, reg, value)
    except OSError as e:
        print(f"I2C write error (reg=0x{reg:02X}): {e}", file=sys.stderr)
        raise

def read_register(bus, addr, reg):
    try:
        return bus.read_byte_data(addr, reg)
    except OSError as e:
        print(f"I2C read error (reg=0x{reg:02X}): {e}", file=sys.stderr)
        raise

def main():
    global bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Verify device presence
        read_register(bus, MCP23017_ADDR, 0x00)  # IOCON
    except OSError:
        print(f"No MCP23017 found at address 0x{MCP23017_ADDR:02X} on bus {I2C_BUS}", file=sys.stderr)
        sys.exit(1)

    # Configure switch input with pull-up
    write_register(bus, MCP23017_ADDR, 0x0C, 1 << SWITCH_PIN)  # IODIRA bit
    # Configure LED output
    write_register(bus, MCP23017_ADDR, 0x0A, 1 << LED_PIN)  # IODIRB bit
    # Enable pull-up on switch input
    write_register(bus, MCP23017_ADDR, 0x0D, 1 << SWITCH_PIN)
    # Set LED off initially
    write_register(bus, MCP23017_ADDR, 0x14, 0)  # GPIOA

    led_state = 0
    switch_state = 1  # pull-up enabled -> initial read is HIGH

    try:
        while running:
            try:
                switch_state = read_register(bus, MCP23017_ADDR, 0x12) & (1 << SWITCH_PIN)
            except OSError:
                # Device may have been disconnected; retry next cycle
                time.sleep(POLL_INTERVAL)
                continue

            if switch_state == 0:
                led_state = 1
            else:
                led_state = 0

            try:
                write_register(bus, MCP23017_ADDR, 0x14, led_state)
            except OSError:
                # Device may have been disconnected; retry next cycle
                time.sleep(POLL_INTERVAL)
                continue

            if led_state == 1:
                print("Led ON")
            else:
                print("Led OFF")

            time.sleep(POLL_INTERVAL)
    finally:
        if bus is not None:
            try:
                write_register(bus, MCP23017_ADDR, 0x14, 0)
            except OSError:
                pass
        print("Program stopped")

if __name__ == "__main__":
    main()

