import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or is not running on a Raspberry Pi.")
    sys.exit(1)

LED_PIN = 17
led_state = False
_running = True


def cleanup_gpio():
    """Drive the LED low and release the GPIO resource on every exit path."""
    global led_state
    try:
        if led_state:
            GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    led_state = False


def handle_signal(signum, frame):
    """Handle SIGTERM/SIGINT so cleanup runs on service shutdown."""
    global _running
    _running = False


def main():
    global led_state, _running

    signal.signal(signal.SIGTERM, handle_signal)
    signal.signal(signal.SIGINT, handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)

    try:
        while _running:
            try:
                user_input = input("Enter 'on', 'off', or 'exit': ").strip().lower()
            except EOFError:
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
            elif user_input == "exit":
                break
            else:
                print("Invalid input")

            print(f"LED state: {led_state}")

            if _running:
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()
        print("Exiting program.")


if __name__ == "__main__":
    main()

