import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

I2C_BUS = 1
MCP23017_ADDR = 0x20

# Register addresses (BANK=0, default after power-on)
IODIRA = 0x00
IODIRB = 0x01
GPPUA = 0x0C
GPPUB = 0x0D
GPIOA = 0x12
GPIOB = 0x13

LED_BIT = 0
SWITCH_BIT = 7
DEBOUNCE_MS = 20

running = True
bus = None


def _write_reg(reg, value):
    bus.write_byte_data(MCP23017_ADDR, reg, value & 0xFF)


def _read_reg(reg):
    return bus.read_byte_data(MCP23017_ADDR, reg)


def _toggle_led(state):
    _write_reg(GPIOA, (1 if state else 0) << LED_BIT)


def _read_switch():
    return (1 if (_read_reg(GPIOB) >> SWITCH_BIT) & 1 else 0)


def _safe_shutdown():
    global bus
    if bus is not None:
        try:
            _write_reg(GPIOA, 0x00)
            _write_reg(GPIOB, 0x00)
        except OSError:
            pass
        try:
            bus.close()
        except OSError:
            pass
        bus = None


def _signal_handler(signum, frame):
    global running
    running = False


def main():
    global bus
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
