import sys
import time
import signal

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    # RPi.GPIO is not available in non-Pi environments (e.g., emulated CI)
    GPIO = None

# Pin definitions (BCM numbering)
BUTTON_PIN = 5
LED_PIN = 17

# Timing constants
POLL_INTERVAL = 0.1  # seconds

# Global flag for clean shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    global _running
    _running = False


def setup_gpio():
    """Initialize GPIO mode and pins. Returns True on success, False on failure."""
    if GPIO is None:
        print("Error: RPi.GPIO library is not available.", file=sys.stderr)
        return False

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        return True
    except Exception as e:
        print(f"Error setting up GPIO: {e}", file=sys.stderr)
        return False


def cleanup_gpio():
    """Safely turn off the LED and release GPIO resources."""
    if GPIO is None:
        return
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Warning during GPIO cleanup: {e}", file=sys.stderr)


def main():
    """Main loop: poll button, toggle LED, print status."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    if not setup_gpio():
        sys.exit(1)

    try:
        while _running:
            try:
                button_state = GPIO.input(BUTTON_PIN)
            except Exception as e:
                print(f"Error reading button state: {e}", file=sys.stderr)
                time.sleep(POLL_INTERVAL)
                continue

            if button_state == GPIO.HIGH:
                GPIO.output(LED_PIN, GPIO.HIGH)
                print("Button pressed! LED is ON")
            else:
                GPIO.output(LED_PIN, GPIO.LOW)
                print("Button released! LED is OFF")

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()
        print("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

