import signal
import sys
import time
import requests
from requests.auth import HTTPBasicAuth

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or is not running on a Raspberry Pi.")
    sys.exit(1)

# --- Configuration -----------------------------------------------------------
SENSOR_PIN = 4            # BCM GPIO 4 (physical pin 7)
SERVER_URL = "http://localhost:5000/sensor"
USERNAME = "your_username"
PASSWORD = "your_password"
POLL_INTERVAL = 5         # seconds between sensor reads

# --- Globals for cleanup -----------------------------------------------------
_running = True
_gpio_initialized = False


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _cleanup():
    """Release GPIO resources if they were initialized."""
    global _gpio_initialized
    if _gpio_initialized:
        try:
            GPIO.cleanup()
        except Exception:
            pass
        _gpio_initialized = False


def _init_gpio():
    """Configure GPIO pin 4 as a floating input with no pull resistor."""
    global _gpio_initialized
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_OFF)
        _gpio_initialized = True
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        _gpio_initialized = False
        raise


def read_sensor():
    """Return the digital value of the sensor, or None on error."""
    if not _gpio_initialized:
        return None
    try:
        return GPIO.input(SENSOR_PIN)
    except Exception as e:
        print(f"Error reading sensor: {e}")
        return None


def send_data(value):
    """POST a JSON payload to the server; swallow request errors but log them."""
    payload = {"sensor": "digital_input", "value": value}
    try:
        response = requests.post(
            SERVER_URL,
            json=payload,
            auth=HTTPBasicAuth(USERNAME, PASSWORD),
            timeout=10,
        )
        response.raise_for_status()
        print(f"Data sent successfully (HTTP {response.status_code}).")
    except requests.exceptions.RequestException as e:
        print(f"Error sending data: {e}")


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _init_gpio()
    except Exception:
        print("Failed to initialize GPIO. Exiting.")
        sys.exit(1)

    print("Starting sensor monitoring. Press Ctrl+C to stop.")

    try:
        while _running:
            value = read_sensor()
            if value is not None:
                print(f"Sensor value: {value}")
                send_data(value)
            else:
                print("Sensor read failed; skipping submission.")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < POLL_INTERVAL:
                time.sleep(0.1)
                slept += 0.1
    finally:
        _cleanup()
        print("GPIO cleanup completed. Exiting.")


if __name__ == "__main__":
    main()

