logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PIN = 17
HIGH_DURATION = 0.2
LOW_DURATION = 0.2

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def setup_gpio(pin):
    logging.info("Setting up GPIO %d...", pin)
    try:
        # In a real driver this would configure the pin as output and set it LOW.
        # Here we just log the action.
        logging.info("GPIO %d setup complete.", pin)
    except Exception as exc:
        logging.error("GPIO setup failed: %s", exc)
        raise


def generate_pulse(pin, high_duration, low_duration):
    logging.info("Generating pulse on GPIO %d (HIGH for %.2f s, LOW for %.2f s).", pin, high_duration, low_duration)
    try:
        # In a real driver this would write HIGH.
        time.sleep(high_duration)
        # In a real driver this would write LOW.
        time.sleep(low_duration)
    except Exception as exc:
        logging.error("Pulse generation failed: %s", exc)
        raise


def cleanup_gpio(pin):
    logging.info("Cleaning up GPIO %d...", pin)
    try:
        # In a real driver this would set the pin to a safe LOW state.
        logging.info("GPIO %d cleanup complete.", pin)
    except Exception as exc:
        logging.error("GPIO cleanup failed: %s", exc)


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        setup_gpio(PIN)
    except Exception:
        logging.error("GPIO setup failed. Exiting.")
        sys.exit(1)

    try:
        while _running:
            generate_pulse(PIN, HIGH_DURATION, LOW_DURATION)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received. Shutting down...")
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        cleanup_gpio(PIN)
        logging.info("Program terminated.")


if __name__ == "__main__":
