import signal
import sys
import threading
import time

from src.api import DOG

MANUAL = {
    "help": "help [command]\n  display\n  help\n  send\n  start\n  stop\n  write\n  exit",
    "start": "start <filename>\n  Starts logging data to the specified file.",
    "stop": "stop\n  Stops logging data.",
    "display": "display\n  Displays the contents of the log file.",
    "send": "send <data>\n  Sends the specified data via DOG.send().",
    "write": "write <data>\n  Appends the specified data to the log file with a newline.",
    "exit": "exit\n  Exits the program.",
}


class CommandLineInterface:
    def __init__(self, dog: DOG):
        self.dog = dog
        self.running = False
        self.log_file = None
        self.receive_thread = None
        self._lock = threading.Lock()

    def _signal_handler(self, signum, frame):
        print(f"\nSignal {signum} received. Shutting down...")
        self.running = False
        self._cleanup()
        sys.exit(0)

    def _cleanup(self):
        if self.log_file:
            try:
                self.log_file.close()
            except Exception:
                pass
            self.log_file = None
        if self.receive_thread and self.receive_thread.is_alive():
            self.receive_thread.join(timeout=2.0)
