import signal
import sys
import time
import requests
from gpiozero import InputDevice
from gpiozero.exc import GPIOZeroError

VOLTAGE_PIN = 17
ALERT_ENDPOINT = 'http://example.com/alert'
POLL_INTERVAL = 1.0
POST_TIMEOUT = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def send_alert():
    try:
        resp = requests.post(
            ALERT_ENDPOINT,
            json={'alert': 'Power failure detected'},
            timeout=POST_TIMEOUT,
        )
        resp.raise_for_status()
    except requests.exceptions.RequestException as exc:
        print(f'Error sending alert: {exc}', file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = InputDevice(VOLTAGE_PIN, pull_up=True)
    except GPIOZeroError as exc:
        print(f'Failed to initialize GPIO {VOLTAGE_PIN}: {exc}', file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                if sensor.is_active:
                    print('Power present')
                else:
                    print('Power failure detected')
                    send_alert()
            except GPIOZeroError as exc:
                print(f'GPIO read error: {exc}', file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    finally:
        sensor.close()
        print('GPIO cleanup completed.')

if __name__ == '__main__':
    main()

