import asyncio
import json
import logging
import os
import signal
import sys
import time
from typing import List, Optional, Tuple

import speech_recognition as sr
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Project-specific imports
from config import Config
from sentiment_analysis import SentimentAnalyzer
from voice_activity_detection import VoiceActivityDetector
from keyword_spotting import KeywordSpotter

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global shutdown flag
_shutdown_event = asyncio.Event()


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    logging.info(f"Received signal {signum}, initiating shutdown...")
    _shutdown_event.set()


def load_config(config_path: str) -> Config:
    """Loads configuration from a JSON file."""
    try:
        with open(config_path, 'r') as f:
            config_data = json.load(f)
        return Config(**config_data)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_path}")
        raise
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON format in configuration file: {config_path}: {e}")
        raise
    except Exception as e:
        logging.error(f"Error loading configuration: {e}")
        raise


def initialize_led(config: Config) -> Optional[LED]:
    """Initializes the LED GPIO pin."""
    try:
        return LED(config.led_pin)
    except GPIOZeroError as e:
        logging.error(f"Failed to initialize LED on pin {config.led_pin}: {e}")
        return None
    except Exception as e:
        logging.error(f"Unexpected error initializing LED: {e}")
        return None


def check_for_updates(config: Config) -> bool:
    """Checks for updates to the configuration file."""
    try:
        if not os.path.exists(config.config_file):
            logging.warning(f"Configuration file not found: {config.config_file}")
            return False
        with open(config.config_file, 'r') as f:
            latest_config_data = json.load(f)
        if latest_config_data != config.config_data:
            logging.info("Configuration update detected. Fetching latest configuration...")
            # Placeholder for actual update logic
            return True
        return False
    except Exception as e:
        logging.error(f"Error checking for configuration updates: {e}")
        return False


def update_config(config: Config) -> None:
    """Updates the configuration with the latest values."""
    try:
        with open(config.config_file, 'r') as f:
            latest_config_data = json.load(f)
        config.update(latest_config_data)
        logging.info("Configuration updated successfully.")
    except Exception as e:
        logging.error(f"Error updating configuration: {e}")


def run_sentiment_analysis(
    audio_data: bytes,
    sentiment_analyzer: SentimentAnalyzer,
    config: Config
) -> Tuple[Optional[str], Optional[float]]:
    """Runs sentiment analysis on the given audio data."""
    try:
        sentiment_score = sentiment_analyzer.analyze(audio_data)
        if sentiment_score is not None:
            logging.info(f"Sentiment score: {sentiment_score}")
            if sentiment_score < config.sentiment_threshold:
                logging.warning("Sentiment score below threshold. Triggering alert.")
                return "Alert", sentiment_score
            return None, sentiment_score
        return None, None
    except Exception as e:
        logging.error(f"Error during sentiment analysis: {e}")
        return None, None


def run_keyword_spotting(
    audio_data: bytes,
    keyword_spotter: KeywordSpotter,
    config: Config
) -> Optional[str]:
    """Runs keyword spotting on the given audio data."""
    try:
        keywords = keyword_spotter.identify(audio_data)
        if keywords:
            logging.info(f"Keyword detected: {keywords}")
            return keywords[0]
        return None
    except Exception as e:
        logging.error(f"Error during keyword spotting: {e}")
        return None


def run_voice_activity_detection(
    audio_data: bytes,
    vad: VoiceActivityDetector,
    config: Config
) -> bool:
    """Runs voice activity detection on the given audio data."""
    try:
        is_speaking = vad.is_speaking(audio_data)
        if is_speaking:
            logging.info("Voice activity detected.")
            return True
        return False
    except Exception as e:
        logging.error(f"Error during voice activity detection: {e}")
        return False


async def heartbeat_task(config: Config, led: Optional[LED]) -> None:
    """Periodically sends heartbeat signals."""
    while not _shutdown_event.is_set():
        try:
            if led:
                led.on()
            await asyncio.sleep(config.heartbeat_interval)
            if led:
                led.off()
            await asyncio.sleep(config.heartbeat_interval)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logging.error(f"Error in heartbeat task: {e}")
            await asyncio.sleep(1)


async def check_for_updates_task(config: Config) -> None:
    """Periodically checks for configuration updates."""
    while not _shutdown_event.is_set():
        try:
            if check_for_updates(config):
                update_config(config)
            await asyncio.sleep(config.update_check_interval)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logging.error(f"Error in update check task: {e}")
            await asyncio.sleep(1)


async def log_resource_usage_task(config: Config) -> None:
    """Periodically logs resource usage."""
    while not _shutdown_event.is_set():
        try:
            logging.info("Logging resource usage...")
            await asyncio.sleep(config.resource_logging_interval)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logging.error(f"Error in resource logging task: {e}")
            await asyncio.sleep(1)


async def main_loop(
    vad: VoiceActivityDetector,
    keyword_spotter: KeywordSpotter,
    sentiment_analyzer: SentimentAnalyzer,
    config: Config,
    led: Optional[LED]
) -> None:
    """Main loop for continuous monitoring."""
    r = sr.Recognizer()
    try:
        while not _shutdown_event.is_set():
            try:
                with sr.Microphone(sample_rate=16000) as source:
                    r.adjust_for_ambient_noise(source)
                    audio_data = r.listen(source, timeout=5)
            except sr.WaitTimeoutError:
                logging.warning("Listening timed out. No speech detected.")
                await asyncio.sleep(1)
                continue
            except sr.AudioSourceError as e:
                logging.error(f"Audio source error: {e}")
                await asyncio.sleep(1)
                continue
            except Exception as e:
                logging.error(f"Error during audio capture: {e}")
                await asyncio.sleep(1)
                continue

            if run_voice_activity_detection(audio_data, vad, config):
                try:
                    text = r.recognize_google(audio_data)
                    logging.info(f"Recognized speech: {text}")
                    keyword = run_keyword_spotting(text, keyword_spotter, config)
                    if keyword:
                        sentiment_result, sentiment_score = run_sentiment_analysis(
                            audio_data, sentiment_analyzer, config
                        )
                        if sentiment_result:
                            logging.info(f"Sentiment analysis result: {sentiment_result}")
                            if led:
                                led.on()
                            if config.send_cloud_alert:
                                logging.info("Sending cloud alert...")
                            if sentiment_score is not None:
                                logging.info(f"Sentiment score: {sentiment_score}")
                except sr.UnknownValueError:
                    logging.warning("Google Web Speech API could not understand audio")
                except sr.RequestError as e:
                    logging.error(f"Could not request results from Google Web Speech API; {e}")
                except Exception as e:
                    logging.error(f"Error during speech recognition: {e}")
            await asyncio.sleep(1)
    except asyncio.CancelledError:
        raise
    except Exception as e:
        logging.error(f"Error in main loop: {e}")


async def main() -> None:
    """Main function to initialize and run the application."""
    config = None
    try:
        config = load_config("config.json")
    except Exception:
        logging.error("Failed to load configuration. Exiting.")
        sys.exit(1)

    led = initialize_led(config)
    vad = VoiceActivityDetector(config.sensitivity)
    keyword_spotter = KeywordSpotter(config.keyword_spots)
    sentiment_analyzer = SentimentAnalyzer(config.sentiment_model_path)

    heartbeat_task_instance = asyncio.create_task(heartbeat_task(config, led))
    update_task_instance = asyncio.create_task(check_for_updates_task(config))
    resource_task_instance = asyncio.create_task(log_resource_usage_task(config))

    try:
        await main_loop(vad, keyword_spotter, sentiment_analyzer, config, led)
    except asyncio.CancelledError:
        logging.info("Main loop cancelled.")
    finally:
        logging.info("Shutting down...")
        heartbeat_task_instance.cancel()
        update_task_instance.cancel()
        resource_task_instance.cancel()
        try:
            await asyncio.gather(heartbeat_task_instance, update_task_instance, resource_task_instance, return_exceptions=True)
        except asyncio.CancelledError:
            pass
        if led:
            led.close()
        logging.info("Shutdown complete.")


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"Unhandled exception: {e}")
    finally:
        logging.info("Exiting program.")

