import signal
import sys
import time

import board
import busio
import adafruit_tsl2561
import digitalio
import pulseio

# --- Configuration -----------------------------------------------------------
I2C_BUS_NUMBER = 1          # /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
TSL2561_ADDRESS = 0x29      # Default I2C address (ADDR pin tied to GND)
LED_GPIO_PIN = 18           # BCM 18 (physical pin 12)
PWM_FREQUENCY = 1000        # 1 kHz
SAMPLE_INTERVAL = 1.0       # seconds between readings
INTEGRATION_TIME = 0.4      # 402 ms (TSL2561.INTEGRATIONTIME_402MS)
GAIN = adafruit_tsl2561.GAIN_MED

# --- Globals for cleanup -----------------------------------------------------
_i2c = None
_sensor = None
_pwm = None
_running = True


def _cleanup():
    """Stop PWM, deinitialize the sensor, and close the I2C bus."""
    global _pwm, _sensor, _i2c
    if _pwm is not None:
        try:
            _pwm.deinit()
        except Exception:
            pass
        _pwm = None
    if _sensor is not None:
        try:
            _sensor.deinit()
        except Exception:
            pass
        _sensor = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize I2C bus {I2C_BUS_NUMBER}: {exc}")
        return None


def _init_sensor(i2c_bus):
    """Initialize the TSL2561 sensor; return the sensor object or None."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_ADDRESS)
        sensor.integration_time = INTEGRATION_TIME
        sensor.gain = GAIN
        return sensor
    except ValueError as exc:
        print(f"[ERROR] TSL2561 not detected at 0x{TSL2561_ADDRESS:02X}: {exc}")
        return None
    except Exception as exc:
        print(f"[ERROR] Failed to initialize TSL2561: {exc}")
        return None


def _init_led():
    """Initialize the PWM output on LED_GPIO_PIN; return the PWM object or None."""
    try:
        led = digitalio.DigitalInOut(getattr(board, f"D{LED_GPIO_PIN}"))
        led.direction = digitalio.Direction.OUTPUT
        pwm = pulseio.PWMOut(led, frequency=PWM_FREQUENCY, duty_cycle=0)
        return pwm
    except Exception as exc:
        print(f"[ERROR] Failed to initialize PWM on GPIO{LED_GPIO_PIN}: {exc}")
        return None


def _read_lux(sensor):
    """Read lux from the sensor; return lux or None on error."""
    try:
        return sensor.lux
    except OSError as exc:
        print(f"[ERROR] I2C read error from TSL2561: {exc}")
        return None
    except Exception as exc:
        print(f"[ERROR] Unexpected error reading lux: {exc}")
        return None


def _map_lux_to_brightness(lux):
    """Map lux (0–10000) to a 0–65535 duty cycle (10-bit PWM)."""
    if lux is None:
        return 0
    return int((lux / 10000.0) * 65535)


def main():
    global _i2c, _sensor, _pwm

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _i2c = _init_i2c()
    if _i2c is None:
        _cleanup()
        sys.exit(1)

    _sensor = _init_sensor(_i2c)
    if _sensor is None:
        _cleanup()
        sys.exit(1)

    _pwm = _init_led()
    if _pwm is None:
        _cleanup()
        sys.exit(1)

    print("TSL2561 light-to-LED brightness controller running. Press Ctrl+C to exit.")

    try:
        while _running:
            lux = _read_lux(_sensor)
            if lux is not None:
                brightness = _map_lux_to_brightness(lux)
                _pwm.duty_cycle = brightness
                print(f"Lux: {lux:.2f}  |  LED Brightness: {brightness / 65535:.2f}")
            time.sleep(SAMPLE_INTERVAL)
    except Exception as exc:
        print(f"[ERROR] Fatal error in main loop: {exc}")
    finally:
        _cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

