import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or to be run on a Raspberry Pi.")
    sys.exit(1)

# BCM pin numbers for the two IR sensors
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Number of samples to collect
NUM_SAMPLES = 10

# Delay between samples (seconds)
SAMPLE_DELAY = 0.5

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def setup_gpio():
    """Configure the GPIO pins for the IR sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        GPIO.cleanup()
        sys.exit(1)


def read_sensor(pin):
    """Read a single IR sensor. Returns 0 for black line, 1 for white surface."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}")
        return None


def analyze_direction(left_value, right_value):
    """Determine steering direction from the two sensor readings."""
    if left_value is None or right_value is None:
        return "ERROR"
    if left_value == 0 and right_value == 0:
        return "FORWARD"
    if left_value == 1 and right_value == 0:
        return "TURN LEFT"
    if left_value == 0 and right_value == 1:
        return "TURN RIGHT"
    return "SEARCH"


def main():
    """Main loop: collect samples and print steering status."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    setup_gpio()
    print("Starting IR line follower...")
    print(f"Collecting {NUM_SAMPLES} samples, {SAMPLE_DELAY}s apart.\n")

    try:
        for i in range(NUM_SAMPLES):
            if not _running:
                break

            left = read_sensor(LEFT_SENSOR_PIN)
            right = read_sensor(RIGHT_SENSOR_PIN)

            if left is None or right is None:
                print(f"Sample {i + 1}: ERROR (sensor read failed)")
            else:
                print(f"Sample {i + 1}: Left={left}, Right={right} -> {analyze_direction(left, right)}")

            time.sleep(SAMPLE_DELAY)

    except Exception as e:
        print(f"Unexpected error during sampling: {e}")

    finally:
        GPIO.cleanup()
        print("\nGPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

