import signal
import sys
import time
import logging

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or to be run on a Raspberry Pi.")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21
START_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [0, 0, 0, 0, 0, 0, 0, 0]
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False
    logging.info(f"Signal {signum} received, shutting down...")

def initialize_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in [DATA_OUT_PIN, TIMER_OUT_PIN, DATA_IN_PIN, TIMER_IN_PIN]:
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

def send_data(data):
    global _running
    initialize_gpio()
    try:
        for bit in START_SIGNAL:
            if not _running:
                logging.info("Transmission interrupted by signal.")
                return
            GPIO.output(DATA_OUT_PIN, bit)
            GPIO.output(TIMER_OUT_PIN, 1)
            time.sleep(TRANSMIT_DELAY)
            GPIO.output(TIMER_OUT_PIN, 0)
            time.sleep(TRANSMIT_DELAY)
        for bit in data:
            if not _running:
                logging.info("Transmission interrupted by signal.")
                return
            GPIO.output(DATA_OUT_PIN, bit)
            GPIO.output(TIMER_OUT_PIN, 1)
            time.sleep(TRANSMIT_DELAY)
            GPIO.output(TIMER_OUT_PIN, 0)
            time.sleep(TRANSMIT_DELAY)
        for bit in END_SIGNAL:
            if not _running:
                logging.info("Transmission interrupted by signal.")
                return
            GPIO.output(DATA_OUT_PIN, bit)
            GPIO.output(TIMER_OUT_PIN, 1)
            time.sleep(TRANSMIT_DELAY)
            GPIO.output(TIMER_OUT_PIN, 0)
            time.sleep(TRANSMIT_DELAY)
        logging.info("Data sent successfully.")
    except Exception as e:
        logging.error(f"Error during transmission: {e}")
    finally:
        GPIO.cleanup()

def receive_data():
    global _running
    initialize_gpio()
    try:
        start_time = time.time()
        while _running and time.time() - start_time < RECEPTION_TIMEOUT:
            if all(GPIO.input(DATA_IN_PIN) == bit for bit in START_SIGNAL):
                break
            if not _running:
                return None
        if not _running:
            return None
        received_data = []
        while _running and time.time() - start_time < RECEPTION_TIMEOUT:
            byte = []
            for _ in range(8):
                if not _running:
                    return None
                if GPIO.input(DATA_IN_PIN) == 1:
                    byte.append(1)
                else:
                    byte.append(0)
                if not _running:
                    return None
                GPIO.output(TIMER_IN_PIN, 1)
                time.sleep(TRANSMIT_DELAY)
                GPIO.output(TIMER_IN_PIN, 0)
                time.sleep(TRANSMIT_DELAY)
            received_data.append(byte)
        if not _running:
            return None
        if all(GPIO.input(DATA_IN_PIN) == bit for bit in END_SIGNAL):
            return received_data
        return None
    except Exception as e:
        logging.error(f"Error during reception: {e}")
        return None
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        send_data([1, 0, 1, 0, 1, 0, 1, 0])
    except Exception as e:
        logging.error(f"Failed to send data: {e}")
    try:
        received = receive_data()
        if received is not None:
            print(f"Received data: {received}")
        else:
            print("No data received within timeout.")
    except Exception as e:
        logging.error(f"Failed to receive data: {e}")

