#!/usr/bin/env python3
"""
Sentiment Analysis and LED Control for Raspberry Pi

Monitors /home/pi/feedback/customer_feedback.txt for new lines every 5 seconds,
performs sentiment analysis on each line, logs results to two destinations,
and drives green (GPIO 17) and red (GPIO 18) LEDs based on polarity.

Hardware:
  - Green LED  : GPIO 17 (BCM), anode to LED, cathode to 330Ω resistor, to GND
  - Red LED    : GPIO 18 (BCM), anode to LED, cathode to 330Ω resistor, to GND

Dependencies:
  pip install textblob
"""

import json
import os
import signal
import sys
import time
from datetime import datetime

from textblob import TextBlob

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
FEEDBACK_FILE = "/home/pi/feedback/customer_feedback.txt"
LOG_FILE = "/home/pi/logs/sentiment_log.txt"
DATA_FILE = "/home/pi/data/sentiment_data.json"
POLL_INTERVAL = 5          # seconds between checks
GREEN_LED_PIN = 17         # BCM
RED_LED_PIN = 18           # BCM
POLARITY_THRESHOLD = 0.2   # green LED on above this, red below this

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_leds = {"green": None, "red": None}


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _setup_gpio():
    """Initialize GPIO pins for LEDs. Returns dict of pin objects or None."""
    try:
        import RPi.GPIO as GPIO
    except ImportError:
        print("RPi.GPIO not available. Running in simulation mode.", file=sys.stderr)
        return {"green": None, "red": None}

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for name, pin in _leds.items():
        try:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as exc:
            print(f"Warning: could not initialize GPIO {pin} ({name}): {exc}", file=sys.stderr)
            return {"green": None, "red": None}
    return {"green": GPIO.PWM(pin, 1) for name, pin in _leds.items()}


def _cleanup_gpio(leds):
    """Stop PWM and clean up GPIO resources."""
    try:
        for name, led in leds.items():
            if led is not None:
                try:
                    led.stop()
                except Exception:
                    pass
    except Exception as exc:
        print(f"Warning: GPIO cleanup error: {exc}", file=sys.stderr)
    try:
        import RPi.GPIO as GPIO
        GPIO.cleanup()
    except Exception:
        pass


def _log_data(log_file, data):
    """Append JSON-serializable data to the log file."""
    try:
        with open(log_file, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(data) + "\n")
    except OSError as exc:
        print(f"Error writing to log file: {exc}", file=sys.stderr)


def _log_data_json(data_file, data):
    """Append a JSON object to the data file, maintaining a valid JSON array."""
    try:
        existing = []
        if os.path.isfile(data_file):
            with open(data_file, "r", encoding="utf-8") as fh:
                try:
                    content = fh.read().strip()
                    if content:
                        existing = json.loads(content)
                except json.JSONDecodeError:
                    existing = []
        existing.append(data)
        with open(data_file, "w", encoding="utf-8") as fh:
            fh.write(json.dumps(existing, indent=2) + "\n")
    except OSError as exc:
        print(f"Error writing to data file: {exc}", file=sys.stderr)


def _set_leds(leds, polarity):
    """Set LED states based on polarity: green > 0.2, red < -0.2, off in between."""
    try:
        if polarity > POLARITY_THRESHOLD:
            leds["green"].start(50)
            leds["red"].stop()
        elif polarity < -POLARITY_THRESHOLD:
            leds["green"].stop()
            leds["red"].start(50)
        else:
            leds["green"].stop()
            leds["red"].stop()
    except Exception as exc:
        print(f"Error setting LEDs: {exc}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    leds = _setup_gpio()
    _leds.update(leds)

    try:
        while _running:
            try:
                if not os.path.isfile(FEEDBACK_FILE):
                    time.sleep(POLL_INTERVAL)
                    continue

                with open(FEEDBACK_FILE, "r", encoding="utf-8") as fh:
                    lines = fh.readlines()

                if not lines:
                    time.sleep(POLL_INTERVAL)
                    continue

                new_lines = [line.strip() for line in lines if line.strip()]
                if not new_lines:
                    time.sleep(POLL_INTERVAL)
                    continue

                feedback = new_lines[-1]
                blob = TextBlob(feedback)
                polarity = blob.sentiment.polarity

                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                log_data = {
                    "timestamp": timestamp,
                    "feedback": feedback,
                    "polarity": round(polarity, 3),
                }
                _log_data(LOG_FILE, log_data)
                _log_data_json(DATA_FILE, log_data)

                _set_leds(leds, polarity)

            except FileNotFoundError:
                print(f"Error: {FEEDBACK_FILE} not found.", file=sys.stderr)
            except IOError as exc:
                print(f"IOError reading {FEEDBACK_FILE}: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Unexpected error: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

    finally:
        _cleanup_gpio(leds)
        print("Program terminated.")


if __name__ == "__main__":
    main()

