import time
import logging
import signal
import zmq
from typing import Optional, Callable, Any

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class PIDHandler:
    """
    Manages a PID controller and its associated error output (PWM or digital)
    using a ZeroMQ watchdog to enforce a timeout.
    """

    def __init__(
        self,
        err_pin: int,
        watchdog_timeout: float = 20.0,
        pwm: bool = False,
        pwm_frequency: int = 1000,
        initial_duty_cycle: float = 0.0,
    ) -> None:
        self.err_pin = err_pin
        self.watchdog_timeout = watchdog_timeout
        self.pwm = pwm
        self.pwm_frequency = pwm_frequency
        self.initial_duty_cycle = initial_duty_cycle
        self.zctx: Optional[zmq.Context] = None
        self.zsock: Optional[zmq.Socket] = None
        self.last_msg: float = time.time()
        self.global_err_state: bool = False
        self._shutdown: bool = False
        self._gpio_ready: bool = False

        if GPIO is not None:
            try:
                GPIO.setmode(GPIO.BOARD)
                GPIO.setwarnings(False)
                self._gpio_ready = True
                logging.info("GPIO initialized (BOARD mode).")
            except Exception as e:
                logging.error(f"GPIO initialization failed: {e}")
                self._gpio_ready = False
        else:
            logging.warning("RPi.GPIO not available; running in simulation mode.")

        if self.pwm and self._gpio_ready:
            try:
                GPIO.setup(self.err_pin, GPIO.OUT)
                self.pwm_obj = GPIO.PWM(self.err_pin, self.pwm_frequency)
                self.pwm_obj.start(self.initial_duty_cycle)
                logging.info(
                    f"PWM initialized on pin {self.err_pin} "
                    f"at {self.pwm_frequency} Hz, duty cycle {self.initial_duty_cycle}."
                )
            except Exception as e:
                logging.error(f"PWM initialization failed: {e}")
                self.pwm_obj = None
        else:
            try:
                GPIO.setup(self.err_pin, GPIO.OUT)
                logging.info(f"Digital output initialized on pin {self.err_pin}.")
            except Exception as e:
                logging.error(f"Digital output initialization failed: {e}")
                self.pwm_obj = None

    def set_error_output(self, state: bool) -> None:
        """Sets the error output state (PWM or digital)."""
        if not self._gpio_ready:
            logging.warning("GPIO not ready; cannot set error output.")
            return
        try:
            if self.pwm_obj is not None:
                self.pwm_obj.ChangeDutyCycle(100 if state else 0)
            else:
                GPIO.output(self.err_pin, GPIO.HIGH if state else GPIO.LOW)
            self.global_err_state = state
            logging.debug(f"Error output set to {state}.")
        except Exception as e:
            logging.error(f"Error setting error output: {e}")

    def update_error_output(self, state: bool) -> None:
        """Updates the error output state and logs the change."""
        self.set_error_output(state)
        logging.info(f"Error output updated to {state}.")

    def handle_message(self, sub_sock: zmq.Socket) -> None:
        """Handles incoming messages and resets the watchdog."""
        if self._shutdown:
            return
        try:
            msg = sub_sock.recv_string(flags=zmq.NOBLOCK)
            self.last_msg = time.time()
            logging.debug(f"Received message: {msg}")
        except zmq.Again:
            pass
        except zmq.ZMQError as e:
            if e.errno != zmq.ETERM:
                logging.error(f"Error receiving message: {e}")
        except Exception as e:
            logging.error(f"Unexpected error handling message: {e}")

    def cleanup(self) -> None:
        """Closes the GPIO devices and releases resources."""
        self._shutdown = True
        logging.info("Cleaning up resources...")
        if self.zsock is not None:
            try:
                self.zsock.close(linger=0)
            except Exception as e:
                logging.error(f"Error closing ZMQ socket: {e}")
            self.zsock = None
        if self.zctx is not None:
            try:
                self.zctx.term()
            except Exception as e:
                logging.error(f"Error terminating ZMQ context: {e}")
            self.zctx = None
        if self.pwm_obj is not None:
            try:
                self.pwm_obj.stop()
            except Exception as e:
                logging.error(f"Error stopping PWM: {e}")
            self.pwm_obj = None
        if self._gpio_ready:
            try:
                GPIO.cleanup()
                logging.info("GPIO cleaned up.")
            except Exception as e:
                logging.error(f"Error during GPIO cleanup: {e}")
        self._gpio_ready = False

    def _signal_handler(self, signum: int, frame: Any) -> None:
        """Handles SIGINT and SIGTERM for graceful shutdown."""
        logging.info(f"Signal {signum} received. Shutting down...")
        self.cleanup()
        raise SystemExit(0)


def main() -> None:
    """Main entry point for the PIDHandler."""
    handler = PIDHandler(
        err_pin=15,  # Physical pin 10 (BCM GPIO 15)
        watchdog_timeout=20.0,
        pwm=True,
        pwm_frequency=1000,
        initial_duty_cycle=0.0,
    )

    signal.signal(signal.SIGINT, handler._signal_handler)
    signal.signal(signal.SIGTERM, handler._signal_handler)

    try:
        handler.update_error_output(True)
        time.sleep(5)
        handler.update_error_output(False)
    finally:
        handler.cleanup()


if __name__ == "__main__":
    main()

