        """Closes the GPIO devices and releases resources."""
        self._shutdown = True
        logging.info("Cleaning up resources...")
        if self.zsock is not None:
            try:
                self.zsock.close(linger=0)
            except Exception as e:
                logging.error(f"Error closing ZMQ socket: {e}")
            self.zsock = None
        if self.zctx is not None:
            try:
                self.zctx.term()
            except Exception as e:
                logging.error(f"Error terminating ZMQ context: {e}")
            self.zctx = None
        if self.pwm_obj is not None:
            try:
                self.pwm_obj.stop()
            except Exception as e:
                logging.error(f"Error stopping PWM: {e}")
            self.pwm_obj = None
        if self._gpio_ready:
            try:
                GPIO.cleanup()
                logging.info("GPIO cleaned up.")
            except Exception as e:
                logging.error(f"Error during GPIO cleanup: {e}")
        self._gpio_ready = False

    def _signal_handler(self, signum: int, frame: Any) -> None:
        """Handles SIGINT and SIGTERM for graceful shutdown."""
        logging.info(f"Signal {signum} received. Shutting down...")
        self.cleanup()
        raise SystemExit(0)


def main() -> None:
    """Main entry point for the PIDHandler."""
    handler = PIDHandler(
        err_pin=15,  # Physical pin 10 (BCM GPIO 15)
        watchdog_timeout=20.0,
        pwm=True,
        pwm_frequency=1000,
        initial_duty_cycle=0.0,
    )

    signal.signal(signal.SIGINT, handler._signal_handler)
    signal.signal(signal.SIGTERM, handler._signal_handler)

    try:
        handler.update_error_output(True)
        time.sleep(5)
        handler.update_error_output(False)
    finally:
        handler.cleanup()


if __name__ == "__main__":
    main()

