# Access control system for Raspberry Pi 5 using fingerprint sensor over I2C.

import time
import board
import busio
import adafruit_fingerprint

# Constants
I2C_ADDRESS = 0x0A  # Default I2C address for Adafruit fingerprint sensor
RETRY_DELAY = 1.0   # Delay between authentication attempts (seconds)


def initialize_i2c():
    """Initializes the I2C bus on the Raspberry Pi 5."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_fingerprint_sensor(i2c_bus):
    """Initializes the fingerprint sensor."""
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus, address=I2C_ADDRESS)
        return sensor
    except Exception as e:
        print(f"Error initializing fingerprint sensor: {e}")
        return None


def get_fingerprint_id(sensor):
    """Gets the fingerprint ID from the user."""
    while True:
        try:
            print("Waiting for fingerprint...")
            if sensor.get_image() == adafruit_fingerprint.NOFINGER:
                time.sleep(RETRY_DELAY)
                continue
            print("Image taken. Converting to template...")
            if sensor.image_2_tz(1) != adafruit_fingerprint.OK:
                print("Template conversion failed.")
                time.sleep(RETRY_DELAY)
                continue
            print("Template created. Searching database...")
            if sensor.finger_search() != adafruit_fingerprint.OK:
                print("No match found.")
                return -1
            return sensor.finger_id
        except ValueError as e:
            print(f"I2C bus error: {e}. Retrying...")
            time.sleep(RETRY_DELAY)
        except RuntimeError as e:
            print(f"Sensor error: {e}. Retrying...")
            time.sleep(RETRY_DELAY)
        except Exception as e:
            print(f"Unexpected error: {e}. Retrying...")
            time.sleep(RETRY_DELAY)


def main():
    """Main function to run the fingerprint authentication system."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    fingerprint_sensor = initialize_fingerprint_sensor(i2c_bus)
    if fingerprint_sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            print("Place your finger on the sensor...")
            user_id = get_fingerprint_id(fingerprint_sensor)

            if user_id == -1:
                print("Access Denied")
            else:
                print(f"Access Granted. User ID: {user_id}")
    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        i2c_bus.deinit()
        print("I2C bus deinitialized.")


if __name__ == "__main__":
    main()

