import socket
import logging
import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

LISTEN_PORT = 9100
LISTEN_ADDRESS = "0.0.0.0"
BACKLIGHT_PIN = 24
COMMAND_TIMEOUT = 5
MAX_COMMAND_LENGTH = 64

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received – shutting down.", signum)
    _running = False


def setup_gpio():
    if GPIO is None:
        logger.warning("RPi.GPIO not available – GPIO control disabled.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(BACKLIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
        logger.info("GPIO %d configured as output (initial LOW).", BACKLIGHT_PIN)
        return True
    except Exception as exc:
        logger.error("GPIO setup failed: %s", exc)
        return False


def cleanup_gpio():
    if GPIO is None:
        return
    try:
        GPIO.output(BACKLIGHT_PIN, GPIO.LOW)
        GPIO.cleanup()
        logger.info("GPIO cleaned up.")
    except Exception as exc:
        logger.error("GPIO cleanup error: %s", exc)


def handle_client(conn, addr):
    logger.info("Connection from %s:%d", addr[0], addr[1])
    try:
        while _running:
            try:
                data = conn.recv(64)
            except socket.timeout:
                continue
            except OSError as exc:
                logger.error("Socket recv error: %s", exc)
                break

            if not data:
                break

            command = data.decode("utf-8", errors="replace").strip()
            logger.info("Received command: %r", command)

            if command == "on":
                GPIO.output(BACKLIGHT_PIN, GPIO.HIGH)
                reply = "backlight on"
            elif command == "off":
                GPIO.output(BACKLIGHT_PIN, GPIO.LOW)
                reply = "backlight off"
            else:
                reply = "unknown command"

            try:
                conn.sendall(reply.encode("utf-8"))
            except OSError as exc:
                logger.error("Failed to send reply: %s", exc)
                break
    finally:
        try:
            conn.close()
        except OSError:
            pass
        logger.info("Connection closed from %s:%d", addr[0], addr[1])


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not setup_gpio():
        logger.warning("Continuing without GPIO backlight control.")

    server_socket = None
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((LISTEN_ADDRESS, LISTEN_PORT))
        server_socket.listen(1)
        server_socket.settimeout(COMMAND_TIMEOUT)
        logger.info("Listening on %s:%d", LISTEN_ADDRESS, LISTEN_PORT)

        while _running:
            try:
                conn, addr = server_socket.accept()
            except socket.timeout:
                continue
            except OSError as exc:
                logger.error("Accept error: %s", exc)
                break

            handle_client(conn, addr)

    except OSError as exc:
        logger.error("Socket error: %s", exc)
    finally:
        if server_socket is not None:
            try:
                server_socket.close()
            except OSError:
                pass
        cleanup_gpio()
        logger.info("Shutdown complete.")


if __name__ == "__main__":
    main()

