import signal
import sys
import time

try:
    from gpiozero import Button, LED
    from gpiozero.exc import BadPinFactory, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

DOOR_SENSOR_PIN = 19
SIREN_LED_PIN = 26
SAMPLE_INTERVAL = 0.4
NUM_SAMPLES = 8
BOUNCE_TIME = 0.05

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        door_sensor = Button(
            DOOR_SENSOR_PIN,
            pull_up=False,
            bounce_time=BOUNCE_TIME,
        )
        siren = LED(SIREN_LED_PIN)
    except BadPinFactory:
        print("Error: Could not initialize GPIO. Is this running on a Raspberry Pi?")
        sys.exit(1)
    except Exception as exc:
        print(f"Error: Failed to initialize GPIO devices: {exc}")
        sys.exit(1)

    try:
        for sample_index in range(NUM_SAMPLES):
            if not _running:
                print("\nAborted by user.")
                break

            try:
                if door_sensor.is_pressed:
                    print(f"Sample {sample_index}: Door closed (reed switch closed).")
                else:
                    print(f"Sample {sample_index}: Door open (reed switch open, GPIO HIGH).")
                    siren.on()
                    print("  -> SIREN ON")
            except DeviceClosed:
                print(f"Error: GPIO device closed unexpectedly during sample {sample_index}.")
                break
            except Exception as exc:
                print(f"Error: Failed to read door sensor during sample {sample_index}: {exc}")
                break

            time.sleep(SAMPLE_INTERVAL)

    finally:
        try:
            siren.off()
            siren.close()
        except Exception:
            pass
        try:
            door_sensor.close()
        except Exception:
            pass
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

