try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO is not installed. Install with: pip install RPi.GPIO")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def set_fan_speed(pwm, speed):
    if not 0 <= speed <= 100:
        print("Error: Fan speed must be between 0 and 100.")
        return False
    try:
        pwm.ChangeDutyCycle(speed)
        print(f"Fan speed set to {speed}%")
        return True
    except Exception as e:
        print(f"Error setting fan speed: {e}")
        return False


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)

    pwm = None
    try:
        try:
            pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
            pwm.start(0)
            print(f"Hardware PWM started on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
        except Exception as e:
            print(f"Hardware PWM unavailable ({e}); using software PWM.")
            pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
            pwm.start(0)

        while _running:
            try:
                user_input = input("Enter fan speed (0-100, or 'q' to quit): ")
            except EOFError:
                break

            if user_input.lower() == "q":
                break

            try:
                fan_speed = float(user_input)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100.")
                continue

            if not 0 <= fan_speed <= 100:
                print("Invalid input. Please enter a number between 0 and 100.")
                continue

            set_fan_speed(pwm, fan_speed)

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
        GPIO.cleanup()
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

