import http.server
import socketserver
import signal
import sys
import logging

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is required. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

LED_PIN = 18
SERVER_PORT = 8000

led = None
httpd = None

class LEDRequestHandler(http.server.SimpleHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/led/on':
            try:
                led.on()
                self.send_response(200)
                self.send_header('Content-type', 'text/plain')
                self.end_headers()
                self.wfile.write(b'LED is ON')
            except GPIOZeroError as e:
                logger.error(f"GPIO error turning LED on: {e}")
                self.send_error(500, f"Internal Server Error: {e}")
        elif self.path == '/led/off':
            try:
                led.off()
                self.send_response(200)
                self.send_header('Content-type', 'text/plain')
                self.end_headers()
                self.wfile.write(b'LED is OFF')
            except GPIOZeroError as e:
                logger.error(f"GPIO error turning LED off: {e}")
                self.send_error(500, f"Internal Server Error: {e}")
        else:
            self.send_error(404, 'Not Found')

def cleanup(signum=None, frame=None):
    global httpd, led
    logger.info("Shutting down...")
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception as e:
            logger.error(f"Error shutting down HTTP server: {e}")
    if led is not None:
        try:
            led.close()
        except Exception as e:
            logger.error(f"Error closing LED: {e}")
    if signum is not None:
        sys.exit(0)

def main():
    global led, httpd
    try:
        led = LED(LED_PIN)
        logger.info(f"LED initialized on GPIO{LED_PIN}")
    except GPIOZeroError as e:
