import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

I2C_BUS = 1
BH1750_ADDR = 0x23
BH1750_POWER_ON = 0x01
BH1750_CONTINUOUS_HIGH_RES_MODE = 0x10
BH1750_MEAS_DELAY_S = 0.12

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(BH1750_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(BH1750_ADDR, reg)


def _init_sensor(bus):
    _write_reg(bus, BH1750_POWER_ON, 0x01)
    time.sleep(0.01)
    _write_reg(bus, BH1750_CONTINUOUS_HIGH_RES_MODE, 0x10)
    time.sleep(BH1750_MEAS_DELAY_S)


