    try:
        data = bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
    except OSError:
        return None
    if data is None or len(data) < 2:
        return None
    raw = (data[0] << 8) | data[1]
    if raw == 0:
        return None
    return raw / 1.2


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            _init_sensor(bus)
        except OSError as e:
            print(f"Error: BH1750 not detected at 0x{BH1750_ADDR:02X} on bus {I2C_BUS}: {e}", file=sys.stderr)
