            if lux is None:
                print("Warning: sensor read failed (device absent or bus error).", file=sys.stderr)
            else:
                print(f"Luminance: {lux:.2f} lux")
            time.sleep(1)
    finally:
        try:
            bus.close()
        except Exception:
            pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

