import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError as exc:
    print(f"Error: Failed to initialize GPIO (not running on a Raspberry Pi?): {exc}")
    sys.exit(1)
except ImportError as exc:
    print(f"Error: RPi.GPIO library not installed: {exc}")
    sys.exit(1)

LED_PIN = 17
BLINK_INTERVAL = 0.5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio(pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

def cleanup_gpio(pin):
    try:
        GPIO.output(pin, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup(pin)

def main():
    global _running
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        setup_gpio(LED_PIN)
    except PermissionError:
        print(f"Error: Permission denied accessing GPIO (run as root or add user to gpio group).")
        cleanup_gpio(LED_PIN)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: Failed to initialize GPIO: {exc}")
        cleanup_gpio(LED_PIN)
        sys.exit(1)

    print(f"Starting blink on GPIO{LED_PIN} with interval {BLINK_INTERVAL}s")
    try:
        while _running:
            GPIO.output(LED_PIN, GPIO.HIGH)
            time.sleep(BLINK_INTERVAL)
            if not _running:
                break
            GPIO.output(LED_PIN, GPIO.LOW)
            time.sleep(BLINK_INTERVAL)
    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received, exiting...")
    except Exception as exc:
        print(f"Error during blink loop: {exc}")
    finally:
        cleanup_gpio(LED_PIN)
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

