import RPi.GPIO as GPIO
import time
import sys

LED_PIN = 17

def setup_gpio():
    """Configure GPIO and return an LED object, or raise on failure."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    return GPIO

def blink_led(led):
    """Blink the LED with 1-second on/off cycles, printing status messages."""
    while True:
        led.on()
        print("LED is ON")
        time.sleep(1)
        led.off()
        print("LED is OFF")
        time.sleep(1)

def main():
    led = None
    try:
        led = setup_gpio()
        blink_led(led)
    except KeyboardInterrupt:
        print("Program stopped. LED is OFF.")
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        if led is not None:
            try:
                led.off()
                GPIO.cleanup()
            except Exception:
                pass

if __name__ == "__main__":
    main()

