#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter with capacitive touchpads.

Touchpad A (GPIO5)  -> bit 4 (MSB)
Touchpad B (GPIO6)  -> bit 2 (middle)
Touchpad C (GPIO12) -> bit 1 (LSB)

LEDs:  onboard green (GPIO7), blue (GPIO8)
Buzzer: GPIO13
APA102: data GPIO10, clock GPIO11
14-segment display: I2C (default address 0x71)
"""

import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

try:
    from gpiozero import LED, Buzzer, DigitalInputDevice
except ImportError:
    print("Error: gpiozero is required. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Pin / I2C / APA102 constants
# ---------------------------------------------------------------------------
I2C_BUS = 1
DISPLAY_ADDR = 0x71

DATA_PIN = 10
CLOCK_PIN = 11

GREEN_LED_PIN = 7
BLUE_LED_PIN = 8
BUZZER_PIN = 13

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_green_led = None
_blue_led = None
_buzzer = None
_touch_a = None
_touch_b = None
_touch_c = None
_display_bus = None


def _cleanup():
    """Turn off all outputs and release resources."""
    global _green_led, _blue_led, _buzzer, _display_bus
    for dev in (_green_led, _blue_led, _buzzer):
        if dev is not None:
            try:
                dev.off()
            except Exception:
                pass
    if _display_bus is not None:
        try:
            _display_bus.close()
        except Exception:
            pass
    _display_bus = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_display(value):
    """Write a 4-bit value to the 14-segment display over I2C."""
    if _display_bus is None:
        return
    try:
        _display_bus.write_i2c_block_data(DISPLAY_ADDR, value, [0x00])
    except OSError as exc:
        print(f"Display write error: {exc}", file=sys.stderr)


def _update_leds(bit_states):
    """Drive the onboard green and blue LEDs according to bit_states."""
    if _green_led is not None:
        _green_led.on() if bit_states & 0x08 else _green_led.off()
    if _blue_led is not None:
        _blue_led.on() if bit_states & 0x04 else _blue_led.off()


def _update_buzzer(bit_states):
    """Sound a 0.5 s tone on the buzzer when bit_states is non-zero."""
    if _buzzer is not None:
        if bit_states:
            _buzzer.on()
            time.sleep(0.5)
            _buzzer.off()
        else:
            _buzzer.off()


def _update_apa102(bit_states):
    """Drive the APA102 LED strip: dim white at index 0, all white at 7, else
    a single pixel red/green/blue at the index equal to the decimal value."""
    try:
        from apa102 import APA102
    except ImportError:
        print("Error: apa102 library not found. Install with: pip install apa102", file=sys.stderr)
        return

    pixels = [0] * 8
    if bit_states == 0:
        pixels[0] = 0xA0000000  # dim white
    elif bit_states == 7:
        for i in range(8):
            pixels[i] = 0xA0FFFFFF  # full white
    else:
        idx = bit_states & 0x07
        pixels[idx] = 0xA0000000  # full red/green/blue
    apa = APA102(num_led=8, global_brightness=1, data_pin=DATA_PIN, clock_pin=CLOCK_PIN)
    apa.update(pixels)


def _on_touch(channel):
    """Callback for touchpad events."""
    global bit_states
    try:
        if channel == 0:
            bit_states ^= 0x08
        elif channel == 1:
            bit_states ^= 0x04
        elif channel == 2:
            bit_states ^= 0x01
        _update_leds(bit_states)
        _write_display(bit_states)
        _update_apa102(bit_states)
        _update_buzzer(bit_states)
    except Exception as exc:
        print(f"Touch event handler error: {exc}", file=sys.stderr)


def main():
    global bit_states, _green_led, _blue_led, _buzzer, _touch_a, _touch_b, _touch_c, _display_bus

    bit_states = 0

    # --- LED outputs ---------------------------------------------------------
    try:
        _green_led = LED(GREEN_LED_PIN)
        _blue_led = LED(BLUE_LED_PIN)
    except Exception as exc:
        print(f"LED init error: {exc}", file=sys.stderr)

    # --- Buzzer --------------------------------------------------------------
    try:
        _buzzer = Buzzer(BUZZER_PIN)
    except Exception as exc:
        print(f"Buzzer init error: {exc}", file=sys.stderr)

    # --- APA102 LED strip ----------------------------------------------------
    try:
        from apa102 import APA102
        apa = APA102(num_led=8, global_brightness=1, data_pin=DATA_PIN, clock_pin=CLOCK_PIN)
        apa.update([0] * 8)
    except Exception as exc:
        print(f"APA102 init error: {exc}", file=sys.stderr)

    # --- 14-segment display --------------------------------------------------
    try:
        _display_bus = smbus.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"I2C bus error: {exc}", file=sys.stderr)
        _display_bus = None

    # --- Touchpads (capacitive, active-low) ----------------------------------
    try:
        _touch_a = DigitalInputDevice(5, pull_up=True, bounce_time=0.05)
        _touch_b = DigitalInputDevice(6, pull_up=True, bounce_time=0.05)
        _touch_c = DigitalInputDevice(12, pull_up=True, bounce_time=0.05)
    except Exception as exc:
        print(f"Touchpad init error: {exc}", file=sys.stderr)

    if _touch_a is not None:
        _touch_a.when_activated = lambda: _on_touch(0)
    if _touch_b is not None:
        _touch_b.when_activated = lambda: _on_touch(1)
    if _touch_c is not None:
        _touch_c.when_activated = lambda: _on_touch(2)

    # --- Graceful shutdown ---------------------------------------------------
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    print("Rainbow HAT binary counter ready. Press touchpads A/B/C to toggle bits.")
    print("Press Ctrl+C to exit.")

    try:
        while _running:
            time.sleep(0.1)
    except Exception as exc:
        print(f"Main loop error: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

