import time
import atexit
import logging
import signal
import sys
from typing import Optional

try:
    import board
    import busio
    from adafruit_pca9685 import PCA9685
except ImportError as e:
    logging.error(f"Missing required libraries: {e}. Install with: pip install adafruit-circuitpython-pca9685")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DEFAULT_PWM_FREQUENCY = 60
DEFAULT_MIN_PULSE_WIDTH_US = 150
DEFAULT_MAX_PULSE_WIDTH_US = 600
DEFAULT_SERVO_DELAY = 0.029
SERVO_MIN_PULSE_WIDTH_US = 1000
SERVO_MAX_PULSE_WIDTH_US = 2000

class Fuchikoma:
    SERVO_CHANNELS = {
        "claw": 0,
        "lock": 1,
        "water_gun": 2,
    }

    def __init__(self, i2c_bus: Optional[i2c_bus] = None, pwm_frequency: int = DEFAULT_PWM_FREQUENCY):
        self.pwm_frequency = pwm_frequency
        self.pwm: Optional[PCA9685] = None
        self._initialize_pca9685(i2c_bus)
        atexit.register(self.cleanup)

    def _initialize_pca9685(self, i2c_bus: Optional[i2c_bus] = None):
        try:
            if i2c_bus is None:
                i2c_bus = busio.I2C(board.SCL, board.SDA)
            self.pwm = PCA9685(i2c_bus, address=0x40)
            self.pwm.frequency = self.pwm_frequency
            logging.info(f"PCA9685 initialized on I2C bus at address 0x40, frequency {self.pwm_frequency} Hz")
        except (ValueError, OSError) as e:
            logging.error(f"Failed to initialize PCA9685: {e}")
            raise

    def _validate_servo_name(self, servo_name: str) -> None:
        if servo_name not in self.SERVO_CHANNELS:
            raise ValueError(f"Invalid servo name: {servo_name}. Valid names: {list(self.SERVO_CHANNELS.keys())}")

    def _validate_angle(self, servo_name: str, angle: float) -> None:
        if not -77 <= angle <= 77:
            raise ValueError(f"Angle {angle} out of range for servo {servo_name}. Must be between -77 and 77.")

    def _calculate_pulse_width_us(self, angle: float) -> int:
        zero_pulse_us = (SERVO_MIN_PULSE_WIDTH_US + SERVO_MAX_PULSE_WIDTH_US) // 2
        pulse_width_us = zero_pulse_us + (angle / 77) * (SERVO_MAX_PULSE_WIDTH_US - zero_pulse_us)
        return int(pulse_width_us)

    def _set_servo_pulse(self, channel: int, pulse_width_us: int) -> None:
        if self.pwm is None:
            raise RuntimeError("PCA9685 not initialized.")
        pulse_us = max(DEFAULT_MIN_PULSE_WIDTH_US, min(DEFAULT_MAX_PULSE_WIDTH_US, pulse_width_us))
        self.pwm.channels[channel].duty_cycle = pulse_us

    def move_servo(self, servo_name: str, angle: float, delay: float = DEFAULT_SERVO_DELAY) -> None:
        self._validate_servo_name(servo_name)
        self._validate_angle(servo_name, angle)
        channel = self.SERVO_CHANNELS[servo_name]
        pulse_width_us = self._calculate_pulse_width_us(angle)
        self._set_servo_pulse(channel, pulse_width_us)
        time.sleep(delay)
        self._set_servo_pulse(channel, 0)

    def bite(self) -> None:
        self.move_servo("claw", -75)

    def open_claw(self) -> None:
        self.move_servo("claw", 75)

    def lock(self) -> None:
        self.move_servo("lock", 75)

    def unlock(self) -> None:
        self.move_servo("lock", -75)

    def shoot(self) -> None:
        self.move_servo("water_gun", -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self) -> None:
        self.move_servo("water_gun", 75)

    def cleanup(self) -> None:
        if self.pwm is not None:
            try:
                for channel in self.SERVO_CHANNELS.values():
                    self.pwm.channels[channel].duty_cycle = 0
                logging.info("PCA9685 channels de-energized.")
            except Exception as e:
                logging.error(f"Error during PCA9685 cleanup: {e}")
            finally:
                try:
                    self.pwm.deinit()
                except Exception:
                    pass
                self.pwm = None
        logging.info("Cleanup complete.")


def main():
    fuchikoma = None
    try:
        fuchikoma = Fuchikoma()
        fuchikoma.bite()
        time.sleep(1)
        fuchikoma.open_claw()
        time.sleep(1)
        fuchikoma.lock()
        time.sleep(1)
        fuchikoma.unlock()
        time.sleep(1)
        fuchikoma.shoot()
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if fuchikoma is not None:
            fuchikoma.cleanup()


if __name__ == "__main__":
    main()

