LOG_FILE_SIZE_LIMIT = 1024 * 1024  # 1 MB
READ_INTERVAL = 5  # seconds
DEFAULT_LOG_FILE = "energy_log.json"

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# Global state
data_queue: queue.Queue = queue.Queue()
stop_event: threading.Event = threading.Event()
sensor_lock = threading.Lock()
sensor_data = {
    "sensor1": {"active_power": 0.0, "voltage": 0.0, "current": 0.0, "frequency": 0.0, "power_factor": 0.0},
    "sensor2": {"active_power": 0.0, "voltage": 0.0, "current": 0.0, "frequency": 0.0, "power_factor": 0.0},
    "sensor3": {"active_power": 0.0, "voltage": 0.0, "current": 0.0, "frequency": 0.0, "power_factor": 0.0},
}

# Signal handler for graceful shutdown
def signal_handler(signum, frame):
    logger.info("Signal received, shutting down...")
    stop_event.set()

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


def generate_sensor_data() -> dict:
    """Generates simulated sensor data."""
    return {
        "active_power": round(random.uniform(50, 200), 2),
        "voltage": round(random.uniform(220, 240), 2),
        "current": round(random.uniform(0.2, 1.0), 2),
        "frequency": round(random.uniform(59.5, 60.5), 2),
        "power_factor": round(random.uniform(0.8, 1.0), 2),
    }


def acquire_sensor_data(sensor_id: str) -> Optional[dict]:
    """Simulates acquiring sensor data from a specific sensor."""
    try:
        time.sleep(random.uniform(0.1, 0.5))  # Simulate network latency
        data = generate_sensor_data()
        data["timestamp"] = datetime.datetime.now().isoformat()
        data["sensor_id"] = sensor_id
        return data
    except Exception as e:
        logger.error(f"Error acquiring data from sensor {sensor_id}: {e}")
        return None


def log_data(data: dict, log_file: str) -> bool:
    """Logs sensor data to a file, handling rotation and permissions."""
    try:
        with sensor_lock:
            log_dir = os.path.dirname(log_file)
            if log_dir and not os.path.exists(log_dir):
                os.makedirs(log_dir, exist_ok=True)

            file_exists = os.path.isfile(log_file)
            file_size = os.path.getsize(log_file) if os.path.exists(log_file) else 0

            if file_size > LOG_FILE_SIZE_LIMIT or file_exists:
                timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                compressed_file = f"{log_file}.{timestamp}.gz"
                try:
                    with open(log_file, "rb") as f:
                        data = f.read()
                    import gzip
                    with gzip.open(compressed_file, "wb") as f:
                        f.write(data)
                    os.remove(log_file)
                    logger.info(f"Rotated log file to {compressed_file}")
                except Exception as e:
                    logger.error(f"Error rotating log file: {e}")
                    return False

            # Write data to file
            with open(log_file, "a") as f:
                f.write(json.dumps(data) + "\n")
            os.chmod(log_file, 0o600)  # Set file permissions to 0o600
            return True
    except Exception as e:
        logger.error(f"Error logging data: {e}")
        return False


def data_acquisition_thread(sensor_id: str, log_file: str):
    """Acquires sensor data and logs it to the queue."""
    while not stop_event.is_set():
        try:
            data = acquire_sensor_data(sensor_id)
            if data:
                data_queue.put((sensor_id, data))
            else:
                logger.warning(f"Failed to acquire data from sensor {sensor_id}")
        except Exception as e:
            logger.error(f"Error in data acquisition thread for sensor {sensor_id}: {e}")
        stop_event.wait(READ_INTERVAL)


def display_data(data: dict) -> None:
    """Displays sensor data in a user-friendly format."""
    print("\n--- Sensor Data ---")
    print(f"Sensor ID: {data['sensor_id']}")
    print(f"Active Power: {data['active_power']} W")
    print(f"Voltage: {data['voltage']} V")
    print(f"Current: {data['current']} A")
    print(f"Frequency: {data['frequency']} Hz")
    print(f"Power Factor: {data['power_factor']}")
    print(f"Timestamp: {data['timestamp']}")


def get_data_for_date(log_file: str, date_str: str) -> list:
    """Retrieves sensor data for a specific date."""
    data = []
    try:
        with open(log_file, "r") as f:
            for line in f:
                try:
                    entry = json.loads(line.strip())
                    if entry.get("timestamp"):
                        timestamp = datetime.datetime.fromisoformat(entry["timestamp"])
                        if timestamp.date().strftime("%Y-%m-%d") == date_str:
                            data.append(entry)
                except json.JSONDecodeError:
                    continue
        return data
    except FileNotFoundError:
        logger.error(f"Log file not found: {log_file}")
        return []
    except Exception as e:
        logger.error(f"Error retrieving data for date {date_str}: {e}")
        return []


def calculate_statistics(data: list, sensor_id: str) -> Tuple[Optional[float], Optional[float], Optional[float]]:
    """Calculates statistics for a specific sensor on a given date."""
    if not data:
        return None, None, None

    active_powers = [entry["active_power"] for entry in data if entry["sensor_id"] == sensor_id]
    if not active_powers:
        return None, None, None

    min_active_power = min(active_powers)
    max_active_power = max(active_powers)
    avg_active_power = sum(active_powers) / len(active_powers)

    return min_active_power, max_active_power, avg_active_power


def main():
    """Main function to run the energy monitoring system."""
    parser = argparse.ArgumentParser(description="Energy Monitoring System for Raspberry Pi")
    parser.add_argument("--log_file", type=str, default=DEFAULT_LOG_FILE, help="Path to the log file")
    args = parser.parse_args()

    # Start data acquisition threads
    threads = []
    for i in range(1, NUM_SENSORS + 1):
        sensor_id = f"sensor{i}"
        thread = threading.Thread(
            target=data_acquisition_thread,
            args=(sensor_id, args.log_file),
            daemon=True,
        )
        threads.append(thread)
        thread.start()

    try:
        while not stop_event.is_set():
            try:
                sensor_id, data = data_queue.get(timeout=1)
                if log_data(data, args.log_file):
                    logger.info(f"Data logged for sensor {sensor_id}")
                else:
                    logger.error(f"Failed to log data for sensor {sensor_id}")
            except queue.Empty:
                continue
            except Exception as e:
                logger.error(f"Error processing data from queue: {e}")

            # Command-line interface
            print("\nOptions:")
            print("1. View current sensor data")
            print("2. View sensor data for a specific date")
            print("3. View statistics for a specific date")
            print("4. Quit")
            choice = input("Enter your choice: ")

            if choice == "1":
                try:
                    sensor_id = input("Enter sensor ID (e.g., sensor1): ")
                    if sensor_id in sensor_data:
                        display_data(sensor_data[sensor_id])
                    else:
                        print("Invalid sensor ID.")
                except Exception as e:
                    logger.error(f"Error viewing sensor data: {e}")

            elif choice == "2":
                try:
                    date_str = input("Enter date (YYYY-MM-DD): ")
                    data = get_data_for_date(args.log_file, date_str)
                    if data:
                        print(f"Data for {date_str}:")
                        for entry in data:
                            print(f"  {entry['sensor_id']}: {entry['active_power']} W")
                    else:
                        print(f"No data found for {date_str}.")
                except Exception as e:
                    logger.error(f"Error retrieving data for date: {e}")

            elif choice == "3":
                try:
                    date_str = input("Enter date (YYYY-MM-DD): ")
                    min_ap, max_ap, avg_ap = calculate_statistics(
                        get_data_for_date(args.log_file, date_str), "sensor1"
                    )
                    if min_ap is not None:
                        print(f"Sensor 1 - Min Active Power: {min_ap} W")
                    if max_ap is not None:
                        print(f"Sensor 1 - Max Active Power: {max_ap} W")
                    if avg_ap is not None:
                        print(f"Sensor 1 - Average Active Power: {avg_ap:.2f} W")
                except Exception as e:
                    logger.error(f"Error calculating statistics: {e}")

            elif choice == "4":
                print("Exiting...")
                break

            else:
                print("Invalid choice. Please try again.")

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        stop_event.set()
        for thread in threads:
            thread.join(timeout=2)
        logger.info("Energy monitoring system stopped.")


if __name__ == "__main__":
    main()

