import time
import signal
import sys
import board
import busio
import adafruit_tcs34725

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    """Initializes the I2C bus on the Raspberry Pi."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_color_sensor(i2c_bus):
    """Initializes the TCS34725 color sensor."""
    try:
        color_sensor = adafruit_tcs34725.TCS34725(i2c_bus)
        # 50ms integration time, 4x gain
        color_sensor.integration_time = 0.05
        color_sensor.gain = 4
        return color_sensor
    except Exception as e:
        print(f"Error initializing color sensor: {e}")
        return None

def read_color_data(color_sensor):
    """Reads color data from the TCS34725 sensor."""
    try:
        red, green, blue, clear = color_sensor.rgb_bytes
        return red, green, blue, clear
    except Exception as e:
        print(f"Error reading color data: {e}")
        return 0, 0, 0, 0

def get_dominant_color(image_path):
    """Determines the dominant color in an image."""
    try:
        from PIL import Image
        image = Image.open(image_path).resize((100, 100))
        pixels = image.getcolors(10000)
        if pixels:
            dominant_color = max(pixels, key=lambda item: item[0])[1]
            return dominant_color
        return (0, 0, 0)
    except FileNotFoundError:
        print(f"Error: Image file '{image_path}' not found.")
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def main():
    """Main function to read color data and image color."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    color_sensor = initialize_color_sensor(i2c_bus)
    if color_sensor is None:
        i2c_bus.deinit()
        sys.exit(1)

    try:
        while _running:
            red, green, blue, clear = read_color_data(color_sensor)
            dominant_color = get_dominant_color("image.jpg")

            print(f"Raw Color Data: R={red}, G={green}, B={blue}, Clear={clear}")
            print(f"Dominant Color in Image: {dominant_color}")

            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        try:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        except Exception:
            pass

if __name__ == "__main__":
    main()

