import json
import socket
import signal
import sys
import time
import logging
from typing import Optional, Tuple

# Configure logging to stderr
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    stream=sys.stderr
)
logger = logging.getLogger(__name__)

# Constants
LISTEN_HOST = '127.0.0.1'
LISTEN_PORT = 9099
GPS_READ_TIMEOUT = 2.0  # seconds
SIMULATED_LAT = 37.7749
SIMULATED_LON = -122.4194

# Global state
tracking_state = False
gps_socket: Optional[socket.socket] = None
listening_socket: Optional[socket.socket] = None


def read_gps_position() -> Tuple[Optional[float], Optional[float]]:
    """
    Reads GPS coordinates from the UART GPS module.
    Returns (lat, lon) or (None, None) if unavailable or timed out.
    """
    global gps_socket
    if gps_socket is None:
        return None, None

    try:
        # Read a line from the GPS UART
        raw = gps_socket.readline()
        if not raw:
            return None, None  # Timeout

        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None, None

        # Parse NMEA $GPRMC sentences
        if line.startswith('$GPRMC'):
            parts = line.split(',')
            if len(parts) >= 7 and parts[2] == 'A':  # Valid fix
                lat = _decode_coordinate(parts[3])
                lon = _decode_coordinate(parts[5])
                if lat is not None and lon is not None:
                    return lat, lon
        return None, None

    except socket.timeout:
        return None, None
    except Exception as e:
        logger.error(f"GPS read error: {e}")
        return None, None


def _decode_coordinate(raw: str) -> Optional[float]:
    """Decode a NMEA coordinate string (e.g., '4137.123456') into decimal degrees."""
    if not raw:
        return None
    try:
        dot = raw.find('.')
        if dot == -1:
            return None
        deg_len = dot - 2
        if deg_len <= 0:
            return None
        degrees = float(raw[:deg_len])
        minutes = float(raw[deg_len:])
        return degrees + minutes / 60.0
    except ValueError:
        return None


def handle_command(command: str) -> str:
    """
    Handles GPS tracking commands.
    Commands: 'start', 'stop', 'report'
    """
    global tracking_state
    try:
        if command == 'start':
            tracking_state = True
            return "Tracking started"
        elif command == 'stop':
            tracking_state = False
            return "Tracking stopped"
        elif command == 'report':
            lat, lon = read_gps_position()
            if lat is not None and lon is not None:
                return json.dumps({'lat': lat, 'lon': lon})
            else:
                return json.dumps({'lat': SIMULATED_LAT, 'lon': SIMULATED_LON})
        else:
            return "Invalid command. Valid commands: start, stop, report"
    except Exception as e:
        logger.error(f"Command handling error: {e}")
        return "Error processing command"


def main():
    """Main function to run the GPS tracking server."""
    global gps_socket, listening_socket

    # Initialize UART GPS connection (example: pyserial)
    try:
        import serial
        gps_socket = serial.Serial('/dev/serial0', baudrate=9600, timeout=GPS_READ_TIMEOUT)
        logger.info("GPS UART initialized on /dev/serial0")
    except Exception as e:
        logger.warning(f"GPS UART unavailable ({e}); using simulated coordinates")
        gps_socket = None

    # Create listening socket
    try:
        listening_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        listening_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        listening_socket.bind((LISTEN_HOST, LISTEN_PORT))
        listening_socket.listen(5)
        listening_socket.settimeout(1.0)  # Allow periodic checks for shutdown
        logger.info(f"Server listening on {LISTEN_HOST}:{LISTEN_PORT}")
    except Exception as e:
        logger.error(f"Failed to create listening socket: {e}")
        sys.exit(1)

    # Signal handlers for graceful shutdown
    def signal_handler(signum, frame):
        logger.info(f"Received signal {signum}, shutting down...")
        shutdown()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            try:
                client_socket, client_address = listening_socket.accept()
                logger.info(f"Connection from {client_address}")
                try:
                    command = client_socket.recv(1024).decode('utf-8').strip()
                    if command:
                        response = handle_command(command)
                        client_socket.sendall(response.encode('utf-8'))
                    else:
                        logger.warning("Empty command received")
                finally:
                    client_socket.close()
            except socket.timeout:
                continue
            except Exception as e:
                logger.error(f"Accept/recv error: {e}")
                continue
    except KeyboardInterrupt:
        logger.info("Keyboard interrupt received")
    finally:
        shutdown()


def shutdown():
    """Clean up resources on exit."""
    global gps_socket, listening_socket
    logger.info("Shutting down...")
    if gps_socket is not None:
        try:
            gps_socket.close()
        except Exception:
            pass
        gps_socket = None
    if listening_socket is not None:
        try:
            listening_socket.close()
        except Exception:
            pass
        listening_socket = None
    logger.info("Cleanup complete")


if __name__ == '__main__':
    main()

