BUZZER_PIN = 20
X_THRESHOLD_LOW = 0.3
X_THRESHOLD_HIGH = 0.7
SAMPLE_INTERVAL = 0.1
LOOP_DELAY = 0.01

# Global resources for cleanup
bus = None
led = None
buzzer = None
running = True


def cleanup():
    """Turn off outputs and release resources on every exit path."""
    global led, buzzer, bus
    if led is not None:
        try:
            led.off()
        except Exception:
            pass
    if buzzer is not None:
        try:
            buzzer.off()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    global running
    running = False


def init_gpio():
    """Initialize GPIO pins for LED and buzzer using RPi.GPIO."""
    global led, buzzer
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BUZZER_PIN, GPIO.OUT, initial=GPIO.LOW)
        led = GPIO
        buzzer = GPIO
    except ImportError:
        print("RPi.GPIO not available; running in simulation mode.")
        led = None
        buzzer = None
    except Exception as e:
        print(f"GPIO initialization error: {e}")
        led = None
        buzzer = None


def init_i2c():
    """Initialize the I2C bus and verify the LIS3DH device."""
    global bus
    try:
        bus = smbus.SMBus(I2C_BUS)
    except Exception as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        return False

    try:
        who_am_i = bus.read_byte_data(LIS3DH_ADDRESS, LIS3DH_WHO_AM_I)
    except Exception as e:
        print(f"Error reading WHO_AM_I from LIS3DH at 0x{LIS3DH_ADDRESS:02X}: {e}")
        bus.close()
        bus = None
        return False

    if who_am_i != EXPECTED_WHO_AM_I:
        print(f"WHO_AM_I mismatch: got 0x{who_am_i:02X}, expected 0x{EXPECTED_WHO_AM_I:02X}")
        bus.close()
        bus = None
        return False

    return True


def read_acceleration():
    """Read and combine the two data bytes into a signed 16-bit value."""
    try:
        data = bus.read_i2c_block_data(LIS3DH_ADDRESS, LIS3DH_XOUT_L, 2)
        raw = (data[0] << 8) | data[1]
        if raw >= 0x8000:
            raw -= 0x10000
        return raw / 1000.0
    except Exception as e:
        print(f"Error reading acceleration data: {e}")
        return None


def main():
    global running

    signal.signal(signal.SIGTERM, signal_handler)

    init_gpio()
    if not init_i2c():
        cleanup()
        sys.exit(1)

    try:
        while running:
            acceleration = read_acceleration()
            if acceleration is None:
                if led is not None:
                    led.output(0)
                if buzzer is not None:
                    buzzer.output(0)
                time.sleep(SAMPLE_INTERVAL)
                continue

            print(f"Acceleration: {acceleration:.2f} g")

            if abs(acceleration) > X_THRESHOLD_HIGH:
                if buzzer is not None:
                    buzzer.output(1)
            else:
                if buzzer is not None:
                    buzzer.output(0)

            if abs(acceleration) > X_THRESHOLD_LOW:
                if led is not None:
                    led.output(1)
            else:
                if led is not None:
                    led.output(0)

            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        cleanup()
        print("Exiting program.")


if __name__ == "__main__":
    main()

