import smbus
import time
import signal
import threading
import sys

# MPU-6050 I2C address and registers
MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
GYRO_XOUT_H = 0x43
GYRO_YOUT_H = 0x45
GYRO_ZOUT_H = 0x47

# Motor GPIO pins (BCM numbering)
MOTOR_PINS = [17, 18, 27]

# Global state
bus = None
running = True
kp_values = {'xkp': 1.0, 'ykp': 1.0, 'zkp': 1.0}
motor_pwms = [None, None, None]

# Lock for thread-safe access to shared resources
state_lock = threading.Lock()


def init_mpu6050():
    """Initialize the MPU-6050 sensor on I2C bus 1."""
    global bus
    try:
        bus = smbus.SMBus(1)
        # Wake up the MPU-6050 (clear sleep bit)
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
        time.sleep(0.1)  # Allow sensor to stabilize
    except IOError as e:
        print(f"Error initializing MPU-6050: {e}")
        sys.exit(1)


def read_raw_gyro():
    """Read raw gyroscope data (signed 16-bit) from the MPU-6050."""
    try:
        # Read 6 bytes starting at GYRO_XOUT_H
        data = bus.read_i2c_block_data(MPU6050_ADDR, GYRO_XOUT_H, 6)
        # Combine high and low bytes
        gyro_x = (data[0] << 8) | data[1]
        gyro_y = (data[2] << 8) | data[3]
        gyro_z = (data[4] << 8) | data[5]
        # Convert to signed 16-bit
        if gyro_x >= 0x8000:
            gyro_x -= 0x10000
        if gyro_y >= 0x8000:
            gyro_y -= 0x10000
        if gyro_z >= 0x8000:
            gyro_z -= 0x10000
        return gyro_x, gyro_y, gyro_z
    except IOError as e:
        print(f"I2C read error: {e}")
        return 0, 0, 0


def integrate_gyro(gyro_x, gyro_y, gyro_z, dt):
    """Integrate angular velocity to obtain angular displacement."""
    global state_lock
    with state_lock:
