try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or to be run on a Raspberry Pi.", file=sys.stderr)
    sys.exit(1)

DOOR_LOCK_PIN = 27
UNLOCK_DURATION = 5.0
LOOP_DELAY = 0.1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup(pin):
    try:
        GPIO.output(pin, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup(pin)
    except Exception:
        pass

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(DOOR_LOCK_PIN, GPIO.OUT, initial=GPIO.LOW)

    try:
        while _running:
            authorized = False
            if authorized:
                GPIO.output(DOOR_LOCK_PIN, GPIO.HIGH)
                time.sleep(UNLOCK_DURATION)
                GPIO.output(DOOR_LOCK_PIN, GPIO.LOW)
            time.sleep(LOOP_DELAY)
    except Exception as exc:
        print(f"Error during operation: {exc}", file=sys.stderr)
    finally:
        _cleanup(DOOR_LOCK_PIN)
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

