import signal
import sys
import time
import logging
import numpy as np
from functools import partial
from contextlib import contextmanager

try:
    import smbus2 as smbus
except ImportError:
    import smbus

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_FS_SEL_0 = 0x1C
ACCEL_FS_SEL_2 = 0x00  # ±2 g full scale
ACCEL_SENSITIVITY = 16384.0  # LSB/g for ±2 g range

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    logger.info("Signal %s received, shutting down...", signum)


def _twos_complement(val, bits):
    if val & (1 << (bits - 1)):
        val -= 1 << bits
    return val


def _read_word(bus, addr, reg):
    high = bus.read_byte_data(addr, reg)
    low = bus.read_byte_data(addr, reg + 1)
    val = (high << 8) | low
    return _twos_complement(val, 16)


def _init_mpu6050(bus):
    bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
    time.sleep(0.1)
    bus.write_byte_data(MPU6050_ADDR, ACCEL_FS_SEL_0, ACCEL_FS_SEL_2)
    time.sleep(0.01)


def _read_accel(bus):
    x = _read_word(bus, MPU6050_ADDR, ACCEL_XOUT_H)
    return x / ACCEL_SENSITIVITY


def _rms(data):
    return float(np.sqrt(np.mean(np.square(data))))


def _variance(data):
    return float(np.var(data))


def _detect_defective(magnitude, variance):
    return magnitude > 2.5 or variance > 0.4


def _process_samples(bus, num_samples):
    magnitudes = []
    for i in range(num_samples):
        if not _running:
            break
        try:
            x = _read_accel(bus)
        except OSError as exc:
            logger.error("I2C read error on sample %d: %s", i, exc)
            return None, None
        magnitudes.append(x)
        time.sleep(0.01)
    if not magnitudes:
        return None, None
    return _rms(magnitudes), _variance(magnitudes)


def _run_model(magnitude, variance):
    return _detect_defective(magnitude, variance)


def _log_result(defective):
    print("DEFECTIVE" if defective else "PASS")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = smbus.SMBus(1)
    except OSError as exc:
        logger.error("Cannot open I2C bus 1: %s", exc)
        sys.exit(1)

    try:
        _init_mpu6050(bus)
        logger.info("MPU6050 initialized on I2C bus 1.")
    except OSError as exc:
        logger.error("MPU6050 not detected on bus 1: %s", exc)
        sys.exit(1)

    process = partial(_process_samples, bus)
    predict = partial(_run_model)

    try:
        while _running:
            rms, variance = process(8)
            if rms is None:
                logger.error("Failed to read sensor data; aborting.")
                break
            defective = predict(rms, variance)
            _log_result(defective)
    except Exception as exc:
        logger.exception("Unexpected error: %s", exc)
    finally:
        try:
            bus.close()
        except Exception:
            pass
        logger.info("Resources released. Exiting.")


if __name__ == "__main__":
    main()

