import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIOZeroWarning
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17
THRESHOLD = 50
CYCLES = 5
DELAY_SECONDS = 2

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_light_level():
    return random.randint(0, 100)


def control_led(led, light_level):
    if light_level < THRESHOLD:
        led.on()
        print("LED ON: Light level below threshold")
    else:
        led.off()
        print("LED OFF: Light level above threshold")


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    led = None
    try:
        led = LED(LED_PIN)
        print(f"Simulating ambient light sensor on BCM pin {LED_PIN} for {CYCLES} cycles...")

        for i in range(CYCLES):
            if not _running:
                print("\nInterrupted by user. Exiting gracefully...")
                break

            light_level = read_light_level()
            print(f"Cycle {i + 1}/{CYCLES} - Light level: {light_level}%")
            control_led(led, light_level)

            if i < CYCLES - 1 and _running:
                time.sleep(DELAY_SECONDS)

        if _running:
            print("Simulation complete.")

    except GPIOZeroError as e:
        print(f"GPIO error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if led is not None:
            try:
                led.off()
                led.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
