import logging
import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice, DigitalOutputDevice
except ImportError:
    logging.error("gpiozero is required. Install with: pip install gpiozero")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

MOTOR_1 = 1
MOTOR_2 = 2
CLOCKWISE = 1
COUNTER_CLOCKWISE = 0
STOP = 0
PWM_FREQUENCY = 100

DUTY_CYCLE_1 = 0.75
DUTY_CYCLE_2 = 0.50
DUTY_CYCLE_1_CHANGED = 0.25
HOLD_TIME = 5


class Motor:
    """Represents a single motor on the Arduino Motor Shield."""

    def __init__(self, shield, motor_id, pwm_pin, directions):
        self.shield = shield
        self.motor_id = motor_id
        self.pwm = None
        self.directions = directions
        self.current_direction = STOP
        self.current_duty_cycle = 0.0

        try:
            self.pwm = PWMOutputDevice(pwm_pin, frequency=PWM_FREQUENCY)
            self.pwm.value = 0.0
            logging.info(
                f"Motor {motor_id} PWM initialized on pin {pwm_pin} "
                f"at {PWM_FREQUENCY} Hz."
            )
        except Exception as e:
            logging.error(f"Failed to initialize PWM for motor {motor_id}: {e}")
            raise

    def set_direction(self, direction):
        if direction not in self.directions:
            raise ValueError(f"Invalid direction: {direction}")
        if direction != self.current_direction:
            try:
                for i, d in enumerate(self.directions):
                    self.shield.shift_out(i, direction == d)
                self.current_direction = direction
                logging.info(
                    f"Motor {self.motor_id} direction set to "
                    f"{directions[self.current_direction]}."
                )
            except Exception as e:
                logging.error(
                    f"Failed to set direction for motor {self.motor_id}: {e}"
                )
                raise

    def start(self, direction=CLOCKWISE, duty_cycle=0.0):
        if duty_cycle < 0 or duty_cycle > 1:
            raise ValueError("Duty cycle must be between 0 and 1.")
        self.set_direction(direction)
        self.change_duty_cycle(duty_cycle)
        logging.info(
            f"Motor {self.motor_id} started in "
            f"{directions[direction]} direction at {duty_cycle * 100:.0f}%."
        )

    def stop(self):
        if self.pwm is not None:
            try:
                self.pwm.value = 0.0
                logging.info(f"Motor {self.motor_id} stopped.")
            except Exception as e:
                logging.error(f"Failed to stop motor {self.motor_id}: {e}")
                raise

    def change_duty_cycle(self, duty_cycle):
        if duty_cycle < 0 or duty_cycle > 1:
            raise ValueError("Duty cycle must be between 0 and 1.")
        if duty_cycle != self.current_duty_cycle:
            try:
                self.pwm.value = duty_cycle
                self.current_duty_cycle = duty_cycle
                logging.info(
                    f"Motor {self.motor_id} duty cycle changed to "
                    f"{duty_cycle * 100:.0f}%."
                )
            except Exception as e:
                logging.error(
                    f"Failed to change duty cycle for motor {self.motor_id}: {e}"
                )
                raise

    def stop_all(self):
        self.stop()

    def close(self):
        if self.pwm is not None:
            try:
                self.pwm.close()
            except Exception as e:
                logging.error(f"Error closing PWM for motor {self.motor_id}: {e}")


class MotorShield:
    """Manages motors and the 74HC595 shift register for the Arduino Motor Shield."""

    def __init__(self, latch_pin, clock_pin, data_pin):
        self.latch = DigitalOutputDevice(latch_pin)
        self.clock = DigitalOutputDevice(clock_pin)
        self.data = DigitalOutputDevice(data_pin)
        self.motors = {}
        self.directions = [STOP, self.directions[0], self.directions[1]]
        self._initialized = False

    def shift_out(self, value, direction):
        self.latch.off()
        for i in range(8):
            self.clock.off()
            bit = (value >> i) & 1
            if direction == self.directions[bit]:
                self.data.on()
            else:
                self.data.off()
            self.clock.on()
        self.latch.on()

    def add_motor(self, motor_id, pwm_pin):
        if motor_id not in (MOTOR_1, MOTOR_2):
            raise ValueError("Invalid motor ID. Must be MOTOR_1 or MOTOR_2.")
        if motor_id in self.motors:
            raise ValueError(f"Motor {motor_id} already exists.")
        motor = Motor(self, motor_id, pwm_pin, self.directions)
        self.motors[motor_id] = motor
        logging.info(f"Motor {motor_id} added to shield.")
        return motor

    def start_motor(self, motor_id, direction=CLOCKWISE, duty_cycle=0.0):
        if motor_id not in self.motors:
            raise ValueError(f"Motor {motor_id} not found.")
        self.motors[motor_id].start(direction, duty_cycle)

    def stop_motor(self, motor_id):
        if motor_id not in self.motors:
            raise ValueError(f"Motor {motor_id} not found.")
        self.motors[motor_id].stop()

    def change_duty_cycle(self, motor_id, duty_cycle):
        if motor_id not in self.motors:
            raise ValueError(f"Motor {motor_id} not found.")
        self.motors[motor_id].change_duty_cycle(duty_cycle)

    def stop_all_motors(self):
        for motor_id, motor in self.motors.items():
            motor.stop_all()

    def close(self):
        self.stop_all_motors()
        for motor in self.motors.values():
            motor.close()
        for dev in (self.latch, self.clock, self.data):
            try:
                dev.close()
            except Exception:
                pass
        logging.info("Motor shield resources released.")


class MotorShieldContext:
    """Context manager for MotorShield ensuring cleanup on exit."""

    def __init__(self, latch_pin, clock_pin, data_pin):
        self.latch_pin = latch_pin
        self.clock_pin = clock_pin
        self.data_pin = data_pin
        self.shield = None

    def __enter__(self):
        self.shield = MotorShield(self.latch_pin, self.clock_pin, self.data_pin)
        return self.shield

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.shield is not None:
            self.shield.close()
            self.shield = None
        return False


directions = {
    STOP: "STOP",
    CLOCKWISE: "CLOCKWISE",
    COUNTER_CLOCKWISE: "COUNTER_CLOCKWISE",
}


def main():
    shield = None
    try:
        with MotorShieldContext(latch_pin=11, clock_pin=9, data_pin=10) as shield:
            motor1 = shield.add_motor(MOTOR_1, 13)
            motor2 = shield.add_motor(MOTOR_2, 12)

            shield.start_motor(MOTOR_1, CLOCKWISE, DUTY_CYCLE_1)
            shield.start_motor(MOTOR_2, COUNTER_CLOCKWISE, DUTY_CYCLE_2)
            logging.info(f"Holding motors for {HOLD_TIME} seconds.")
            time.sleep(HOLD_TIME)

            shield.change_duty_cycle(MOTOR_1, DUTY_CYCLE_1_CHANGED)
            logging.info("Duty cycle changed for Motor 1.")

            shield.stop_all_motors()
            logging.info("All motors stopped.")

    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if shield is not None:
            shield.close()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, lambda s, f: sys.exit(0))
    signal.signal(signal.SIGTERM, lambda s, f: sys.exit(0))
    main()

