#!/usr/bin/python3
"""
Raspberry Pi driver for the Adafruit DC Motor HAT (PCA9685-based).

Wiring:
  - Motor HAT VIN  -> Pi 5 V (Pin 2)
  - Motor HAT GND  -> Pi GND (Pin 6)
  - Motor HAT SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
  - Motor HAT SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
  - Motor HAT I2C  -> 0x60 (default)

Dependencies:
  pip install adafruit-circuitpython-motorkit adafruit-circuitpython-busdevice

Requires a Raspberry Pi with I2C enabled (raspi-config -> Interfacing Options ->
  I2C).  The driver is tested on a Raspberry Pi 5 with a standard 48 V DC motor
  driver board.
"""

import atexit
import signal
import sys
import time

import board
import busio
import adafruit_motorkit


class DCMotorHATExtra(adafruit_motorkit.MotorHAT):
    """MotorHAT with extra methods for configurable motor control."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._last_duty_cycle = 0
        self._last_frequency = 60

    def set_pwm_freq(self, freq):
        """Set the PWM frequency (Hz) for all motors."""
        if not 1 <= freq <= 1000:
            raise ValueError("PWM frequency must be between 1 and 1000 Hz")
        self._last_frequency = freq
        try:
            self._driver.frequency = freq
        except Exception as exc:
            raise RuntimeError(f"Failed to set PWM frequency to {freq} Hz: {exc}") from exc

    def get_pwm_freq(self):
        """Return the last configured PWM frequency (Hz)."""
        return self._last_frequency

    def set_dc(self, motor_num, duty_cycle, invert=False):
        """
        Set the duty cycle for a single DC motor.

        duty_cycle: -255 to 255
        invert:     True to invert direction (sign of duty_cycle)
        """
        if not 1 <= motor_num <= 4:
            raise ValueError("Motor number must be between 1 and 4")
        if not -255 <= duty_cycle <= 255:
            raise ValueError("Duty cycle must be between -255 and 255")

        motor = getattr(self, f"motor{motor_num}", None)
        if motor is None:
            raise ValueError(f"Motor {motor_num} does not exist")

        if duty_cycle == self._last_duty_cycle:
            return

        if invert:
            duty_cycle = -duty_cycle

        try:
            motor.throttle = duty_cycle / 255.0
            self._last_duty_cycle = duty_cycle
        except Exception as exc:
            raise RuntimeError(f"Failed to set duty cycle for motor {motor_num}: {exc}") from exc

    def stop(self, motor_num):
        """Stop a single DC motor by setting duty cycle to 0."""
        self.set_dc(motor_num, 0)


class DCMotor:
    """Single DC motor wrapper with configurable speed and direction."""

    def __init__(self, motor_hat, motor_num, frequency=60, invert=False):
        if not 1 <= motor_num <= 4:
            raise ValueError("Motor number must be between 1 and 4")
        if not 1 <= frequency <= 1000:
            raise ValueError("PWM frequency must be between 1 and 1000 Hz")

        self.motor_hat = motor_hat
        self.motor_num = motor_num
        self.invert = invert
        self._last_duty_cycle = 0

        self.motor_hat.set_pwm_freq(frequency)
        self.motor_hat.set_dc(motor_num, 0, invert)

    def set_dc(self, duty_cycle):
        """Set the motor duty cycle, clamping to -255..255 and respecting invert."""
        if not -255 <= duty_cycle <= 255:
            raise ValueError("Duty cycle must be between -255 and 255")

        if duty_cycle == self._last_duty_cycle:
            return

        if self.invert:
            duty_cycle = -duty_cycle

        self.motor_hat.set_dc(self.motor_num, duty_cycle, self.invert)
        self._last_duty_cycle = duty_cycle

    def get_status(self):
        """Return the motor number, current frequency, invert flag, and last duty cycle."""
        return {
            "motor_num": self.motor_num,
            "frequency": self.motor_hat.get_pwm_freq(),
            "invert": self.invert,
            "last_duty_cycle": self._last_duty_cycle,
        }

    def stop(self):
        """Stop the motor by setting duty cycle to 0."""
        self.motor_hat.stop(self.motor_num)


def _cleanup(motor_hat):
    """Stop all motors and close the I2C interface."""
    if motor_hat is None:
        return
    for i in range(1, 5):
        try:
            motor_hat.stop(i)
        except Exception:
            pass
    try:
        motor_hat.close()
    except Exception:
        pass


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    sys.exit(0)


def main():
    motor_hat = None
    try:
        # Initialize I2C bus 1 (GPIO2 / SDA, GPIO3 / SCL)
        i2c = busio.I2C(board.SCL, board.SDA)

        # Initialize the Motor HAT at the default I2C address (0x60)
        motor_hat = DCMotorHATExtra(i2c=i2c, address=0x60)

        # Register cleanup at exit
        atexit.register(_cleanup, motor_hat)

        # Register signal handlers for clean shutdown
        signal.signal(signal.SIGINT, _signal_handler)
        signal.signal(signal.SIGTERM, _signal_handler)

        # Verify I2C communication by reading the driver version
        try:
            _ = motor_hat._driver.version
        except Exception as exc:
            print(f"Error: Failed to communicate with Motor HAT at 0x60: {exc}")
            sys.exit(1)

        # Create a DC motor on motor number 1
        motor = DCMotor(motor_hat, 1, frequency=60, invert=False)

        print("Ramping motor 1 forward...")
        for dc in range(0, 256, 10):
            motor.set_dc(dc)
            time.sleep(0.05)

        print("Ramping motor 1 backward...")
        for dc in range(0, -256, -10):
            motor.set_dc(dc)
            time.sleep(0.05)

        print("Stopping motor 1...")
        motor.stop()

    except Exception as exc:
        print(f"Error: {exc}")
        if motor_hat is not None:
            _cleanup(motor_hat)
        sys.exit(1)


if __name__ == "__main__":
    main()

