        if not 1 <= motor_num <= 4:
            raise ValueError("Motor number must be between 1 and 4")
        if not -255 <= duty_cycle <= 255:
            raise ValueError("Duty cycle must be between -255 and 255")

        motor = getattr(self, f"motor{motor_num}", None)
        if motor is None:
            raise ValueError(f"Motor {motor_num} does not exist")

        if duty_cycle == self._last_duty_cycle:
            return

        if invert:
            duty_cycle = -duty_cycle

        try:
            motor.throttle = duty_cycle / 255.0
            self._last_duty_cycle = duty_cycle
        except Exception as exc:
            raise RuntimeError(f"Failed to set duty cycle for motor {motor_num}: {exc}") from exc

    def stop(self, motor_num):
