        self.set_dc(motor_num, 0)


class DCMotor:
    """Single DC motor wrapper with configurable speed and direction."""

    def __init__(self, motor_hat, motor_num, frequency=60, invert=False):
        if not 1 <= motor_num <= 4:
            raise ValueError("Motor number must be between 1 and 4")
        if not 1 <= frequency <= 1000:
            raise ValueError("PWM frequency must be between 1 and 1000 Hz")

        self.motor_hat = motor_hat
        self.motor_num = motor_num
        self.invert = invert
        self._last_duty_cycle = 0

        self.motor_hat.set_pwm_freq(frequency)
        self.motor_hat.set_dc(motor_num, 0, invert)

    def set_dc(self, duty_cycle):
        """Set the motor duty cycle, clamping to -255..255 and respecting invert."""
        if not -255 <= duty_cycle <= 255:
            raise ValueError("Duty cycle must be between -255 and 255")

        if duty_cycle == self._last_duty_cycle:
            return

        if self.invert:
            duty_cycle = -duty_cycle

        self.motor_hat.set_dc(self.motor_num, duty_cycle, self.invert)
        self._last_duty_cycle = duty_cycle

    def get_status(self):
        """Return the motor number, current frequency, invert flag, and last duty cycle."""
        return {
            "motor_num": self.motor_num,
            "frequency": self.motor_hat.get_pwm_freq(),
            "invert": self.invert,
            "last_duty_cycle": self._last_duty_cycle,
        }

