    print(f"\nReceived signal {signum}, shutting down...")
    sys.exit(0)


def main():
    motor_hat = None
    try:
        # Initialize I2C bus 1 (GPIO2 / SDA, GPIO3 / SCL)
        i2c = busio.I2C(board.SCL, board.SDA)

        # Initialize the Motor HAT at the default I2C address (0x60)
        motor_hat = DCMotorHATExtra(i2c=i2c, address=0x60)

        # Register cleanup at exit
        atexit.register(_cleanup, motor_hat)

        # Register signal handlers for clean shutdown
        signal.signal(signal.SIGINT, _signal_handler)
        signal.signal(signal.SIGTERM, _signal_handler)

        # Verify I2C communication by reading the driver version
        try:
            _ = motor_hat._driver.version
        except Exception as exc:
            print(f"Error: Failed to communicate with Motor HAT at 0x60: {exc}")
            sys.exit(1)

