        for dc in range(0, -256, -10):
            motor.set_dc(dc)
            time.sleep(0.05)

        print("Stopping motor 1...")
        motor.stop()

    except Exception as exc:
        print(f"Error: {exc}")
        if motor_hat is not None:
            _cleanup(motor_hat)
        sys.exit(1)


