_PWM_FREQUENCY = 50


class ServoController:
    """Controls a servo motor via RPi.GPIO using the hardware PWM API."""

    def __init__(self, pin, frequency=_PWM_FREQUENCY):
        if not _GPIO_AVAILABLE:
