            raise ValueError(f"Invalid frequency: {frequency!r}")

        self._pin = pin
        self._frequency = frequency
        self._pwm = None
        self._initialized = False

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self._pin, GPIO.OUT)
            self._pwm = GPIO.PWM(self._pin, self._frequency)
            self._pwm.start(0)
            self._initialized = True
            logging.info(
                "ServoController initialized on BCM pin %d at %d Hz.",
                self._pin,
                self._frequency,
            )
        except Exception as exc:
            self._cleanup()
            raise RuntimeError(f"Failed to initialize PWM on pin {self._pin}: {exc}") from exc

