        except Exception as exc:
            logging.error("Error moving servo to angle %s: %s", angle, exc)
            raise

    def stop(self):
        """Stop the servo PWM signal and release resources."""
        if self._pwm is not None:
            try:
                self._pwm.stop()
            except Exception as exc:
                logging.warning("Error stopping PWM: %s", exc)
            finally:
                self._pwm = None
        self._initialized = False
        logging.info("Servo stopped.")

    def _cleanup(self):
        """Best-effort cleanup of any partial state."""
        if self._pwm is not None:
            try:
                self._pwm.stop()
            except Exception:
                pass
            self._pwm = None
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception as exc:
                logging.warning("Error during GPIO cleanup: %s", exc)

    def _angle_to_duty_cycle(self, angle):
        """Convert a servo angle (0-180) to a PWM duty cycle percentage."""
        if not (0 <= angle <= 180):
            raise ValueError(f"Angle {angle} out of range for duty-cycle calculation.")
        return (angle / 18.0) + 2.5


