        'Register': 0x0006,
        'functioncode': 6,
    },
    'TorqueLimit': {
        'R/W': 'W',
        'Register': 0x0008,
        'functioncode': 6,
    },
    'Enable': {
        'R/W': 'W',
        'Register': 0x000A,
        'functioncode': 6,
    },
}


def main() -> None:
    servo_controller = ServoController(
        modbus_client=ModbusRTU(port='/dev/serial0', baudrate=115200, timeout=1.0, retries=3),
        register_map=SERVO_REGISTER_MAP,
    )

    def signal_handler(signum, frame):
        logger.info('Signal %d received, shutting down...', signum)
        servo_controller.modbus_client.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        if not servo_controller.modbus_client.connect():
            logger.error('Failed to connect to servo controller; exiting')
            return

        # Example: read position register
        position = servo_controller.read_servo_registers('Position')
        if position:
            logger.info('Position: %s', position['Value'])
        else:
            logger.warning('Failed to read position')

        # Example: write target position
        result = servo_controller.write_servo_register('TargetPosition', 1000)
        if result:
            logger.info('TargetPosition written successfully')
        else:
            logger.warning('Failed to write target position')

        # Example: write torque limit (multiple registers)
        values = [100, 200]
        result = servo_controller.write_multiple_servo_registers('TorqueLimit', values)
        if result:
            logger.info('TorqueLimit written successfully')
        else:
            logger.warning('Failed to write torque limit')

    except Exception as exc:
        logger.error('Runtime error: %s', exc)
    finally:
        servo_controller.modbus_client.close()


if __name__ == '__main__':
    main()

