import time
import logging
import signal
import sys
import atexit

try:
    from automationhat import relay, input as automationhat_input
except ImportError:
    logging.error("The 'automationhat' library is not installed or the Automation HAT is not connected.")
    sys.exit(0)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DOOR_CLOSED = 1
DOOR_OPEN = 0
RELAY_ON_DURATION = 0.5
STATE_PIN = 1

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    try:
        relay.one.off()
        logging.info("Relay turned OFF during cleanup.")
    except Exception as e:
        logging.error(f"Error turning off relay during cleanup: {e}")


class GarageDoor:
    def __init__(self, state_pin=STATE_PIN, relay_one=1):
        self.state_pin = state_pin
        self.relay_one = relay_one
        self._closed = None
        self._open = None
        self._initialize_hardware()

    def _initialize_hardware(self):
        try:
            if not relay.connected():
                raise RuntimeError("Automation HAT driver not connected or hardware not detected.")
            relay.one.off()
            logging.info("Automation HAT initialized and relay one set to OFF.")
        except Exception as e:
            logging.error(f"Error initializing Automation HAT: {e}")
            raise

    def read_state(self):
        try:
            value = automationhat_input[self.state_pin].read()
            if value is None:
                raise RuntimeError("Failed to read state: input returned None.")
            if not isinstance(value, int):
                raise RuntimeError(f"Unexpected input type: {type(value).__name__}")
            if value not in (DOOR_CLOSED, DOOR_OPEN):
                raise RuntimeError(f"Invalid state value: {value}")
            return value
        except Exception as e:
            logging.error(f"Error reading state: {e}")
            return None

    def is_closed(self):
        if self._closed is None:
            self._closed = self.read_state() == DOOR_CLOSED
        return self._closed

    def is_open(self):
        if self._open is None:
            self._open = self.read_state() == DOOR_OPEN
        return self._open

    def open_door(self):
        if self.is_open():
            logging.info("Garage door is already open.")
            return
        try:
            relay.one.on()
            logging.info("Opening garage door...")
            time.sleep(RELAY_ON_DURATION)
            relay.one.off()
            self._closed = False
            self._open = True
            logging.info("Garage door opened.")
        except Exception as e:
            logging.error(f"Error opening garage door: {e}")
            self._cleanup_relay()

    def close_door(self):
        if self.is_closed():
            logging.info("Garage door is already closed.")
            return
        try:
            relay.one.on()
            logging.info("Closing garage door...")
            time.sleep(RELAY_ON_DURATION)
            relay.one.off()
            self._closed = True
            self._open = False
            logging.info("Garage door closed.")
        except Exception as e:
            logging.error(f"Error closing garage door: {e}")
            self._cleanup_relay()

    def _cleanup_relay(self):
        try:
            relay.one.off()
            logging.info("Relay turned OFF during error handling.")
        except Exception as e:
            logging.error(f"Error turning off relay during cleanup: {e}")


My_Garage = GarageDoor()


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    atexit.register(_cleanup)

    try:
        while _running:
            if My_Garage.is_closed():
                My_Garage.open_door()
            elif My_Garage.is_open():
                My_Garage.close_door()
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

