import signal
import sys
import time
from smbus2 import SMBus, i2c_msg

# PCA9685 constants
I2C_BUS = 1
PCA9685_ADDRESS = 0x40
MODE1_REG = 0x00
PRESCALE_REG = 0xFE
LED0_ON_L_REG = 0x06
PWM_FREQUENCY = 60

# Global state for cleanup
_pwm = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    """Write a single byte to a register with error handling."""
    try:
        bus.write_byte_data(PCA9685_ADDRESS, reg, value)
    except OSError as e:
        raise RuntimeError(f"I2C write failed at register 0x{reg:02X}: {e}") from e


def _read_reg(bus, reg):
    """Read a single byte from a register with error handling."""
    try:
        return bus.read_byte_data(PCA9685_ADDRESS, reg)
    except OSError as e:
        raise RuntimeError(f"I2C read failed at register 0x{reg:02X}: {e}") from e


def _read_mode1(bus):
    """Read the MODE1 register."""
    return _read_reg(bus, MODE1_REG)


def _write_mode1(bus, value):
    """Write to the MODE1 register."""
    _write_reg(bus, MODE1_REG, value)


def _read_prescale(bus):
    """Read the PRESCALE register."""
    return _read_reg(bus, PRESCALE_REG)


def _write_prescale(bus, value):
    """Write to the PRESCALE register."""
    _write_reg(bus, PRESCALE_REG, value)


def _read_channel_on_l(bus, channel):
    """Read the ON_L register for a channel (16-bit, big-endian)."""
    reg = LED0_ON_L_REG + 4 * channel
    return _read_reg(bus, reg)


def _write_channel_on_l(bus, channel, value):
    """Write to the ON_L register for a channel."""
    reg = LED0_ON_L_REG + 4 * channel
    _write_reg(bus, reg, value)


def _write_channel_on_h(bus, channel, value):
    """Write to the ON_H register for a channel."""
    reg = LED0_ON_L_REG + 4 * channel + 1
    _write_reg(bus, reg, value)


def _write_channel_off_l(bus, channel, value):
    """Write to the OFF_L register for a channel."""
    reg = LED0_ON_L_REG + 4 * channel + 2
    _write_reg(bus, reg, value)


def _write_channel_off_h(bus, channel, value):
    """Write to the OFF_H register for a channel."""
    reg = LED0_ON_L_REG + 4 * channel + 3
    _write_reg(bus, reg, value)


def _set_pwm_frequency(bus, freq):
    """Set the PWM frequency on the PCA9685."""
    if freq < 24 or freq > 1526:
        raise ValueError(f"PWM frequency {freq} Hz out of range (24-1526 Hz)")

    prescale = int(round(25e6 / (4096 * freq)) - 1)
    prescale = max(3, min(255, prescale))

    old_mode = _read_mode1(bus)
    _write_mode1(bus, (old_mode & 0x7F) | 0x10)  # sleep
    _write_prescale(bus, prescale)
    _write_mode1(bus, old_mode)
    time.sleep(0.005)
    _write_mode1(bus, old_mode | 0x80)  # restart


def _set_pwm_channel(bus, channel, on, off):
    """Set PWM on/off ticks for a single channel."""
    if not 0 <= channel <= 15:
        raise ValueError(f"Channel {channel} out of range (0-15)")
    if not 0 <= on <= 4095:
        raise ValueError(f"ON {on} out of range (0-4095)")
    if not 0 <= off <= 4095:
        raise ValueError(f"OFF {off} out of range (0-4095)")

    _write_channel_on_l(bus, channel, on & 0xFF)
    _write_channel_on_h(bus, channel, on >> 8)
    _write_channel_off_l(bus, channel, off & 0xFF)
    _write_channel_off_h(bus, channel, off >> 8)


def _set_servo_angle(bus, channel, angle):
    """Set a servo to a given angle (-77 to +77 degrees)."""
    if not -77 <= angle <= 77:
        raise ValueError(f"Angle {angle} out of range (-77 to 77)")

    pulse_width = 1000 + (angle * 20)
    pulse_width_ticks = int(round(pulse_width * 4096 / 20000))
    _set_pwm_channel(bus, channel, 0, pulse_width_ticks)


def _cleanup(bus):
    """Turn off all PWM channels and release resources."""
    if bus is not None:
        try:
            for ch in range(16):
                _set_pwm_channel(bus, ch, 0, 0)
            time.sleep(0.5)
        except Exception:
            pass
        try:
            bus.close()
        except Exception:
            pass


def main():
    global _pwm

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _pwm = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Verify device presence by reading MODE1
        _read_mode1(_pwm)

        # Set PWM frequency
        _set_pwm_frequency(_pwm, PWM_FREQUENCY)

        # Move to -77 degrees
        _set_servo_angle(_pwm, 0, -77)
        _set_servo_angle(_pwm, 1, -77)
        time.sleep(0.25)

        # Move to +77 degrees
        _set_servo_angle(_pwm, 0, 77)
        _set_servo_angle(_pwm, 1, 77)
        time.sleep(0.25)

        # Return to 0 degrees
        _set_servo_angle(_pwm, 0, 0)
        _set_servo_angle(_pwm, 1, 0)
        time.sleep(0.25)

    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        _cleanup(_pwm)
        _pwm = None


if __name__ == "__main__":
    main()

