import signal
import sys
from datetime import datetime

try:
    import smbus2 as smbus
except ImportError:
    import smbus

# ── Constants ──────────────────────────────────────────────────────────────
I2C_BUS = 1
DS1338_ADDR = 0x68
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07

# ── BCD helpers ────────────────────────────────────────────────────────────
def bcd_to_int(bcd: int) -> int:
    """Convert a two-digit BCD byte to an integer (0-99)."""
    return (bcd >> 4) * 10 + (bcd & 0x0F)

def int_to_bcd(n: int) -> int:
    """Convert an integer (0-99) to a two-digit BCD byte."""
    if not 0 <= n <= 99:
        raise ValueError(f"Value {n} out of BCD range 0-99")
    return (n // 10 << 4) | (n % 10)

# ── DS1338 register helpers ────────────────────────────────────────────────
def _read_reg(bus: smbus.SMBus, reg: int) -> int:
    """Read a single byte from a register; raise OSError on failure."""
    return bus.read_byte_data(DS1338_ADDR, reg)

def _write_reg(bus: smbus.SMBus, reg: int, value: int) -> None:
    """Write a single byte to a register; raise OSError on failure."""
    bus.write_byte_data(DS1338_ADDR, reg, value)

def _read_all_regs(bus: smbus.SMBus) -> list:
    """Read all 7 registers in one I2C transaction."""
    return bus.read_i2c_block_data(DS1338_ADDR, REG_SECONDS, 7)

def _write_all_regs(bus: smbus.SMBus, values: list) -> None:
    """Write all 7 registers in one I2C transaction."""
    bus.write_i2c_block_data(DS1338_ADDR, REG_SECONDS, values)

# ── Public API ─────────────────────────────────────────────────────────────
class DS1338:
    """Full register read/write interface for the DS1338 RTC chip."""

    def __init__(self, bus_num: int = I2C_BUS):
        self.bus_num = bus_num
        self.bus = None
        try:
            self.bus = smbus.SMBus(bus_num)
        except OSError as exc:
            raise OSError(
                f"Cannot open I2C bus {bus_num}: {exc}"
            ) from exc

        # Probe the device with a zero-length write to confirm presence.
        try:
            self.bus.write_byte(DS1338_ADDR, 0x00)
        except OSError as exc:
            self.close()
            raise OSError(
                f"No DS1338 found at address 0x{DS1338_ADDR:02X} on bus {bus_num}: {exc}"
            ) from exc

    def close(self) -> None:
        """Release the I2C bus handle."""
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            finally:
                self.bus = None

    def _read_reg(self, reg: int) -> int:
        return _read_reg(self.bus, reg)

    def _write_reg(self, reg: int, value: int) -> None:
        _write_reg(self.bus, reg, value)

    def _read_all_regs(self) -> list:
        return _read_all_regs(self.bus)

    def _write_all_regs(self, values: list) -> None:
        _write_all_regs(self.bus, values)

    # ── Time helpers ───────────────────────────────────────────────────────
    @staticmethod
    def _validate_range(value: int, lo: int, hi: int) -> None:
        if not lo <= value <= hi:
            raise ValueError(
                f"Value {value} out of range [{lo}, {hi}]"
            )

    @staticmethod
    def _validate_datetime(year: int, month: int, day: int,
                           hour: int, minute: int, second: int) -> None:
        DS1338._validate_range(year, 0, 99)
        DS1338._validate_range(month, 1, 12)
        DS1338._validate_range(day, 1, 31)
        DS1338._validate_range(hour, 0, 23)
        DS1338._validate_range(minute, 0, 59)
        DS1338._validate_range(second, 0, 59)

    # ── Read ────────────────────────────────────────────────────────────────
    def read_datetime(self, century: int = 21) -> datetime:
        """Read the current time and return a datetime object.

        Args:
            century: The century (20 or 21) for the year field.
        """
        data = self._read_all_regs()
        if len(data) != 7:
            raise OSError(
                f"Unexpected register block length: {len(data)}"
            )

        year = century * 100 + bcd_to_int(data[6])
        month = bcd_to_int(data[4])
        day = bcd_to_int(data[3])
        hour = bcd_to_int(data[2]) & 0x3F  # mask bit 6 (12/24 hr)
        minute = bcd_to_int(data[1])
        second = bcd_to_int(data[0])

        self._validate_datetime(year, month, day, hour, minute, second)
        return datetime(year, month, day, hour, minute, second)

    # ── Write ───────────────────────────────────────────────────────────────
    def write_all(self, seconds: int = None, minutes: int = None,
                  hours: int = None, day: int = None,
                  date: int = None, month: int = None,
                  year: int = None) -> None:
        """Write values to all registers.

        Each argument is optional; only the fields whose value is not None
        are written.  Bit 6 of the hours register is masked when reading
        and cleared when writing, so the 24-hour format is assumed.
        """
        data = self._read_all_regs()
        if len(data) != 7:
            raise OSError(
                f"Unexpected register block length: {len(data)}"
            )

        values = list(data)

        if seconds is not None:
            self._validate_range(seconds, 0, 59)
            values[0] = int_to_bcd(seconds)
        if minutes is not None:
            self._validate_range(minutes, 0, 59)
            values[1] = int_to_bcd(minutes)
        if hours is not None:
            self._validate_range(hours, 0, 23)
            values[2] = int_to_bcd(hours) & 0x3F  # mask bit 6
        if day is not None:
            self._validate_range(day, 1, 7)
            values[3] = int_to_bcd(day)
        if date is not None:
            self._validate_range(date, 1, 31)
            values[4] = int_to_bcd(date)
        if month is not None:
            self._validate_range(month, 1, 12)
            values[5] = int_to_bcd(month)
        if year is not None:
            self._validate_range(year, 0, 99)
            values[6] = int_to_bcd(year % 100)

        self._write_all_regs(values)

# ── Signal handling ────────────────────────────────────────────────────────
_rtc: DS1338 | None = None

def _signal_handler(signum, frame):
    if _rtc is not None:
        _rtc.close()
    sys.exit(0)

def main() -> None:
    global _rtc
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _rtc = DS1338()
        print("DS1338 initialized on I2C bus 1 (address 0x68).")

        # Read current time and print it.
        now = _rtc.read_datetime(century=21)
        print(f"Current RTC time: {now.isoformat()}")

        # Set the time to 14:30:00 on 2024-01-01.
        _rtc.write_all(
            seconds=0, minutes=30, hours=14,
            day=1, date=1, month=1, year=23
        )
        print("Time set to 14:30:00 on 2024-01-01.")

    except OSError as exc:
        print(f"I2C error: {exc}", file=sys.stderr)
    except ValueError as exc:
        print(f"Value error: {exc}", file=sys.stderr)
    finally:
        if _rtc is not None:
            _rtc.close()

if __name__ == "__main__":
    main()

