import threading
import time

from gpiozero import DigitalOutputDevice
from spidev import SpiDev

# Constants
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1_000_000
SPI_MODE = 0
SPI_BITS_PER_WORD = 8
EEPROM_SIZE = 4096
EEPROM_ADDR = 0
EEPROM_DATA = b"1234567890ABCDEF"
CS_PIN = 5


class EEPROM:
    """Thread-safe SPI EEPROM driver for a 4-Kb SPI EEPROM (e.g. 25LC040)."""

    def __init__(self, spi_bus, spi_device, cs_pin):
        self.spi = SpiDev()
        self.cs = DigitalOutputDevice(cs_pin, active_high=False, initial_value=True)
        self.spi.open(spi_bus, spi_device)
        self.spi.max_speed_hz = SPI_MAX_SPEED_HZ
        self.spi.mode = SPI_MODE
        self.spi.bits_per_word = SPI_BITS_PER_WORD
        self.lock = threading.Lock()
        self._closed = False

    def _write_byte(self, addr, data):
        with self.lock:
            self.cs.off()
            try:
                self.spi.xfer2([addr >> 8, addr & 0xFF, data])
            finally:
                self.cs.on()

    def _read_byte(self, addr):
        with self.lock:
            self.cs.off()
            try:
                return self.spi.xfer2([addr >> 8, addr & 0xFF, 0x00])[2]
            finally:
                self.cs.on()

    def write(self, addr, data):
        if self._closed:
            raise RuntimeError("EEPROM is closed")
        if not isinstance(data, bytes) or len(data) != 1:
            raise ValueError("data must be a single byte")
        self._write_byte(addr, data)

    def read(self, addr, length=1):
        if self._closed:
            raise RuntimeError("EEPROM is closed")
        if length <= 0:
            raise ValueError("length must be positive")
        with self.lock:
            self.cs.off()
            try:
                return self.spi.xfer2([addr >> 8, addr & 0xFF] + [0x00] * length)[2:]
            finally:
                self.cs.on()

    def close(self):
        if self._closed:
            return
        self._closed = True
        try:
            self.spi.close()
        except Exception:
            pass
        try:
            self.cs.close()
        except Exception:
            pass


def write_thread_func(eeprom, addr, data):
    eeprom.write(addr, data)


def read_thread_func(eeprom, addr, length=1):
    return eeprom.read(addr, length)


def main():
    eeprom = None
    spi = None
    cs = None

    def cleanup(signum=None, frame=None):
        nonlocal eeprom, spi, cs
        if eeprom is not None:
            try:
                eeprom.close()
            except Exception:
                pass
        if spi is not None:
            try:
                spi.close()
            except Exception:
                pass
        if cs is not None:
            try:
                cs.close()
            except Exception:
                pass
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        spi = SpiDev()
        cs = DigitalOutputDevice(CS_PIN, active_high=False, initial_value=True)
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = SPI_MODE
        spi.bits_per_word = SPI_BITS_PER_WORD
        eeprom = EEPROM(SPI_BUS, SPI_DEVICE, CS_PIN)
    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        print("Writing data...")
        t1 = threading.Thread(target=write_thread_func, args=(eeprom, EEPROM_ADDR, EEPROM_DATA), daemon=True)
        t1.start()
        t1.join()
        print("Write complete.")

        print("Reading data...")
        t2 = threading.Thread(target=read_thread_func, args=(eeprom, EEPROM_ADDR, len(EEPROM_DATA)), daemon=True)
        t2.start()
        t2.join()
        read_data = t2.join()
        print(f"Read data: {read_data}")

        if read_data == EEPROM_DATA:
            print("Verification successful.")
        else:
            print("Verification failed.")
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

