# co2_sensor_logging_rpi.py
# Reads a serial CO2 sensor on /dev/ttyUSB0 at 9600 baud on a Raspberry Pi Zero W,
# samples every 5 seconds, logs ppm values to co2_readings_log.txt, and handles
# errors and clean shutdown on SIGINT / SIGTERM.

import signal
import sys
import time
from datetime import datetime

import serial

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1          # seconds
SAMPLE_INTERVAL = 5       # seconds
LOG_FILE = 'co2_readings_log.txt'

_running = True


def _handle_signal(signum, frame):
    """Flag the main loop to exit cleanly on SIGINT / SIGTERM."""
    global _running
    _running = False


def initialize_serial(port, baud, timeout):
    """Open and return a serial port, or None on failure."""
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        if not ser.is_open:
            print(f"Error: serial port {port} did not open.")
            return None
        print(f"Serial port {port} opened at {baud} baud.")
        return ser
    except serial.SerialException as exc:
        print(f"Error opening serial port {port}: {exc}")
        return None
    except OSError as exc:
        print(f"OS error opening serial port {port}: {exc}")
        return None


def read_co2_data(serial_port):
    """Read one line from the serial port and return it as a stripped str, or None."""
    try:
        raw = serial_port.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}")
        return None
    except OSError as exc:
        print(f"OS read error: {exc}")
        return None

    if not raw:
        return None

    try:
        data = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}")
        return None

    return data if data else None


def process_co2_data(data):
    """Convert the CO2 data string to an integer ppm value, or None on error."""
    if not data:
        return None
    try:
        return int(data)
    except ValueError:
        print(f"Invalid data received (not an integer): '{data}'")
        return None


def log_co2_reading(reading, log_file):
    """Append a timestamped CO2 reading to the log file, or raise IOError."""
    timestamp = datetime.now().isoformat(timespec='seconds')
    line = f"{timestamp} - CO2 Concentration: {reading} ppm\n"
    try:
        with open(log_file, 'a', encoding='utf-8') as fh:
            fh.write(line)
    except OSError as exc:
        print(f"Error writing to log file '{log_file}': {exc}")
        raise


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial communication. Exiting.")
        sys.exit(1)

    try:
        while _running:
            co2_reading = read_co2_data(serial_connection)
            if co2_reading is not None:
                ppm_value = process_co2_data(co2_reading)
                if ppm_value is not None:
                    print(f"CO2 Concentration: {ppm_value} ppm")
                    try:
                        log_co2_reading(ppm_value, LOG_FILE)
                    except OSError:
                        pass
            else:
                print("No data received from sensor.")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < SAMPLE_INTERVAL:
                time.sleep(0.1)
                slept += 0.1
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

