import time
import signal
import sys

ESP_OK = b"OK"
ESP_ERROR = b"ERROR"
ESP_FAIL = b"FAIL"
ESP_BUSY = b"busy p..."
ESP_READY = b"ready"


class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self._uart = None
        try:
            self._uart = serial.Serial(
                port=port,
                baudrate=baud_rate,
                timeout=timeout,
                write_timeout=timeout
            )
        except serial.SerialException as e:
            print(f"Error opening UART port {port}: {e}")
            self._uart = None
        except Exception as e:
            print(f"Unexpected error opening UART port {port}: {e}")
            self._uart = None

    def _send_command(self, command, timeout=1.0, wait_for_ok=True):
        if self._uart is None:
            print("UART not initialized; cannot send command.")
            return None
        try:
            self._uart.reset_input_buffer()
            self._uart.write(command)
            time.sleep(0.01)
            response = bytearray()
            deadline = time.monotonic() + timeout
            while time.monotonic() < deadline:
                if self._uart.in_waiting > 0:
                    chunk = self._uart.read(self._uart.in_waiting)
                    if chunk:
                        response.extend(chunk)
                else:
                    time.sleep(0.01)
            if response:
                decoded = b"".join(chr(c) if 32 <= c <= 126 else " " for c in response).strip()
                print(f"Command: {command!r} | Response: {decoded!r} | Raw: {response!r}")
                if wait_for_ok and ESP_OK in response:
                    return response
                elif wait_for_ok and ESP_ERROR in response:
                    return None
                elif wait_for_ok and ESP_FAIL in response:
                    return None
                elif wait_for_ok and ESP_BUSY in response:
                    return None
                else:
                    return response
            else:
                return None
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None
        except Exception as e:
            print(f"Unexpected error sending command: {e}")
            return None

    def test_connection(self):
        return self._send_command(b"AT\r\n", timeout=1.0, wait_for_ok=True) is not None

    def restart(self):
        print("Restarting ESP8266...")
        response = self._send_command(b"AT+RST\r\n", timeout=5.0, wait_for_ok=False)
        if response is None:
            print("Failed to restart ESP8266.")
            return False
        time.sleep(2.0)
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP="{ssid}","{password}"\r\n'.encode('utf-8')
        return self._send_command(command, timeout=10.0, wait_for_ok=True) is not None

    def disconnect_wifi(self):
        return self._send_command(b"AT+CWQAP\r\n", timeout=1.0, wait_for_ok=True) is not None

    def get_ip(self):
        response = self._send_command(b"AT+CIFSR\r\n", timeout=2.0, wait_for_ok=True)
        if response is None:
            return None
        try:
            lines = response.split(b"\r\n")
            for line in lines:
                if b"STAIP" in line:
                    parts = line.split(b":")
                    if len(parts) > 1:
                        ip = parts[1].strip()
                        print(f"IP Address: {ip}")
                        return ip
        except Exception as e:
            print(f"Error parsing IP address: {e}")
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if headers is None:
            headers = []
        request = f"{method} {url} HTTP/1.1\r\n"
        request += "Host: " + host + "\r\n"
        for header in headers:
            request += header + "\r\n"
        if data:
            request += "Content-Type: application/x-www-form-urlencoded\r\n"
            request += f"Content-Length: {len(data)}\r\n"
            request += "\r\n"
            request += data
        else:
            request += "\r\n"
        request_command = f'AT+CIPSTART="TCP","{host}",{port}\r\n'.encode('utf-8')
        if self._send_command(request_command, timeout=5.0, wait_for_ok=True) is None:
            print("Failed to start TCP connection.")
            return None
        send_command = f'AT+CIPSEND={len(request)}\r\n'.encode('utf-8')
        if self._send_command(send_command, timeout=2.0, wait_for_ok=True) is None:
            print("Failed to send data length.")
            self._send_command(b"AT+CIPCLOSE\r\n", timeout=1.0)
            return None
        response = self._send_command(request.encode('utf-8'), timeout=10.0, wait_for_ok=False)
        if response is None:
            print("Failed to send HTTP request.")
            self._send_command(b"AT+CIPCLOSE\r\n", timeout=1.0)
            return None
        self._send_command(b"AT+CIPCLOSE\r\n", timeout=1.0)
        return response

    def receive_http_response(self, timeout=5.0):
        response = b""
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
