                                payload, _, _ = part.partition(b":")
                                return payload
                    if b"CLOSED" in response:
                        return None
            else:
                time.sleep(0.01)
        return response

    def close(self):
        if self._uart is not None:
            try:
                self._uart.close()
            except Exception as e:
                print(f"Error closing UART: {e}")
            finally:
                self._uart = None


def signal_handler(sig, frame):
    print("\nExiting...")
    if 'esp' in globals() and esp is not None:
