        return None
    except Exception as e:
        print(f"Unexpected error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_radiation_level(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Error: could not convert data to float: {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}", file=sys.stderr)
        return None

