import logging
import signal
import struct
import sys
import time
from dataclasses import dataclass
from typing import Optional

import serial

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

GPGGA_FORMAT = "!bHbHbbHHHh"
GPGGA_LEN = struct.calcsize(GPGGA_FORMAT)


@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    satellites: int


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.uart: Optional[serial.Serial] = None
        self._running = False

    def connect(self) -> bool:
        try:
            self.uart = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logging.info("Connected to GPS on %s at %d baud.", self.port, self.baudrate)
            return True
        except serial.SerialException as exc:
            logging.error("Failed to connect to GPS on %s: %s", self.port, exc)
            self.uart = None
            return False

    def disconnect(self) -> None:
        if self.uart is not None:
            try:
                if self.uart.is_open:
                    self.uart.close()
                    logging.info("Disconnected from GPS.")
            except serial.SerialException as exc:
                logging.error("Error while closing serial port: %s", exc)
            finally:
                self.uart = None

    def _parse_gpgga(self, sentence: str) -> Optional[GPS_readings]:
        if not sentence.startswith("$GPGGA"):
            return None

        try:
            fields = sentence.split(",")
        except AttributeError:
            logging.error("Invalid GPGGA sentence (not a string): %s", sentence)
            return None

        if len(fields) < 15:
            logging.error("Incomplete GPGGA sentence (fewer than 15 fields): %s", sentence)
            return None

        try:
            talker_id = fields[0]
            fix_quality = int(fields[6])
            num_satellites = int(fields[7])
        except ValueError as exc:
            logging.error("Numeric conversion error in GPGGA sentence: %s", exc)
            return None

        if talker_id != "GPGGA" or fix_quality == 0:
            return None

        try:
            lat_raw = fields[2]
            lat_dir = fields[3]
            lon_raw = fields[4]
            lon_dir = fields[5]
            altitude = float(fields[9])
        except (IndexError, ValueError) as exc:
            logging.error("Missing or invalid GPGGA field in sentence: %s", exc)
            return None

        if not lat_raw or not lon_raw:
            logging.error("Empty latitude or longitude in GPGGA sentence: %s", sentence)
            return None

        try:
            lat_deg = int(lat_raw[:2])
            lat_min = float(lat_raw[2:])
            lat = lat_deg + lat_min / 60.0
            if lat_dir == "S":
                lat = -lat
        except (ValueError, IndexError) as exc:
            logging.error("Invalid latitude in GPGGA sentence: %s", exc)
            return None

        try:
            lon_deg = int(lon_raw[:3])
            lon_min = float(lon_raw[3:])
            lon = lon_deg + lon_min / 60.0
            if lon_dir == "W":
                lon = -lon
        except (ValueError, IndexError) as exc:
            logging.error("Invalid longitude in GPGGA sentence: %s", exc)
            return None

        return GPS_readings(latitude=lat, longitude=lon, altitude=altitude, satellites=num_satellites)

    def read_data(self) -> Optional[GPS_readings]:
        if self.uart is None or not self.uart.is_open:
            logging.error("Serial port not open. Call connect() first.")
            return None

        try:
            raw = self.uart.readline()
        except serial.SerialException as exc:
            logging.error("Serial read error: %s", exc)
            return None

        if not raw:
            return None

        try:
            sentence = raw.decode("utf-8", errors="ignore").strip()
        except Exception as exc:
            logging.error("Decode error: %s", exc)
            return None

        return self._parse_gpgga(sentence)

    def run(self) -> None:
        if not self.connect():
            return

        self._running = True
        try:
            while self._running:
                readings = self.read_data()
                if readings is not None:
                    logging.info(
                        "GPS: lat=%.6f, lon=%.6f, alt=%.1f m, satellites=%d",
                        readings.latitude,
                        readings.longitude,
                        readings.altitude,
                        readings.satellites,
                    )
                time.sleep(0.1)
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received, exiting.")
        finally:
            self.disconnect()


def main() -> None:
    gps = GPSReader(port="/dev/serial0", baudrate=9600, timeout=1.0)

    def _signal_handler(signum, frame):
        logging.info("Signal %d received, shutting down.", signum)
        gps._running = False

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    gps.run()


if __name__ == "__main__":
    main()

