import signal
import sys
import time
import logging
from typing import Optional

try:
    import serial
except ImportError:
    logging.error("pyserial is required. Install with: pip install pyserial")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


class ESP8266:
    """Driver for an ESP8266 Wi-Fi module connected to a Raspberry Pi via UART."""

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 115200, timeout: float = 5.0):
        self._port = port
        self._baudrate = baudrate
        self._timeout = timeout
        self._uart: Optional[serial.Serial] = None
        self._closed = False
        self._install_signal_handlers()

    def _install_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._signal_handler)
            except (ValueError, OSError):
                pass

    def _signal_handler(self, signum, frame) -> None:
        logger.info("Signal %s received, shutting down.", signum)
        self.close()
        sys.exit(0)

    def _open_uart(self) -> None:
        try:
            self._uart = serial.Serial(
                port=self._port,
                baudrate=self._baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self._timeout,
                write_timeout=self._timeout,
            )
            logger.info("UART opened on %s at %d baud.", self._port, self._baudrate)
        except serial.SerialException as e:
            logger.error("Failed to open UART %s: %s", self._port, e)
            self._uart = None
            raise

    def _close_uart(self) -> None:
        if self._uart is not None and self._uart.is_open:
            try:
                self._uart.close()
                logger.info("UART closed.")
            except serial.SerialException as e:
                logger.warning("Error closing UART: %s", e)
        self._uart = None

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        self._close_uart()

    def _send_command(self, command: str, delay: float = 1.0, max_retries: int = 3) -> Optional[str]:
        if self._uart is None or not self._uart.is_open:
            logger.error("UART not initialized or closed.")
            return None

        for attempt in range(1, max_retries + 1):
            try:
                self._uart.reset_input_buffer()
                self._uart.write(command.encode("utf-8"))
                self._uart.flush()
                time.sleep(delay)
                return self._read_response()
            except serial.SerialException as e:
                logger.warning("UART write error (attempt %d/%d): %s", attempt, max_retries, e)
                if attempt < max_retries:
                    time.sleep(0.5)
            except Exception as e:
                logger.error("Unexpected error sending command: %s", e)
                return None
        logger.error("Failed to send command '%s' after %d retries.", command.strip(), max_retries)
        return None

    def _read_response(self) -> Optional[str]:
        if self._uart is None or not self._uart.is_open:
            return None

        response = b""
        deadline = time.monotonic() + self._timeout
        while time.monotonic() < deadline:
            try:
                chunk = self._uart.read(1024)
                if chunk:
                    response += chunk
                else:
                    break
            except serial.SerialException as e:
                logger.warning("UART read error: %s", e)
                return None
            except Exception as e:
                logger.error("Unexpected error reading response: %s", e)
                return None

        if not response:
            logger.warning("No response received within timeout.")
            return None

        try:
            return response.decode("utf-8", errors="ignore").strip()
        except Exception as e:
            logger.error("Failed to decode response: %s", e)
            return None

    def test_connection(self) -> bool:
        response = self._send_command("AT\r\n")
        if response is None:
            logger.error("AT test failed.")
            return False
        if "OK" in response:
            logger.info("ESP8266 responds OK.")
            return True
        logger.error("Unexpected AT response: %s", response)
        return False

    def restart(self) -> bool:
        response = self._send_command("AT+RST\r\n", delay=2.0)
        if response is None:
            logger.error("Restart failed.")
            return False
        if "OK" in response:
            logger.info("ESP8266 restarted.")
            return True
        logger.error("Restart response: %s", response)
        return False

    def connect_wifi(self, ssid: str, password: str) -> bool:
        command = f'AT+CWJAP_CUR="{ssid}","{password}"\r\n'
        response = self._send_command(command, delay=5.0)
        if response is None:
            logger.error("Wi-Fi connection failed.")
            return False
        if "WIFI GOT IP" in response:
            logger.info("Wi-Fi connected and got IP.")
            return True
        logger.error("Wi-Fi connection response: %s", response)
        return False


def main() -> None:
    esp = ESP8266(port="/dev/serial0", baudrate=115200, timeout=5.0)
    try:
        if esp.test_connection():
            if esp.connect_wifi("MySSID", "MyPassword"):
