import signal
import threading
import time
from typing import List, Optional

import serial
from flask import Flask, Response, jsonify, request

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1.0          # seconds
WEB_PORT = 5000
WEB_HOST = "0.0.0.0"

# ---------------------------------------------------------------------------
# In-memory data store (thread-safe)
# ---------------------------------------------------------------------------
data_store: List[dict] = [
    {"id": 1, "name": "Task 1", "done": False},
    {"id": 2, "name": "Task 2", "done": True},
]
data_store_lock = threading.Lock()

# ---------------------------------------------------------------------------
# UART helpers
# ---------------------------------------------------------------------------
class UartConnection:
    """Thread-safe, idempotent UART connection with per-instance state."""

    def __init__(self, port: str, baudrate: int, timeout: float):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self._uart: Optional[serial.Serial] = None
        self._lock = threading.Lock()

    def open(self) -> bool:
        """Open the serial port; return True on success."""
        with self._lock:
            if self._uart is not None and self._uart.is_open:
                return True
            try:
                self._uart = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=self.timeout,
                )
                return True
            except serial.SerialException as exc:
                self._uart = None
                print(f"[UART] Error opening {self.port}: {exc}")
                return False

    def close(self) -> None:
        """Close the serial port if open."""
        with self._lock:
            if self._uart is not None and self._uart.is_open:
                try:
                    self._uart.close()
                except serial.SerialException as exc:
                    print(f"[UART] Error closing {self.port}: {exc}")
                finally:
                    self._uart = None

    def send_command(self, command: str) -> Optional[str]:
        """Send *command* (ASCII) and return the stripped response line, or None on error/timeout."""
        with self._lock:
            if self._uart is None or not self._uart.is_open:
                print("[UART] Port not open.")
                return None
            try:
                self._uart.reset_input_buffer()
                self._uart.write(command.encode("ascii"))
                self._uart.flush()
                raw = self._uart.readline()
                if not raw:
                    print("[UART] Timeout: no response within timeout window.")
                    return None
                return raw.decode("ascii", errors="replace").strip()
            except serial.SerialException as exc:
                print(f"[UART] Error during UART communication: {exc}")
                return None

    def __enter__(self) -> "UartConnection":
        if not self.open():
            raise RuntimeError(f"Failed to open UART on {self.port}")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()


# ---------------------------------------------------------------------------
# Flask app
# ---------------------------------------------------------------------------
app = Flask(__name__)


@app.route("/version", methods=["GET"])
def get_version() -> Response:
    """Query the connected instrument for its identity."""
    try:
        with UartConnection(SERIAL_PORT, BAUD_RATE, TIMEOUT) as uart:
            response = uart.send_command("*IDN?\n")
            if response is None:
                return Response(
                    "No response from instrument (timeout or error).\n",
                    status=504,
                    mimetype="text/plain",
                )
            return Response(response + "\n", mimetype="text/plain")
    except RuntimeError as exc:
        return Response(f"UART port error: {exc}\n", status=500, mimetype="text/plain")
    except Exception as exc:
        return Response(f"Unexpected error: {exc}\n", status=502, mimetype="text/plain")


@app.route("/data", methods=["GET"])
def get_data() -> Response:
    """Return all items in the in-memory store."""
    with data_store_lock:
        return jsonify(data_store)


@app.route("/data/<int:item_id>", methods=["GET"])
def get_item(item_id: int) -> Response:
    """Return a single item by id, or 404 if not found."""
    with data_store_lock:
        item = next((i for i in data_store if i["id"] == item_id), None)
    if item is None:
        return Response("Item not found", status=404, mimetype="text/plain")
    return jsonify(item)


@app.route("/data", methods=["POST"])
def create_item() -> Response:
    """Create a new item from validated JSON data."""
    try:
        data = request.get_json(silent=True)
        if not data or "name" not in data or "done" not in data:
            return Response("Invalid data: 'name' and 'done' required.\n", status=400, mimetype="text/plain")
        if not isinstance(data["name"], str) or not data["name"]:
            return Response("Invalid data: 'name' must be a non-empty string.\n", status=400, mimetype="text/plain")
        if not isinstance(data["done"], bool):
            return Response("Invalid data: 'done' must be a boolean.\n", status=400, mimetype="text/plain")
        with data_store_lock:
            new_id = data_store[-1]["id"] + 1 if data_store else 1
            item = {"id": new_id, "name": data["name"], "done": data["done"]}
            data_store.append(item)
        return jsonify(item), 201
    except Exception as exc:
        return Response(f"Error creating item: {exc}\n", status=502, mimetype="text/plain")


# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _shutdown(signum, frame):
    print("\n[Shutdown] Received signal, closing UART and stopping web service...")
    app.stop()
    print("[Shutdown] Web service stopped.")


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Start Flask in a background thread so the UART connection can be
    # established before the service is fully ready.
    import threading
    web_thread = threading.Thread(target=app.run, args=(WEB_HOST, WEB_PORT, False), daemon=True)
    web_thread.start()
    print(f"[Main] Web service started on {WEB_HOST}:{WEB_PORT}")

    # Wait for Flask to be ready (or for a shutdown signal).
    deadline = time.monotonic() + 5.0
    while web_thread.is_alive() and _running:
        if time.monotonic() > deadline:
            print("[Main] Flask did not start within 5 s; continuing anyway.")
            break
        time.sleep(0.1)

    # Open UART once the web service is up and running.
    try:
        with UartConnection(SERIAL_PORT, BAUD_RATE, TIMEOUT) as uart:
            print(f"[Main] UART opened on {SERIAL_PORT} @ {BAUD_RATE} baud.")
            # Keep the port open until a shutdown signal arrives.
            while _running:
                time.sleep(0.5)
    except Exception as exc:
        print(f"[Main] Fatal error: {exc}")
    finally:
        print("[Main] Exiting.")


if __name__ == "__main__":
    main()

